window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0082", [{"word":"gestational","ipa_uk":"/ˌdʒesˈteɪʃənəl/","ipa_us":"/ˌdʒesˈteɪʃənəl/","definition_zh":"妊娠期的；按孕期长短来衡量的","definition_en":"relating to the period in which a young mammal develops inside its mother before birth","core_image":"一张按周编号的产检表格，每一格代表胎儿在母体内长成的一段路","scene":"产检室里，医生摊开一张按周编号的表格，逐格核对胎儿的发育进度。 The clinic keeps a chart of gestational age so that every scan can be compared with the expected range.","sceneCN":"这里 gestational 指「按怀孕时长来衡量的」（第 1 个义项：以孕周为尺度来描述孕期）；句意为诊所保留一张孕龄记录表，以便每次检查都能与预期范围对照。","pos":[{"tag":"adj.","zh":"妊娠（期）的；孕期的；按孕周计算的"}],"collocations":[{"phrase":"gestational age","zh":"孕龄；胎龄"},{"phrase":"gestational diabetes","zh":"妊娠糖尿病"},{"phrase":"gestational week","zh":"孕周"},{"phrase":"gestational sac","zh":"孕囊"},{"phrase":"gestational carrier","zh":"代孕母体"},{"phrase":"gestational hypertension","zh":"妊娠高血压"}],"forms":[{"label":"原级","form":"gestational"},{"label":"比较级","form":"more gestational"},{"label":"最高级","form":"most gestational"},{"label":"派生副词","form":"gestationally"},{"label":"同根名词","form":"gestation"},{"label":"同根动词","form":"gestate"}],"derivatives":[{"word":"gestation","pos":"n.","zh":"妊娠期；孕育过程"},{"word":"gestate","pos":"v.","zh":"孕育；怀胎"},{"word":"gestating","pos":"adj.","zh":"孕育中的"},{"word":"gestational","pos":"adj.","zh":"妊娠期的"}],"senses":[{"no":"01","title":"Measured by length of pregnancy","titleCN":"按怀孕时长来衡量的","definition":"relating to the length of time an unborn mammal has been developing","definitionCN":"与未出生幼体已经发育的时长有关","example":"The clinic records gestational age in weeks at every visit.","exampleCN":"诊所每次就诊都以周为单位记录孕龄。","why":"gestational is the adjective of gestation, which in Latin means 'a carrying'; the suffix -al turns that carrying period into a defining attribute.","whyCN":"gestational 是 gestation 的形容词，后者在拉丁语中意为「背负、运送」；后缀 -al 把这段「怀着的时期」变成事物的限定属性。"},{"no":"02","title":"Belonging to the unborn stage","titleCN":"属于胎儿发育阶段的","definition":"belonging to the stage of development of the unborn young rather than to the mother","definitionCN":"属于未出生幼体自身的发育阶段，而非母亲的状态","example":"Gestational development in the first trimester is mostly organ formation.","exampleCN":"孕早期的胎儿发育主要是器官形成。","why":"the word shifts attention from the carrier to what is being carried, because gestation names both the carrying and the thing carried.","whyCN":"这个词把注意力从承载者移向被承载者，因为 gestation 同时指「怀着」这件事与被怀着的对象。"},{"no":"03","title":"Of disorders that start with pregnancy","titleCN":"孕期才出现的病症（如妊娠糖尿病）","definition":"used of medical conditions that arise because of pregnancy rather than before it","definitionCN":"用于描述因怀孕而出现、怀孕前并不存在的疾病","example":"Gestational diabetes usually disappears after delivery.","exampleCN":"妊娠糖尿病通常在分娩后消失。","why":"such conditions exist only during the carrying period, so the adjective marks pregnancy as their cause and their time limit.","whyCN":"这类疾病只存在于怀孕期内，形容词因此既标明孕期的起因，也标明它的时限。"},{"no":"04","title":"Counted from the last menstrual period","titleCN":"以末次月经为起点计算的","definition":"counted from the last menstrual period rather than from conception","definitionCN":"从末次月经起算，而不是从受孕起算","example":"By gestational dating, the pregnancy is two weeks older than the embryo.","exampleCN":"按孕龄推算，孕期比胚胎本身的实际周数多两周。","why":"clinical counting starts before conception because the exact moment of fertilisation is unknown, so the adjective follows the calendar doctors actually use.","whyCN":"临床计算从受孕之前开始，因为受精的确切时刻无法确定，形容词于是跟随医生实际使用的日历。"},{"no":"05","title":"Of a person carrying another's pregnancy","titleCN":"代孕的；替他人怀孕的","definition":"describing a person who carries a pregnancy for someone else","definitionCN":"描述替他人怀胎的人","example":"The gestational carrier has no genetic link to the child.","exampleCN":"代孕母体与孩子没有基因联系。","why":"the emphasis falls on the carrying work alone, which is exactly what distinguishes a carrier from a genetic parent.","whyCN":"重点只落在「怀胎」这件工作上，而这正是代孕母体与基因父母的分界。"},{"no":"06","title":"Of structures visible in early scans","titleCN":"早期超声可见结构的（如孕囊）","definition":"used of the early structures that mark where the pregnancy is implanted","definitionCN":"用于描述标示胚胎着床位置的早期结构","example":"The sonographer located a gestational sac inside the uterus.","exampleCN":"超声医师在子宫内找到了孕囊。","why":"these structures belong to the pregnancy as a whole, not to the embryo alone, so the adjective attaches them to the gestational period.","whyCN":"这些结构属于整个妊娠而非单独的胚胎，形容词因此把它们系在孕期的整体上。"},{"no":"07","title":"Of pregnancy length in other mammals","titleCN":"其他哺乳动物孕期的","definition":"used of the carrying period in mammals other than humans","definitionCN":"用于人类以外哺乳动物的怀胎时长","example":"Gestational length in elephants approaches two years.","exampleCN":"大象的孕期接近两年。","why":"the Latin root describes any animal carrying young, so the adjective extends naturally to zoology.","whyCN":"拉丁词根本来就指任何动物怀胎，形容词因此自然延伸到动物学。"},{"no":"08","title":"Of a slow period before something emerges","titleCN":"比喻：事物成形前的酝酿期","definition":"figurative, of the slow period during which an idea or project takes shape before it appears","definitionCN":"比喻用法，指想法或项目成形、露面之前的缓慢酝酿期","example":"The policy had a long gestational phase before anyone saw a draft.","exampleCN":"这项政策在任何人看到草案之前经过了漫长的酝酿期。","why":"the abstract sense keeps the shape of the literal one: something invisible grows at its own pace until it can be shown.","whyCN":"抽象义保留了字面义的形状：看不见的东西按自己的节奏成长，直到可以示人。"}],"etymology":{"intro":{"en":"Gestational is the adjective of gestation, from Latin gestatio 'a carrying', built on gestare 'to carry, carry in the womb', a frequentative of gerere 'to carry, bear'. Dates are approximate.","cn":"gestational 是 gestation 的形容词，后者来自拉丁 gestatio「背负」，由 gestare「背负、怀胎」构成，而 gestare 是 gerere「携带、承担」的反复动词。年代均为约数。"},"items":[{"era":"LATIN GERERE","en":"Gerere meant 'to carry, bear, conduct', and it also underlies gesture and digest; its deeper ancestry is not settled.","cn":"gerere 意为「携带、承担、进行」，gesture 与 digest 也由它而来；它更早的来源尚无定论。"},{"era":"LATIN GESTARE","en":"Gestare is a frequentative of gerere, adding repeated or sustained carrying; the frequentative reading is generally accepted rather than proven by attestation.","cn":"gestare 是 gerere 的反复动词，加上「反复、持续地背负」的意思；这一反复体解释一般认为是正确的，但并非由书证直接证明。"},{"era":"LATIN GESTATIO","en":"Gestatio named the act of carrying, and medical Latin narrowed it to carrying young in the womb.","cn":"gestatio 指「背负」这一动作，医学拉丁语把它收窄为「在子宫中怀胎」。"},{"era":"ENGLISH GESTATION","en":"English gestation is recorded from the seventeenth century; the adjective gestational followed much later with the growth of obstetric measurement.","cn":"英语 gestation 自 17 世纪有记录；形容词 gestational 则晚得多，随产科测量方法的兴起才出现。"},{"era":"SUFFIX -AL","en":"The suffix -al, from Latin -alis, means 'pertaining to', so gestational simply means 'pertaining to gestation'.","cn":"后缀 -al 来自拉丁 -alis，意为「与……有关的」，因此 gestational 就是「与 gestation 有关的」。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date of the adjective): no firm first citation for gestational is available, and the pre-Latin origin of gerere is a reconstruction rather than a documented form.","cn":"来源不确定（形容词的首见年代）：gestational 没有可靠的最早书证；gerere 在拉丁语之前的来源属重构形式，而非有文献记录的形式。"}]},"similar":{"note":{"en":"Group one holds words that look like gestational but do not share its root; group two holds the medical time words that overlap with it in meaning.","cn":"第一组是外形相近但词根不同的词；第二组是在含义上与之重叠的医学时间词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gestalt","ipa":"/ɡeˈʃtɑːlt/","tag":"German, different root","definition":"A German noun for an organised whole whose parts cannot be understood separately; it has no Latin root and no link to gestation.","definitionCN":"德语名词，指各部分不能分开理解的整体；没有拉丁词根，与 gestation 无关。"},{"word":"gesture","ipa":"/ˈdʒestʃə/","tag":"same root, different branch","definition":"From Latin gestura, built on gestus, the past participle of gerere; it shares the root with gestation but means a bodily movement used to express meaning.","definitionCN":"来自拉丁 gestura，建立在 gerere 的过去分词 gestus 之上；与 gestation 同根，但指表达意思的身体动作。"},{"word":"digest","ipa":"/daɪˈdʒest/","tag":"same root, different prefix","definition":"Di- 'apart' plus gerere 'carry': to carry food apart inside the body, hence to break it down; the root is shared but the sense is unrelated.","definitionCN":"di-「分开」加 gerere「携带」：在体内把食物分开搬运，因此指消化；词根相同而词义无关。"},{"word":"congest","ipa":"/kənˈdʒest/","tag":"same root, crowded sense","definition":"Con- 'together' plus gerere: to carry things into one place until they pile up, as blood congests a tissue.","definitionCN":"con-「一起」加 gerere：把东西搬进一处直到堆积，如血液使组织充血。"}]},{"heading":"NEAR MEANING","entries":[{"word":"prenatal","ipa":"/ˌpriːˈneɪtəl/","tag":"before birth","definition":"Relating to the period before birth, usually from conception onward; broader than gestational, which measures the carrying period itself.","definitionCN":"指出生之前的时期，通常自受孕算起；比 gestational 宽，后者只量怀胎这段时长。"},{"word":"antenatal","ipa":"/ˌæntiˈneɪtəl/","tag":"British clinical word","definition":"The British medical term for care given before birth; it describes services rather than a measurement of age.","definitionCN":"英式医学用语，指产前照护；描述的是服务，而不是孕龄的计量。"},{"word":"perinatal","ipa":"/ˌperiˈneɪtəl/","tag":"around birth","definition":"Relating to the weeks just before and just after birth; it brackets the delivery rather than covering the whole pregnancy.","definitionCN":"指出生前后数周；框住分娩这一刻，而不覆盖整个孕期。"},{"word":"maternal","ipa":"/məˈtɜːnəl/","tag":"of the mother","definition":"Relating to the mother; gestational describes the time dimension, while maternal describes the person.","definitionCN":"与母亲有关；gestational 描述时间维度，maternal 描述人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real clinical phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的临床搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"gest- 'carry' + -ation + -al: the carrying period turned into an adjective.","cn":"gest-「背负」+ -ation + -al：把「怀着的时期」变成形容词。"},{"en":"The same root shows in gesture and digest, both built on Latin gerere 'carry'.","cn":"同一词根见于 gesture 与 digest，二者都建立在拉丁 gerere「携带」之上。"},{"en":"Clinical phrases fix the sense: gestational age, gestational diabetes, gestational week.","cn":"临床搭配固定了词义：孕龄、妊娠糖尿病、孕周。"},{"en":"The counting starts before conception, which is why gestational age exceeds embryo age.","cn":"计算起点在受孕之前，所以孕龄大于胚胎的实际周数。"},{"en":"The family runs gestation, gestate, gestating, gestational.","cn":"同族词包括 gestation、gestate、gestating、gestational。"}],"abstract":[{"en":"Picture a calendar with one square per week, each square holding a stage of a hidden life.","cn":"想象一本每周一格的日历，每一格里装着一段看不见的生命阶段。"},{"en":"Picture a pot kept warm on a stove for months before anyone lifts the lid.","cn":"想象一只在炉上温了几个月的锅，没有人掀开盖子。"},{"en":"Picture a manuscript sealed in a drawer until its author decides it is ready.","cn":"想象一份手稿被锁在抽屉里，直到作者认为它可以见人。"}]},"examples":[{"en":"Gestational age is estimated from the last menstrual period.","cn":"孕龄由末次月经推算。"},{"en":"She was treated for gestational diabetes in the third trimester.","cn":"她在孕晚期接受了妊娠糖尿病的治疗。"},{"en":"The study compared gestational length across mammal species.","cn":"这项研究比较了不同哺乳动物的孕期时长。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「gest（带）+ ational」——把胎儿一路带着走的时期 → 妊娠期的","word":"gestational"},"root":"拉丁 gestare「背负、怀胎」（gerere「携带」的反复动词）+ -ation + -al；gerere 更早来源属重构形式，gestare 的反复体关系一般认为是正确的。英语 gestational。","sensesIntro":{"en":"Eight senses of gestational circle one idea: a span of time defined by carrying the young, measured in weeks, split into stages, and finally stretched to cover any slow incubation.","cn":"gestational 的八个义项围绕一个观念：由「怀着幼体」定义的时段，按周计量、按阶段划分，最后延伸去指任何缓慢的酝酿。"},"semanticMap":{"core":{"en":"CORE IMAGE: a week-by-week chart of a hidden life being carried.","cn":"核心意象：一张按周记录、承载着看不见生命的表格。"},"chain":["CARRY","SPAN OF TIME","COUNT IN WEEKS","PRENATAL RISK","SURROGATE CARRIER","INCUBATION"],"branches":[{"senses":"01 · 04","en":"MEASUREMENT: the carrying span is turned into a number of weeks.","cn":"计量：把怀胎时长换算成周数。"},{"senses":"02 · 07","en":"DEVELOPING YOUNG: the focus moves from carrier to carried, in humans and in other mammals.","cn":"发育中的幼体：焦点从承载者移向被承载者，人也包括其他哺乳动物。"},{"senses":"03 · 06","en":"CLINICAL MARKS: conditions and structures exist only because the pregnancy exists.","cn":"临床标记：疾病与结构只因妊娠而存在。"},{"senses":"05","en":"CARRYING ONLY: a carrier contributes the period, not the genes.","cn":"只承担怀胎：代孕者提供的是时段，而非基因。"},{"senses":"08","en":"SLOW EMERGENCE: anything hidden can be said to have a gestational phase.","cn":"缓慢浮现：任何隐藏之物都可以说有酝酿期。"}]},"affixes":{"intro":{"en":"Gestational can be read as three pieces: a Latin root for carrying, a noun suffix, and an adjective suffix.","cn":"gestational 可以拆成三段读：表「背负」的拉丁词根、名词后缀与形容词后缀。"},"latinIntro":{"en":"Latin gerere 'to carry' yields gestare, gestatio and gestus; English draws gesture, digest, congest and gestation from the same stock.","cn":"拉丁 gerere「携带」衍生 gestare、gestatio 与 gestus；英语的 gesture、digest、congest 与 gestation 都取自这一词族。"},"items":[{"word":"gest-","structure":"gestare (Latin verb, first conjugation, frequentative of gerere)","meaning":"to carry, to carry in the womb","meaningCN":"背负；怀胎","example":"The root supplies the idea of sustained carrying.","exampleCN":"这个词根提供「持续背负」的意思。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"the act or state of doing something","meaningCN":"动作或状态","example":"Gestation names the act of carrying.","exampleCN":"gestation 指「背负」这一动作。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"pertaining to","meaningCN":"与……有关的","example":"Gestational means pertaining to gestation.","exampleCN":"gestational 意为与 gestation 有关的。"},{"word":"gestation","structure":"gestare + -ation","meaning":"the carrying of young in the womb","meaningCN":"妊娠；怀胎","example":"Gestation lasts about nine months in humans.","exampleCN":"人类的妊娠约持续九个月。"},{"word":"gestate","structure":"gestare + English verb ending","meaning":"to carry young, or to develop slowly","meaningCN":"孕育；酝酿","example":"The plan gestated for years before it was announced.","exampleCN":"这项计划在公布前酝酿了多年。"},{"word":"gestating","structure":"gestate + -ing","meaning":"currently carrying or developing","meaningCN":"正在孕育的","example":"The gestating embryo was visible on the scan.","exampleCN":"正在发育的胚胎在扫描图像上可见。"},{"word":"gestationally","structure":"gestational + -ly","meaning":"with respect to gestational age","meaningCN":"就孕龄而言","example":"The infants were grouped gestationally rather than by birth weight.","exampleCN":"这些婴儿按孕龄而非出生体重分组。"},{"word":"gestational age","structure":"gestational + age (compound term)","meaning":"the standard clinical measure of pregnancy length","meaningCN":"孕龄（临床标准计量）","example":"Gestational age is reported in completed weeks.","exampleCN":"孕龄以整周数报告。"}],"latinEntries":[{"word":"gerere","structure":"gerere, gessi, gestum (verb, third conjugation)","meaning":"to carry, bear, conduct","meaningCN":"携带；承担；进行"},{"word":"gestare","structure":"gestare, gestavi, gestatum (verb, first conjugation)","meaning":"to carry, carry in the womb","meaningCN":"背负；怀胎"},{"word":"gestatio","structure":"gestatio, gestationis (f., third declension)","meaning":"a carrying","meaningCN":"背负；怀胎"},{"word":"gestus","structure":"gestus, gestus (m., fourth declension)","meaning":"a bearing, gesture","meaningCN":"姿态；动作"}]}},{"word":"fertilization","ipa_uk":"/ˌfɜːtɪlaɪˈzeɪʃən/","ipa_us":"/ˌfɝːtələˈzeɪʃən/","definition_zh":"受精；施肥；使土地肥沃","definition_en":"the joining of a male and a female reproductive cell, or the act of making soil or water richer in nutrients","core_image":"两粒微小的种子在显微镜下合成一粒，旁边是一把撒进土里的肥料","scene":"实验台上，一枚卵细胞与一枚精子在被放入同一滴液体后开始融合。 Under the microscope, fertilization begins the moment the two membranes meet and the nuclei start to move together.","sceneCN":"这里 fertilization 指「受精」（第 1 个义项：雌雄配子融合为一）；句意为在显微镜下，两膜相触、两核开始靠拢的那一刻，受精就开始了。","pos":[{"tag":"n.","zh":"受精；受孕；施肥；使肥沃"}],"collocations":[{"phrase":"double fertilization","zh":"双受精"},{"phrase":"cross-fertilization","zh":"异花受精；相互启发"},{"phrase":"in vitro fertilization","zh":"体外受精"},{"phrase":"fertilization rate","zh":"受精率"},{"phrase":"soil fertilization","zh":"土壤施肥"},{"phrase":"external fertilization","zh":"体外受精（卵在水中受精）"}],"forms":[{"label":"原形","form":"fertilization"},{"label":"复数","form":"fertilizations"},{"label":"英式拼写","form":"fertilisation"},{"label":"同根动词","form":"fertilize"},{"label":"同根形容词","form":"fertile"},{"label":"同根名词（肥沃）","form":"fertility"}],"derivatives":[{"word":"fertilize","pos":"v.","zh":"使受精；施肥"},{"word":"fertile","pos":"adj.","zh":"肥沃的；能生育的"},{"word":"fertility","pos":"n.","zh":"肥沃；生育力"},{"word":"fertilizer","pos":"n.","zh":"肥料"},{"word":"fertilizable","pos":"adj.","zh":"可受精的；可施肥的"}],"senses":[{"no":"01","title":"Fusion of male and female cells","titleCN":"雌雄配子融合","definition":"the joining of a sperm and an egg so that a new cell is formed","definitionCN":"精子与卵子结合，形成一个新的细胞","example":"Fertilization takes place in the upper part of the oviduct.","exampleCN":"受精发生在输卵管上段。","why":"the word's core is making fruitful: two cells that alone cannot develop are joined into one that can.","whyCN":"词的核心是「使之能结果」：两个单独无法发育的细胞被合成为一个可以发育的细胞。"},{"no":"02","title":"Double fertilization in flowering plants","titleCN":"被子植物的双受精","definition":"the special case in flowering plants where two sperm fuse with two different cells","definitionCN":"开花植物中两个精细胞分别与两个不同细胞融合的特殊情形","example":"Double fertilization produces both an embryo and a nutrient store.","exampleCN":"双受精同时产生胚胎与营养储备。","why":"the same fusion event happens twice in one visit, so the general name is kept and qualified as double.","whyCN":"同一次融合事件在一回访问中发生两次，因此沿用通名并加「双」字限定。"},{"no":"03","title":"Fertilization outside the body","titleCN":"体外受精（卵在水中受精）","definition":"the joining of gametes in open water rather than inside a body","definitionCN":"配子在开放水域而非母体内结合","example":"External fertilization is common in fish and amphibians.","exampleCN":"体外受精在鱼类与两栖类中很常见。","why":"the process is the same, only the place changes, so the noun needs an adjective to say where the fusion happens.","whyCN":"过程相同，改变的只是地点，因此名词需要一个形容词来指明融合发生的位置。"},{"no":"04","title":"Deliberate joining in farming","titleCN":"农业上的人工授精或人工授粉","definition":"the controlled joining of gametes by people, as in breeding or orchard work","definitionCN":"由人控制配子的结合，如育种或果园作业","example":"Artificial fertilization let the breeders combine two distant lines.","exampleCN":"人工授精让育种者把两个相距很远的品系组合起来。","why":"human hands take over the moment when cells would otherwise meet by chance.","whyCN":"人手接管了细胞原本靠偶然相遇的那个时刻。"},{"no":"05","title":"Adding nutrients to soil","titleCN":"给土壤施肥","definition":"the act of adding nutrients to soil so that crops grow better","definitionCN":"向土壤添加养分，使作物长得更好","example":"Balanced fertilization raised the yield without polluting the stream.","exampleCN":"平衡施肥既提高了产量，又没有污染小溪。","why":"Latin fertilis means 'fruitful', so making soil fruitful is the most literal non-biological use of the noun.","whyCN":"拉丁 fertilis 意为「能结果的」，因此「使土壤能结果」正是这个名词最直接的非生物学用法。"},{"no":"06","title":"Enriching a body of water","titleCN":"水体富营养化（给水体加养分）","definition":"the addition of nutrients to a lake or sea, whether intended or accidental","definitionCN":"向湖泊或海洋添加养分，无论有意还是意外","example":"Runoff from the fields caused heavy fertilization of the lake.","exampleCN":"田地的径流造成湖泊严重富营养化。","why":"water can be made fruitful in the same sense as soil, and too much fruitfulness becomes pollution.","whyCN":"水也能像土壤一样被「使之肥沃」，而肥沃过头便成了污染。"},{"no":"07","title":"Cross-fertilization of ideas","titleCN":"比喻：思想的相互启发","definition":"the exchange between two fields or people that makes both more productive","definitionCN":"两个领域或两个人之间的交流，使双方都更有产出","example":"Cross-fertilization between genetics and computing reshaped both fields.","exampleCN":"遗传学与计算科学的相互启发重塑了这两个领域。","why":"the metaphor borrows the botanical event: what one field carries can make another field fruitful.","whyCN":"这个比喻借用了植物学事件：一方携带的东西能让另一方结果。"},{"no":"08","title":"The beginning of a pregnancy","titleCN":"受孕，怀孕的开端","definition":"the event taken as the start of a pregnancy","definitionCN":"被视为怀孕起点的那一事件","example":"The date of fertilization fixes the start of the pregnancy.","exampleCN":"受精的日期决定了怀孕的起点。","why":"once the fused cell begins to divide, a new individual exists, so the fusion becomes a milestone rather than a process.","whyCN":"融合后的细胞一旦开始分裂，新的个体就存在了，融合于是从过程变成里程碑。"}],"etymology":{"intro":{"en":"Fertilization is the noun of fertilize, from Medieval Latin fertilizare and earlier fertilis 'fruitful', which is built on ferre 'to bear, carry'. Dates are approximate.","cn":"fertilization 是 fertilize 的名词，来自中世纪拉丁 fertilizare，更早的 fertilis 意为「能结果的」，由 ferre「承载、生育」构成。年代均为约数。"},"items":[{"era":"LATIN FERRE","en":"Ferre meant 'to bear, carry, bring'; the same root yields transfer, refer and fertile, where bearing becomes bearing fruit.","cn":"ferre 意为「承载、带来」；同一词根衍生 transfer、refer 与 fertile，后者把「承载」变成「结果」。"},{"era":"LATIN FERTILIS","en":"Fertilis 'fruitful, productive' is generally taken as ferre plus -ilis, 'able to bear'; the derivation is accepted but the intermediate form is not attested.","cn":"fertilis「能结果的、丰产的」一般认为是 ferre 加 -ilis「能够……」构成；这一派生被接受，但中间形式没有书证。"},{"era":"MEDIEVAL LATIN","en":"Fertilizare appears in medieval Latin for making land productive; the agricultural sense is the oldest English one.","cn":"fertilizare 见于中世纪拉丁语，指使土地丰产；这一农业义也是英语中最早的用法。"},{"era":"ENGLISH FERTILIZE","en":"English fertilize is recorded from the seventeenth century, first of land and later of the egg.","cn":"英语 fertilize 自 17 世纪有记录，先用于土地，后用于卵细胞。"},{"era":"BIOLOGICAL SHIFT","en":"The biological sense grew in the eighteenth and nineteenth centuries as the cell theory made the fusion of gametes visible.","cn":"随着细胞学说让配子融合变得可见，生物学义在 18、19 世纪发展起来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact year when fertilization was first used of gametes is not firmly established; forms and dates here are approximate.","cn":"来源不确定（首见年代）：fertilization 首次用于配子的确切年份尚无定论，此处形式与年代均为约数。"}]},"similar":{"note":{"en":"Group one separates the -fer- words that look alike but carry different prefixes; group two separates the reproductive terms around the same event.","cn":"第一组区分外形相近但前缀不同的 -fer- 词；第二组区分描述同一事件的其他生殖术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fertility","ipa":"/fəˈtɪləti/","tag":"quality, not event","definition":"The noun for being fertile; it names a capacity or a rate, while fertilization names the joining event itself.","definitionCN":"指「肥沃、能生育」这一性质的名词；它描述能力或比率，而 fertilization 指结合事件本身。"},{"word":"fertilizer","ipa":"/ˈfɜːtɪlaɪzə/","tag":"the substance","definition":"The material spread on land, formed with -er 'thing that does'; it is the input, not the act.","definitionCN":"撒在土地上的物质，由 -er「做某事之物」构成；它是投入物，而不是动作。"},{"word":"fertilize","ipa":"/ˈfɜːtɪlaɪz/","tag":"the verb","definition":"The verb behind the noun; English verbs in -ize often come with nouns in -ization, which is exactly the pair here.","definitionCN":"名词背后的动词；英语中以 -ize 结尾的动词常配 -ization 名词，这里正是这一对。"},{"word":"confer","ipa":"/kənˈfɜː/","tag":"different prefix","definition":"Con- 'together' plus ferre: to bring things together, hence to consult or to grant; the root is shared but the prefix changes the meaning completely.","definitionCN":"con-「一起」加 ferre：把东西带到一处，因此指商议或授予；词根相同，但前缀彻底改变了词义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"conception","ipa":"/kənˈsepʃən/","tag":"the moment of becoming pregnant","definition":"The beginning of a pregnancy as a state; fertilization is the cellular event that conception names from the outside.","definitionCN":"怀孕状态的开端；fertilization 是细胞层面的事件，conception 是从外部对这一事件的命名。"},{"word":"pollination","ipa":"/ˌpɒlɪˈneɪʃən/","tag":"pollen transfer, not fusion","definition":"The transfer of pollen to the stigma, which must happen before fertilization in flowering plants; the two are stages, not synonyms.","definitionCN":"花粉落到柱头的过程；在开花植物中它必须先于受精发生，二者是阶段，不是同义词。"},{"word":"insemination","ipa":"/ˌɪnsiˈmeɪʃən/","tag":"delivery of semen","definition":"The placing of semen in the reproductive tract; it may or may not be followed by fertilization.","definitionCN":"把精液送入生殖道；之后可能受精，也可能不受精。"},{"word":"impregnation","ipa":"/ˌɪmpreɡˈneɪʃən/","tag":"result, not fusion","definition":"The state of being made pregnant, or the saturation of a material; it describes the outcome rather than the cellular joining.","definitionCN":"被致孕的状态，或材料被浸透；它描述结果，而非细胞层面的结合。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real agricultural and biological phrases, and real relatives.","cn":"正常联想：真实的构词成分、真实的农业与生物学搭配以及真实同族词。"},"normal":[{"en":"fer- 'bear' + -tilis 'able' + -ization: making something able to bear.","cn":"fer-「承载」+ -tilis「能够」+ -ization：使某物能够结果。"},{"en":"The same root appears in transfer, refer, offer and fertile, all about carrying.","cn":"同一词根见于 transfer、refer、offer 与 fertile，都与「携带」有关。"},{"en":"Two fields of use share one word: soil is fertilized, and so is an egg.","cn":"两个领域共用一个词：土壤被施肥，卵细胞被受精。"},{"en":"Fixed phrases mark the biology: double fertilization, external fertilization, in vitro fertilization.","cn":"固定搭配标出生物学义：双受精、体外受精、试管内受精。"},{"en":"The family runs fertile, fertility, fertilize, fertilizer, fertilization.","cn":"同族词包括 fertile、fertility、fertilize、fertilizer、fertilization。"}],"abstract":[{"en":"Picture two half-seeds that cannot grow alone, pressed into one whole seed.","cn":"想象两粒单独都长不起来的半颗种子，被压成一粒完整的种子。"},{"en":"Picture a field made rich by something carried in from elsewhere.","cn":"想象一块田，因为从别处运来的东西而变得肥沃。"},{"en":"Picture two research labs swapping tools until both can build what neither could alone.","cn":"想象两个实验室交换工具，直到双方都能造出各自原本造不出的东西。"}]},"examples":[{"en":"Fertilization usually occurs within a day of ovulation.","cn":"受精通常在排卵后一天内发生。"},{"en":"Excess fertilization turned the pond green with algae.","cn":"过量的养分输入使池塘因藻类而变绿。"},{"en":"Cross-fertilization of the two traditions produced a new style.","cn":"两种传统的相互启发产生了一种新风格。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fer（带来）+ til（能够）+ ization」——让卵子和土地都能「结果」→ 受精、施肥","word":"fertilization"},"root":"拉丁 fertilis「能结果的」= ferre「承载、生育」+ -ilis「能够」；中世纪拉丁 fertilizare；英语 fertilization。ferre 的印欧来源一般认为是 *bher-，属重构形式。","sensesIntro":{"en":"Eight senses of fertilization follow one move: two things that could not develop alone are joined or fed so that something new can grow.","cn":"fertilization 的八个义项沿同一个动作展开：两个单独无法发展的东西被结合或供养，于是有新的事物能够生长。"},"semanticMap":{"core":{"en":"CORE IMAGE: two half-cells meeting so that a third, living cell can begin.","cn":"核心意象：两个半个细胞相遇，于是第三个活细胞得以开始。"},"chain":["CELL FUSION","NEW CELL","DOUBLE EVENT","OUTSIDE THE BODY","NUTRIENT INPUT","RICHER MEDIUM"],"branches":[{"senses":"01 · 08","en":"BEGINNING: the fusion is also the calendar start of a pregnancy.","cn":"开端：融合同时是怀孕的日历起点。"},{"senses":"02 · 03","en":"ROUTES: fusion can happen twice in a flower or outside the body in water.","cn":"路径：融合可以在花中发生两次，也可以在体外的水中发生。"},{"senses":"04","en":"BY HAND: people can arrange the meeting that would otherwise be chance.","cn":"由人安排：人能让原本靠偶然的相遇被安排出来。"},{"senses":"05 · 06","en":"FEEDING: soil and water are made fruitful in the same literal sense.","cn":"供养：土壤与水在同样直接的意义上被「使之结果」。"},{"senses":"07","en":"IDEA CROSSING: a metaphor keeps only the fruitful-contact part.","cn":"思想交汇：比喻只保留「接触而生果」这一部分。"}]},"affixes":{"intro":{"en":"Fertilization is root plus two suffixes, and the same root builds a large family of carrying words.","cn":"fertilization 是词根加两个后缀，同一词根还构成一大批表「携带」的词。"},"latinIntro":{"en":"Latin ferre 'to bear' yields fertilis, fertilizare and fertilization; English transfer, refer, offer and fertile all descend from the same verb.","cn":"拉丁 ferre「承载」衍生 fertilis、fertilizare 与 fertilizatio；英语 transfer、refer、offer 与 fertile 都出自同一动词。"},"items":[{"word":"fer-","structure":"ferre (Latin verb, irregular)","meaning":"to bear, carry, bring","meaningCN":"承载；带来；生育","example":"The root supplies the idea of bearing fruit.","exampleCN":"这个词根提供「结果实」的意思。"},{"word":"-tilis","structure":"-tilis (Latin adjective suffix)","meaning":"able to, fit for","meaningCN":"能够……的；适于……的","example":"Fertilis literally reads as 'able to bear'.","exampleCN":"fertilis 字面读作「能够承载的」。"},{"word":"-ize","structure":"-izare (via Greek -izein)","meaning":"to make or cause","meaningCN":"使……；使成为","example":"Fertilize means to make fruitful.","exampleCN":"fertilize 意为使结果。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"the act or result of","meaningCN":"动作或结果","example":"Fertilization names the act of making fruitful.","exampleCN":"fertilization 指「使之结果」这一动作。"},{"word":"fertilize","structure":"fertilis + -ize","meaning":"to make fertile, or to join gametes","meaningCN":"施肥；使受精","example":"Farmers fertilize the field in early spring.","exampleCN":"农民在早春给田地施肥。"},{"word":"fertilizer","structure":"fertilize + -er","meaning":"a substance that makes land fruitful","meaningCN":"肥料","example":"The bag of fertilizer was stored away from the well.","exampleCN":"那袋肥料存放在远离水井的地方。"},{"word":"fertile","structure":"ferre + -tilis","meaning":"able to produce young or crops","meaningCN":"能生育的；肥沃的","example":"The river valley has unusually fertile soil.","exampleCN":"这条河谷的土壤异常肥沃。"},{"word":"fertility","structure":"fertile + -ity","meaning":"the quality of being fruitful","meaningCN":"肥沃；生育力","example":"Soil fertility depends on organic matter.","exampleCN":"土壤肥力取决于有机质。"},{"word":"fertilizable","structure":"fertilize + -able","meaning":"able to be fertilized","meaningCN":"可受精的；可施肥的","example":"Only a fertilizable egg can accept a sperm.","exampleCN":"只有可受精的卵才能接受精子。"}],"latinEntries":[{"word":"ferre","structure":"ferre, tuli, latum (verb, irregular)","meaning":"to bear, carry, bring","meaningCN":"承载；带来"},{"word":"fertilis","structure":"fertilis, fertile (adjective, third declension)","meaning":"fruitful, productive","meaningCN":"能结果的；丰产的"},{"word":"fertilizare","structure":"fertilizare (verb, Medieval Latin, first conjugation)","meaning":"to make fruitful","meaningCN":"使结果；使丰产"},{"word":"fertilizatio","structure":"fertilizatio, fertilizationis (f., Medieval Latin, third declension)","meaning":"a making fruitful","meaningCN":"使结果；施肥"}]}},{"word":"fertilize","ipa_uk":"/ˈfɜːtɪlaɪz/","ipa_us":"/ˈfɝːtəlaɪz/","definition_zh":"使受精；给……施肥；使肥沃","definition_en":"to join a male and a female cell, or to add nutrients to soil, water or a growing medium","core_image":"一只手把肥料撒进田垄，另一只手在显微镜下把精子送到卵子旁边","scene":"果园里，工人用软毛刷把花粉从一株花移到另一株花的柱头上。 Growers fertilize the rows by hand when the bees are too few to do the work.","sceneCN":"这里 fertilize 指「使（花）受精、给花授粉」（第 5 个义项：人为把配子送到位）；句意为当蜜蜂太少、干不了这活时，种植者就人工给这几行花授粉。","pos":[{"tag":"vt.","zh":"使受精；使受孕；给……施肥；使肥沃"},{"tag":"vi.","zh":"（土地）变得肥沃"}],"collocations":[{"phrase":"fertilize the soil","zh":"给土壤施肥"},{"phrase":"fertilize an egg","zh":"使卵子受精"},{"phrase":"fertilize a field","zh":"给田地施肥"},{"phrase":"fertilize flowers","zh":"给花授粉"},{"phrase":"fertilize a lake","zh":"使湖泊富营养化"},{"phrase":"fertilize with manure","zh":"用厩肥施肥"}],"forms":[{"label":"三单（he/she/it）","form":"fertilizes"},{"label":"过去式","form":"fertilized"},{"label":"过去分词","form":"fertilized"},{"label":"现在分词","form":"fertilizing"},{"label":"英式拼写","form":"fertilise"},{"label":"名词（受精；施肥）","form":"fertilization"}],"derivatives":[{"word":"fertilization","pos":"n.","zh":"受精；施肥"},{"word":"fertilizer","pos":"n.","zh":"肥料"},{"word":"fertile","pos":"adj.","zh":"肥沃的；能生育的"},{"word":"fertility","pos":"n.","zh":"肥沃；生育力"},{"word":"self-fertilize","pos":"v.","zh":"自花受精；自体受精"}],"senses":[{"no":"01","title":"Add nutrients to soil","titleCN":"给土壤施肥","definition":"to add substances to soil so that crops grow better","definitionCN":"向土壤添加物质，使作物长得更好","example":"They fertilize the vegetable beds every autumn.","exampleCN":"他们每年秋天给菜畦施肥。","why":"the -ize suffix means 'make', and the root means 'fruitful', so fertilize reads as 'make fruitful'.","whyCN":"后缀 -ize 意为「使」，词根意为「能结果的」，因此 fertilize 读作「使之结果」。"},{"no":"02","title":"Enrich a body of water","titleCN":"给水体加养分","definition":"to add nutrients to a lake, pond or sea","definitionCN":"向湖泊、池塘或海洋添加养分","example":"Farm runoff fertilizes the bay every spring.","exampleCN":"农场的径流每年春天给海湾带来养分。","why":"water is treated exactly like soil: something is added so that growth increases, whether wanted or not.","whyCN":"水被完全当作土壤处理：加入某种东西使生长增加，无论这是否是想要的结果。"},{"no":"03","title":"Join a sperm with an egg","titleCN":"使卵子受精","definition":"to cause a female reproductive cell to fuse with a male one","definitionCN":"使雌性生殖细胞与雄性生殖细胞融合","example":"A single sperm fertilizes the egg within hours of ovulation.","exampleCN":"排卵后数小时内，一枚精子使卵子受精。","why":"the verb takes the egg as its object and the sperm as its instrument, so the egg is what becomes fruitful.","whyCN":"这个动词以卵为宾语、以精子为工具，因此变得「能结果」的是卵。"},{"no":"04","title":"Make a female animal pregnant","titleCN":"使雌性动物受孕","definition":"to cause a female animal to conceive, as in breeding","definitionCN":"使雌性动物怀孕，如育种中所为","example":"The stallion fertilized eleven mares that season.","exampleCN":"那匹公马在那个季节使十一匹母马受孕。","why":"in animal husbandry the outcome matters more than the cell event, so the verb stands for the whole successful mating.","whyCN":"在畜牧中结果比细胞事件更重要，动词因此代表整个成功的交配过程。"},{"no":"05","title":"Move pollen to a flower","titleCN":"给花授粉","definition":"to bring pollen to the stigma of a flower, by hand or by a chosen insect","definitionCN":"把花粉送到花的柱头上，靠人工或选定的昆虫","example":"Workers fertilize the vanilla flowers with a small wooden needle.","exampleCN":"工人用小木针给香草花授粉。","why":"in flowering plants the pollen must arrive before fusion can happen, so the verb covers the delivery stage too.","whyCN":"在开花植物中，花粉必须先到达才可能融合，因此这个动词也覆盖了投递阶段。"},{"no":"06","title":"Make land productive","titleCN":"使土地肥沃、丰产","definition":"to improve land so that it can support more growth","definitionCN":"改良土地，使其能支撑更多生长","example":"Decades of flooding fertilized the delta.","exampleCN":"数十年的洪水使这片三角洲变得肥沃。","why":"this sense drops the nutrient material and keeps only the result: land that bears more than before.","whyCN":"这一义项去掉了养分材料，只保留结果：土地比从前结出更多东西。"},{"no":"07","title":"Enrich the mind or imagination","titleCN":"比喻：丰富、激发思想与想像","definition":"to supply something that makes a mind or a plan more productive","definitionCN":"提供某种东西，使头脑或计划更有产出","example":"Travel fertilized her imagination more than any classroom did.","exampleCN":"旅行比任何课堂都更能激发她的想像力。","why":"the metaphor transfers the soil gesture to thought: an outside substance is added and growth follows.","whyCN":"这个比喻把给土壤的动作移到思想上：加入外在之物，随后便有生长。"},{"no":"08","title":"Feed a laboratory medium","titleCN":"给培养基加养分","definition":"to add nutrients to a medium in which cells or plants are grown","definitionCN":"向培养细胞或植物的介质中添加养分","example":"The team fertilized the culture medium with trace minerals.","exampleCN":"团队向培养基中添加微量元素。","why":"a medium is a manufactured soil, so the agricultural verb fits it without any change of sense.","whyCN":"培养基是人造的土壤，因此农业动词原样适用，词义不需改变。"}],"etymology":{"intro":{"en":"Fertilize comes from Medieval Latin fertilizare, built on fertilis 'fruitful', itself ferre 'to bear' plus -ilis 'able'. Dates are approximate.","cn":"fertilize 来自中世纪拉丁 fertilizare，建立在 fertilis「能结果的」之上，后者由 ferre「承载」加 -ilis「能够」构成。年代均为约数。"},"items":[{"era":"LATIN FERRE","en":"Ferre 'to bear, carry' is the source of fertile as well as of transfer and refer.","cn":"ferre「承载、生育」既是 fertile 的来源，也是 transfer 与 refer 的来源。"},{"era":"LATIN FERTILIS","en":"Fertilis 'fruitful' is generally explained as ferre plus -ilis, 'able to bear'; the intermediate adjective is not attested in surviving texts.","cn":"fertilis「能结果的」一般解释为 ferre 加 -ilis「能够承载」；这个中间形容词在现存文献中没有书证。"},{"era":"MEDIEVAL LATIN","en":"Fertilizare meant 'to make fruitful' and was applied to land long before it was applied to gametes.","cn":"fertilizare 意为「使之结果」，用于土地远早于用于配子。"},{"era":"ENGLISH VERB","en":"English fertilize appears in the seventeenth century in agricultural writing, then spreads to biology in the eighteenth and nineteenth.","cn":"英语 fertilize 于 17 世纪出现在农业写作中，18、19 世纪扩展到生物学。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first biological date): the first use of the verb for the union of gametes is not precisely dated; the agricultural record is clearer than the biological one.","cn":"来源不确定（生物学义的首见年代）：这个动词首次用于配子结合的时间没有确切记载；农业用法的记录比生物学用法更清楚。"}]},"similar":{"note":{"en":"Group one separates the -fer- verbs that differ only by prefix; group two separates verbs of supplying from verbs of joining.","cn":"第一组区分只靠前缀不同的 -fer- 动词；第二组区分「供给」类动词与「结合」类动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ferment","ipa":"/fəˈment/","tag":"different root","definition":"From Latin fermentum 'leaven', not from ferre; it means to break down sugars, so the shared fer- is a coincidence of spelling.","definitionCN":"来自拉丁 fermentum「酵素」，并非出自 ferre；意为分解糖分，因此相同的 fer- 只是拼写巧合。"},{"word":"foment","ipa":"/ˈfəʊment/","tag":"heat, not fruitfulness","definition":"From Latin fomentum 'a warm application'; it means to stir up trouble or apply warmth, with no link to fertility.","definitionCN":"来自拉丁 fomentum「热敷物」；意为煽动或热敷，与肥沃无关。"},{"word":"confer","ipa":"/kənˈfɜː/","tag":"different prefix","definition":"Con- 'together' plus ferre: to bring together in speech, hence to consult or bestow.","definitionCN":"con-「一起」加 ferre：在言语中带到一处，因此指商议或授予。"},{"word":"defer","ipa":"/dɪˈfɜː/","tag":"different prefix","definition":"De- 'away' plus ferre: to carry something away to a later time, hence to postpone.","definitionCN":"de-「离开」加 ferre：把某事搬到以后的时间，因此指推迟。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nourish","ipa":"/ˈnɜːrɪʃ/","tag":"supply food","definition":"To supply what a living thing needs to grow; it names the feeding, while fertilize names making the medium fruitful.","definitionCN":"提供生物生长所需之物；它指喂养，而 fertilize 指使介质变得肥沃。"},{"word":"pollinate","ipa":"/ˈpɒlɪneɪt/","tag":"pollen delivery only","definition":"To transfer pollen to a stigma; this is the delivery step, while fertilize covers the fusion that follows.","definitionCN":"把花粉送到柱头；这是投递步骤，而 fertilize 覆盖其后的融合。"},{"word":"inseminate","ipa":"/ɪnˈsemɪneɪt/","tag":"place semen","definition":"To introduce semen into the reproductive tract by technical means; fertilization may follow or may not.","definitionCN":"用技术手段把精液送入生殖道；之后可能受精，也可能不受精。"},{"word":"enrich","ipa":"/ɪnˈrɪtʃ/","tag":"general improvement","definition":"A general verb for adding value or nutrients; it lacks the specific 'bearing fruit' image of fertilize.","definitionCN":"泛指增加价值或养分；缺少 fertilize 那种「结果实」的具体意象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real farm and lab phrases, and real relatives.","cn":"正常联想：真实的构词成分、真实的农事与实验搭配以及真实同族词。"},"normal":[{"en":"fer- 'bear' + -tilis 'able' + -ize 'make': to make able to bear.","cn":"fer-「承载」+ -tilis「能够」+ -ize「使」：使能够承载、结果。"},{"en":"Soil, water, eggs, flowers and culture media can all take the same verb.","cn":"土壤、水、卵、花与培养基都能接受同一个动词。"},{"en":"Fixed phrases: fertilize the soil, fertilize an egg, fertilize with manure.","cn":"固定搭配：给土壤施肥、使卵受精、用厩肥施肥。"},{"en":"The noun pair is regular: fertilize gives fertilization, as -ize gives -ization.","cn":"名词配对很规则：fertilize 派生 fertilization，正如 -ize 派生 -ization。"},{"en":"The family runs fertile, fertility, fertilizer, fertilization, self-fertilize.","cn":"同族词包括 fertile、fertility、fertilizer、fertilization、self-fertilize。"}],"abstract":[{"en":"Picture a hand tipping a jar of richness into a field of thin soil.","cn":"想象一只手把一罐养分倒进贫瘠的田里。"},{"en":"Picture a gardener carrying pollen on a brush as if delivering a letter.","cn":"想象园丁用刷子带着花粉，像在投递一封信。"},{"en":"Picture a mind that reads widely and then produces ideas it could not produce before.","cn":"想象一个广泛阅读的头脑，随后产出它原本产不出的想法。"}]},"examples":[{"en":"Farmers fertilize the fields before the spring rains.","cn":"农民在春雨之前给田地施肥。"},{"en":"The bees fertilize the apple trees as they gather nectar.","cn":"蜜蜂采蜜时给苹果树授粉。"},{"en":"Too much runoff fertilized the pond and choked it with weeds.","cn":"过多的径流给池塘带来了养分，杂草因此疯长。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fer（带来）+ til（能够）+ ize（使）」——使卵子或土地能够结果 → 使受精、施肥","word":"fertilize"},"root":"拉丁 fertilis「能结果的」= ferre「承载、生育」+ -ilis「能够」；中世纪拉丁 fertilizare「使结果」；英语 fertilize。ferre 的印欧来源一般认为是 *bher-，属重构形式。","sensesIntro":{"en":"Eight senses of fertilize all perform one act: something is supplied or brought together so that growth becomes possible.","cn":"fertilize 的八个义项都在做同一件事：供给或促成结合，使生长成为可能。"},"semanticMap":{"core":{"en":"CORE IMAGE: a handful of richness dropped into a medium that could not otherwise bear much.","cn":"核心意象：一把养分落进原本长不出多少东西的介质。"},"chain":["ADD NUTRIENT","MAKE FRUITFUL","JOIN CELLS","DELIVER POLLEN","IMPREGNATE","ENRICH"],"branches":[{"senses":"01 · 02 · 08","en":"FEEDING A MEDIUM: soil, water and culture medium are all enriched the same way.","cn":"喂养介质：土壤、水与培养基都以同样方式被加料。"},{"senses":"03 · 04","en":"JOINING LIVES: one cell meets another, with conception as the animal result.","cn":"生命的结合：一个细胞遇见另一个，在动物身上便成为受孕。"},{"senses":"05","en":"DELIVERY FIRST: pollen has to arrive before any fusion can occur.","cn":"先投递：花粉必须先到，融合才可能发生。"},{"senses":"06","en":"RESULT WITHOUT MATERIAL: land can simply become more productive.","cn":"无料之果：土地可以只是变得更能出产。"},{"senses":"07","en":"MIND AS SOIL: thought is enriched by what is brought in from outside.","cn":"以心为土：思想因外来之物而变得肥沃。"}]},"affixes":{"intro":{"en":"Fertilize is a Latin root plus two suffixes, and its family covers farming, biology and medicine.","cn":"fertilize 是拉丁词根加两个后缀，其词族覆盖农业、生物学与医学。"},"latinIntro":{"en":"Latin ferre 'to bear' yields fertilis and fertilizare; English adds fertilize, fertilizer, fertilization and the wider -fer- family.","cn":"拉丁 ferre「承载」衍生 fertilis 与 fertilizare；英语再加上 fertilize、fertilizer、fertilization 以及更广的 -fer- 词族。"},"items":[{"word":"fer-","structure":"ferre (Latin verb, irregular)","meaning":"to bear, carry","meaningCN":"承载；生育","example":"The root supplies the sense of bearing fruit.","exampleCN":"这个词根提供「结果实」的意思。"},{"word":"-tilis","structure":"-tilis (Latin adjective suffix)","meaning":"able to, fit for","meaningCN":"能够……的","example":"Fertilis reads as 'able to bear'.","exampleCN":"fertilis 读作「能够承载的」。"},{"word":"-ize","structure":"-izare (verb-forming suffix via Greek -izein)","meaning":"to make, to cause to be","meaningCN":"使……；使成为","example":"Fertilize means to make fruitful.","exampleCN":"fertilize 意为使结果。"},{"word":"-er","structure":"-er (agent or instrument suffix)","meaning":"thing that does or supplies","meaningCN":"做某事的人或物","example":"Fertilizer is the thing that fertilizes.","exampleCN":"fertilizer 就是用来施肥的东西。"},{"word":"fertilizer","structure":"fertilize + -er","meaning":"a substance added to soil","meaningCN":"肥料","example":"The fertilizer was spread before planting.","exampleCN":"肥料在播种前撒下。"},{"word":"fertile","structure":"ferre + -tilis","meaning":"able to bear young or crops","meaningCN":"肥沃的；能生育的","example":"The valley floor is fertile and well watered.","exampleCN":"谷底土地肥沃、水源充足。"},{"word":"fertility","structure":"fertile + -ity","meaning":"the quality of being fruitful","meaningCN":"肥沃；生育力","example":"Fertility fell after the soil was exhausted.","exampleCN":"土壤耗尽后肥力下降。"},{"word":"fertilization","structure":"fertilize + -ation","meaning":"the act or result of fertilizing","meaningCN":"受精；施肥","example":"Fertilization was confirmed under the microscope.","exampleCN":"在显微镜下确认了受精。"},{"word":"self-fertilize","structure":"self- + fertilize","meaning":"to fertilize itself with its own gametes","meaningCN":"自体受精；自花受精","example":"Some plants self-fertilize when pollinators are absent.","exampleCN":"没有传粉者时，有些植物会自花受精。"}],"latinEntries":[{"word":"ferre","structure":"ferre, tuli, latum (verb, irregular)","meaning":"to bear, carry","meaningCN":"承载；生育"},{"word":"fertilis","structure":"fertilis, fertile (adjective, third declension)","meaning":"fruitful, productive","meaningCN":"能结果的；丰产的"},{"word":"fertilizare","structure":"fertilizare (verb, Medieval Latin, first conjugation)","meaning":"to make fruitful","meaningCN":"使结果；使丰产"},{"word":"fertilizatio","structure":"fertilizatio, fertilizationis (f., Medieval Latin, third declension)","meaning":"a making fruitful","meaningCN":"使结果；施肥"}]}},{"word":"fertilized","ipa_uk":"/ˈfɜːtɪlaɪzd/","ipa_us":"/ˈfɝːtəlaɪzd/","definition_zh":"已受精的；施过肥的；被加过养分的","definition_en":"having already been joined with a male cell, or having already been given nutrients","core_image":"一枚卵细胞表面留下精子进入的小孔，旁边是一块颜色变深的、刚下过肥的土","scene":"蛙卵在池塘里被精子包围后，表面出现一道浅浅的色素分界，标志着它已开始分裂。 Only a fertilized egg will divide, so the pond is thick with cells at different stages.","sceneCN":"这里 fertilized 指「已受精的」（第 1 个义项：卵细胞已完成与精子的融合）；句意为只有已受精的卵才会分裂，因此池塘里满是处于不同阶段的细胞。","pos":[{"tag":"adj.","zh":"已受精的；（土地）施过肥的；加过养分的"},{"tag":"vt.","zh":"（fertilize 的过去式与过去分词）"}],"collocations":[{"phrase":"fertilized egg","zh":"受精卵"},{"phrase":"fertilized soil","zh":"施过肥的土壤"},{"phrase":"fertilized ovum","zh":"受精卵（学术用语）"},{"phrase":"fertilized field","zh":"施过肥的田地"},{"phrase":"fertilized lawn","zh":"施过肥的草坪"},{"phrase":"newly fertilized","zh":"刚受精的"}],"forms":[{"label":"原级／分词","form":"fertilized"},{"label":"比较级","form":"more fertilized"},{"label":"最高级","form":"most fertilized"},{"label":"原形动词","form":"fertilize"},{"label":"现在分词","form":"fertilizing"},{"label":"名词","form":"fertilization"}],"derivatives":[{"word":"fertilize","pos":"v.","zh":"使受精；施肥"},{"word":"fertilization","pos":"n.","zh":"受精；施肥"},{"word":"unfertilized","pos":"adj.","zh":"未受精的；未施肥的"},{"word":"fertilizer","pos":"n.","zh":"肥料"},{"word":"fertile","pos":"adj.","zh":"肥沃的；能生育的"}],"senses":[{"no":"01","title":"Of an egg that has fused with a sperm","titleCN":"已完成受精的卵","definition":"having already been joined by a male cell and therefore able to divide","definitionCN":"已被雄性细胞结合，因而能够分裂","example":"Only a fertilized egg can begin to cleave.","exampleCN":"只有受精卵才能开始卵裂。","why":"the -ed form marks completion: fertilization has already happened, so the cell is no longer waiting.","whyCN":"-ed 形式标记完成：受精已经发生，因此这个细胞不再处于等待状态。"},{"no":"02","title":"Of soil that has been fed","titleCN":"施过肥的土壤","definition":"having had nutrients added so that it can support stronger growth","definitionCN":"已加入养分，因而能支撑更强的生长","example":"The fertilized soil held moisture far better than the bare plot.","exampleCN":"施过肥的土壤比裸露地块的保水能力强得多。","why":"the same participle applies because the soil has received exactly what the verb supplies.","whyCN":"同一分词同样适用，因为土壤接收了动词所提供的东西。"},{"no":"03","title":"Of a field or pasture already treated","titleCN":"已施过肥的田地或牧场","definition":"having already received fertilizer before planting or grazing","definitionCN":"在播种或放牧之前已经施过肥","example":"Cattle were moved onto the fertilized pasture in May.","exampleCN":"五月里牛群被赶进施过肥的牧场。","why":"land is treated as a patient that receives an action, so the participle describes its finished state.","whyCN":"土地被当作接受动作的对象，分词因此描述它已完成的状态。"},{"no":"04","title":"Of a lawn or garden already fed","titleCN":"已施过肥的草坪或花园","definition":"having been given lawn or garden feed and showing the result","definitionCN":"已施以草坪或园艺肥料，并显出效果","example":"The fertilized lawn greened up within a week.","exampleCN":"施过肥的草坪一周内就绿了起来。","why":"the visible result is the point: the participle implies not only the act but its effect on appearance.","whyCN":"可见的结果才是重点：这个分词不仅暗示动作，还暗示它对长势的影响。"},{"no":"05","title":"Of water oversupplied with nutrients","titleCN":"养分过多的（水体）","definition":"having received so many nutrients that algae grow out of control","definitionCN":"接受的养分过多，以致藻类失控生长","example":"The fertilized pond was closed to swimming that summer.","exampleCN":"那个养分过剩的池塘当年夏天禁止游泳。","why":"the same completion marker turns neutral when the amount is excessive: fed becomes overfed.","whyCN":"当数量过度时，同一个完成标记转为负面：被喂养变成了被喂过头。"},{"no":"06","title":"Of a flower that received pollen","titleCN":"已成功接受花粉的花","definition":"having received pollen on its stigma and therefore able to set seed","definitionCN":"柱头已接受花粉，因而能够结实","example":"Every fertilized flower in the row set a pod.","exampleCN":"这一行里每一朵受过粉的花都结了荚。","why":"in plants the delivery must be complete before fusion, so the participle can mark the earlier stage as finished too.","whyCN":"在植物中投递必须先完成才可能融合，因此这个分词也可标记更早的阶段已结束。"},{"no":"07","title":"Of a pregnancy begun from such a cell","titleCN":"由受精卵开始的妊娠","definition":"describing a pregnancy that began with a fertilized egg that implanted","definitionCN":"描述由已着床的受精卵开始的妊娠","example":"The scan showed a fertilized ovum correctly placed in the uterus.","exampleCN":"扫描显示受精卵正确地着床在子宫内。","why":"the adjective follows the cell into its next role, so the same word describes the start of a pregnancy.","whyCN":"形容词跟着这个细胞进入下一个角色，因此同一个词也描述妊娠的开端。"},{"no":"08","title":"Figurative: a mind made more productive","titleCN":"比喻：被丰富、被激发的（头脑）","definition":"figurative, having been supplied with something that makes thought more productive","definitionCN":"比喻用法，已获得某种使思维更有产出的东西","example":"A fertilized imagination invents connections that a dry one misses.","exampleCN":"被丰富的想像力能想出干枯头脑错过的联系。","why":"the metaphor keeps the completion: the enriching has already taken place and its effect is visible.","whyCN":"比喻保留了完成义：丰富作用已经发生，其效果可见。"}],"etymology":{"intro":{"en":"Fertilized is the past participle of fertilize, from Medieval Latin fertilizare, built on fertilis 'fruitful' and ultimately ferre 'to bear'. Dates are approximate.","cn":"fertilized 是 fertilize 的过去分词，后者来自中世纪拉丁 fertilizare，建立在 fertilis「能结果的」之上，最终出自 ferre「承载」。年代均为约数。"},"items":[{"era":"LATIN FERRE","en":"Ferre 'to bear, carry' supplies the idea of bearing fruit; its pre-Latin origin is reconstructed, not recorded.","cn":"ferre「承载、生育」提供「结果实」的意思；它在拉丁语之前的来源属重构，而非有记录的形式。"},{"era":"LATIN FERTILIS","en":"Fertilis 'fruitful' is generally analysed as ferre plus -ilis 'able'; the intermediate form is unattested.","cn":"fertilis「能结果的」一般分析为 ferre 加 -ilis「能够」；中间形式没有书证。"},{"era":"MEDIEVAL LATIN","en":"Fertilizare 'to make fruitful' passed from land to living things over several centuries.","cn":"fertilizare「使之结果」在数百年间从土地扩展到生物。"},{"era":"ENGLISH PARTICIPLE","en":"English -ed marks a completed action or a resulting state, which is why fertilized can describe an egg, a field or a pond.","cn":"英语的 -ed 标记已完成的动作或由此形成的状态，因此 fertilized 可以描述卵、田地或池塘。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the first recorded use of the participle for a gamete is not established; the dates and stages above are approximate.","cn":"来源不确定（首见年代）：这个分词首次用于配子的记录尚未确定；以上年代与阶段均为约数。"}]},"similar":{"note":{"en":"Group one separates the -ed forms that look alike; group two separates states of being supplied from states of being joined.","cn":"第一组区分外形相近的 -ed 形式；第二组区分「已被供给」与「已被结合」两种状态。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fertile","ipa":"/ˈfɜːtɪl/","tag":"capacity, not history","definition":"Able to produce; it describes a capacity, while fertilized describes a completed event.","definitionCN":"能够出产；描述能力，而 fertilized 描述已完成的事件。"},{"word":"fertilizer","ipa":"/ˈfɜːtɪlaɪzə/","tag":"the substance","definition":"The material itself, formed with -er; it has no tense and cannot describe a field.","definitionCN":"物质本身，由 -er 构成；它没有时态，不能描述田地。"},{"word":"fertilizing","ipa":"/ˈfɜːtɪlaɪzɪŋ/","tag":"in progress","definition":"The active participle: the work is under way, whereas fertilized means the work is finished.","definitionCN":"主动分词：工作正在进行，而 fertilized 表示工作已完成。"},{"word":"sterilized","ipa":"/ˈsterɪlaɪzd/","tag":"near-look, opposite sense","definition":"From sterile, not fertile, plus -ize: made free of living organisms, almost the reverse of fertilized soil.","definitionCN":"来自 sterile 而非 fertile，加 -ize：使不含活体，几乎与施过肥的土壤相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"impregnated","ipa":"/ɪmˈpreɡneɪtɪd/","tag":"made pregnant or saturated","definition":"Having been made pregnant, or having been soaked through with a substance; broader than fertilized.","definitionCN":"已被致孕，或已被某种物质浸透；比 fertilized 更宽。"},{"word":"pollinated","ipa":"/ˈpɒlɪneɪtɪd/","tag":"pollen delivered","definition":"Having received pollen; this marks the delivery, while fertilized marks the fusion.","definitionCN":"已接受花粉；标记投递完成，而 fertilized 标记融合完成。"},{"word":"enriched","ipa":"/ɪnˈrɪtʃt/","tag":"general supply","definition":"Having been given more of something valuable; it lacks the specific growth image of fertilized.","definitionCN":"已获得更多有价值之物；缺少 fertilized 那种生长的具体意象。"},{"word":"treated","ipa":"/ˈtriːtɪd/","tag":"neutral process word","definition":"A neutral participle for having undergone a process; fertilized is narrower because it names which substance was added.","definitionCN":"中性的分词，指经历过某种处理；fertilized 更窄，因为它指明加入了什么。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the -ed ending, the real noun pair and the real opposites.","cn":"正常联想：-ed 词尾、真实的名词配对与真实的反义词。"},"normal":[{"en":"-ed marks completion: the fertilizing is already done.","cn":"-ed 标记完成：施肥或受精已经结束。"},{"en":"Four objects share the participle: egg, soil, field, lawn.","cn":"四个对象共用这个分词：卵、土壤、田地、草坪。"},{"en":"Fixed phrases: fertilized egg, fertilized soil, newly fertilized.","cn":"固定搭配：受精卵、施过肥的土壤、刚受精的。"},{"en":"The opposite is unfertilized, formed with the prefix un-.","cn":"反义词是 unfertilized，由前缀 un- 构成。"},{"en":"The family runs fertilize, fertilization, fertilizer, fertile, fertility.","cn":"同族词包括 fertilize、fertilization、fertilizer、fertile、fertility。"}],"abstract":[{"en":"Picture an egg with a tiny door that has just closed behind a visitor.","cn":"想象一枚卵，门刚在来访者身后合上。"},{"en":"Picture dark, moist soil where bare dust used to be.","cn":"想象深色湿润的土壤，取代了原先裸露的尘土。"},{"en":"Picture a mind that has been watered and now keeps producing.","cn":"想象一个被浇过水的头脑，从此不断产出。"}]},"examples":[{"en":"The fertilized egg divided for the first time six hours later.","cn":"六小时后，受精卵第一次分裂。"},{"en":"The fertilized beds produced twice the usual harvest.","cn":"施过肥的苗圃产量是平常的两倍。"},{"en":"Runoff left the pond fertilized and choked with algae.","cn":"径流使池塘养分过剩，藻类疯长。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「fertilize + ed」——受精或施肥这个动作已经做完 → 已受精的、施过肥的","word":"fertilized"},"root":"拉丁 fertilis「能结果的」= ferre「承载、生育」+ -ilis「能够」；fertilizare「使结果」；英语 fertilize + -ed。ferre 的印欧来源属重构形式。","sensesIntro":{"en":"Eight senses of fertilized share one grammatical fact: the supplying or joining is already complete, so what is described is a finished state.","cn":"fertilized 的八个义项共有一个语法事实：供给或结合已经完成，因此被描述的是一个完成后的状态。"},"semanticMap":{"core":{"en":"CORE IMAGE: a finished act leaves its mark on the thing that received it.","cn":"核心意象：完成的动作在接受者身上留下痕迹。"},"chain":["COMPLETED ACT","FUSED CELL","FED SOIL","TREATED LAND","FED LAWN","OVERFED WATER"],"branches":[{"senses":"01 · 07","en":"THE CELL LINE: fusion is complete, and the same cell later begins a pregnancy.","cn":"细胞线：融合已完成，同一个细胞后来开启一段妊娠。"},{"senses":"02 · 03 · 04","en":"THE LAND LINE: soil, pasture and lawn all carry the mark of having been fed.","cn":"土地线：土壤、牧场与草坪都带着「被喂过」的印记。"},{"senses":"05","en":"TOO MUCH: the same completion becomes damage when nutrients pile up.","cn":"过量：养分堆积时，同样的完成变成损害。"},{"senses":"06","en":"THE FLOWER LINE: pollen delivery can also be marked as done.","cn":"花线：花粉投递同样可以被标记为完成。"},{"senses":"08","en":"THE MIND LINE: enrichment leaves a visible change in thought.","cn":"头脑线：丰富作用在思维中留下可见的改变。"}]},"affixes":{"intro":{"en":"Fertilized is a derived participle, so its suffixes mark both the action and its completion.","cn":"fertilized 是派生分词，后缀既标记动作，也标记完成。"},"latinIntro":{"en":"The Latin base ferre 'to bear' reaches English through fertilis and fertilizare; the English -ed adds the perfect aspect.","cn":"拉丁词基 ferre「承载」经 fertilis 与 fertilizare 进入英语；英语的 -ed 加上完成体。"},"items":[{"word":"fer-","structure":"ferre (Latin verb, irregular)","meaning":"to bear, carry","meaningCN":"承载；生育","example":"The root carries the image of bearing fruit.","exampleCN":"这个词根带着「结果实」的意象。"},{"word":"-tilis","structure":"-tilis (Latin adjective suffix)","meaning":"able to","meaningCN":"能够……的","example":"Fertilis means able to bear.","exampleCN":"fertilis 意为能够承载。"},{"word":"-ize","structure":"-izare (verb suffix)","meaning":"to make","meaningCN":"使……","example":"Fertilize means to make fruitful.","exampleCN":"fertilize 意为使结果。"},{"word":"-ed","structure":"-ed (English past-participle suffix)","meaning":"completed action or resulting state","meaningCN":"已完成的动作或由此形成的状态","example":"Fertilized means the work is done.","exampleCN":"fertilized 意为这件事已经做完。"},{"word":"un-","structure":"un- (English negative prefix)","meaning":"not","meaningCN":"不；未","example":"An unfertilized egg never divides.","exampleCN":"未受精的卵不会分裂。"},{"word":"fertilize","structure":"fertilis + -ize","meaning":"to make fruitful, to join gametes","meaningCN":"施肥；使受精","example":"Bees fertilize the blossoms.","exampleCN":"蜜蜂给花朵授粉。"},{"word":"fertilization","structure":"fertilize + -ation","meaning":"the act or result of fertilizing","meaningCN":"受精；施肥","example":"Fertilization was observed under the lens.","exampleCN":"在镜头下观察到受精。"},{"word":"fertilizer","structure":"fertilize + -er","meaning":"a substance that fertilizes","meaningCN":"肥料","example":"The fertilizer was worked into the topsoil.","exampleCN":"肥料被翻入表土。"},{"word":"fertility","structure":"fertile + -ity","meaning":"the quality of being fruitful","meaningCN":"肥力；生育力","example":"Fertility depends on soil structure.","exampleCN":"肥力取决于土壤结构。"}],"latinEntries":[{"word":"ferre","structure":"ferre, tuli, latum (verb, irregular)","meaning":"to bear, carry","meaningCN":"承载；生育"},{"word":"fertilis","structure":"fertilis, fertile (adjective, third declension)","meaning":"fruitful","meaningCN":"能结果的"},{"word":"fertilizare","structure":"fertilizare (verb, Medieval Latin, first conjugation)","meaning":"to make fruitful","meaningCN":"使结果"},{"word":"fertilizatio","structure":"fertilizatio, fertilizationis (f., Medieval Latin)","meaning":"a making fruitful","meaningCN":"使结果；施肥"}]}},{"word":"pollination","ipa_uk":"/ˌpɒlɪˈneɪʃən/","ipa_us":"/ˌpɑːləˈneɪʃən/","definition_zh":"传粉；授粉过程","definition_en":"the movement of pollen from the male part of a flower to the part that receives it","core_image":"一粒金色花粉从花药上被风或昆虫带走，落在另一朵花的柱头上","scene":"蜂群在花间来回，背上的花粉从一朵花被带到下一朵花的柱头。 Wind and insects both carry pollen, so pollination can happen without any visitor that intends it.","sceneCN":"这里 pollination 指「传粉」（第 1 个义项：花粉被送到柱头的全过程）；句意为风与昆虫都能搬运花粉，因此传粉可以在没有任何有意的来访者的情况下发生。","pos":[{"tag":"n.","zh":"传粉；授粉；传粉过程"}],"collocations":[{"phrase":"cross-pollination","zh":"异花传粉；相互启发"},{"phrase":"self-pollination","zh":"自花传粉"},{"phrase":"wind pollination","zh":"风媒传粉"},{"phrase":"insect pollination","zh":"虫媒传粉"},{"phrase":"hand pollination","zh":"人工授粉"},{"phrase":"pollination syndrome","zh":"传粉综合征"}],"forms":[{"label":"原形","form":"pollination"},{"label":"复数","form":"pollinations"},{"label":"同根动词","form":"pollinate"},{"label":"同根名词（传粉者）","form":"pollinator"},{"label":"同根形容词","form":"pollination-dependent"},{"label":"相关名词（花粉）","form":"pollen"}],"derivatives":[{"word":"pollinate","pos":"v.","zh":"给……传粉"},{"word":"pollinator","pos":"n.","zh":"传粉者"},{"word":"pollen","pos":"n.","zh":"花粉"},{"word":"cross-pollination","pos":"n.","zh":"异花传粉；相互启发"},{"word":"self-pollination","pos":"n.","zh":"自花传粉"}],"senses":[{"no":"01","title":"Moving pollen to the stigma","titleCN":"把花粉送到柱头","definition":"the transfer of pollen from an anther to a stigma","definitionCN":"花粉从花药被转移到柱头的过程","example":"Pollination must precede fertilization in flowering plants.","exampleCN":"在开花植物中，传粉必须先于受精。","why":"the word names the delivery, not the fusion: pollen has to arrive before the two cells can ever meet.","whyCN":"这个词命名的是投递而非融合：花粉必须先到达，两个细胞才可能相遇。"},{"no":"02","title":"Cross-pollination between plants","titleCN":"异花传粉","definition":"pollen moving from one plant to a genetically different one","definitionCN":"花粉从一株植物移到基因上不同的另一株","example":"Cross-pollination keeps a population genetically varied.","exampleCN":"异花传粉使种群保持基因多样。","why":"cross- marks the path that leaves the original plant, which is also why the term became a metaphor for exchanging ideas.","whyCN":"cross- 标记离开原株的路径，这也是该词后来成为「交换思想」比喻的原因。"},{"no":"03","title":"Self-pollination within one flower","titleCN":"自花传粉","definition":"pollen reaching the stigma of the same flower or the same plant","definitionCN":"花粉落到同一朵花或同一株植物的柱头","example":"Self-pollination guarantees seed even when partners are scarce.","exampleCN":"即使缺少伙伴，自花传粉也能保证结实。","why":"self- marks a closed loop, so the deliverer and the receiver belong to one individual.","whyCN":"self- 标记一个闭环：投递者与接收者属于同一个个体。"},{"no":"04","title":"Wind pollination","titleCN":"风媒传粉","definition":"pollen carried by moving air rather than by an animal","definitionCN":"花粉由流动的空气而非动物搬运","example":"Grasses rely on wind pollination and release clouds of pollen.","exampleCN":"禾草依靠风媒传粉，会释放大量花粉。","why":"the agent is named in front of the noun, because pollination alone does not say who did the carrying.","whyCN":"传粉者被放在名词之前，因为单说 pollination 并不说明是谁搬运的。"},{"no":"05","title":"Animal pollination","titleCN":"动物传粉","definition":"pollen carried by insects, birds, bats or other animals","definitionCN":"花粉由昆虫、鸟、蝙蝠或其他动物搬运","example":"Animal pollination is more precise than wind but costs the plant nectar.","exampleCN":"动物传粉比风媒更精准，但植物要付出花蜜。","why":"the animal is the vehicle, and the plant pays for precision with food.","whyCN":"动物是载体，植物用食物为精准付费。"},{"no":"06","title":"Hand pollination in farming","titleCN":"农业上的人工授粉","definition":"pollination performed by people with brushes, sticks or vibrating tools","definitionCN":"由人用毛刷、木针或振动工具完成的传粉","example":"Hand pollination is standard practice in vanilla orchards.","exampleCN":"人工授粉是香草园的标准做法。","why":"human hands replace a missing animal, so the process keeps the same name and only the agent changes.","whyCN":"人手替代了缺失的动物，过程仍用同一个名称，改变的只是执行者。"},{"no":"07","title":"Pollination ecology and syndromes","titleCN":"传粉生态学与传粉综合征","definition":"the study of which visitors a flower is built to attract, and the matching traits","definitionCN":"研究一朵花为吸引哪类来访者而建造，以及与之匹配的特征","example":"The long spur is a classic bat-pollination syndrome.","exampleCN":"长长的距是典型的蝙蝠传粉综合征。","why":"a flower's shape is evidence about its pollinator, so the process name extends to the whole matched set of traits.","whyCN":"花的形状是关于其传粉者的证据，因此过程名称延伸到整套匹配的特征。"},{"no":"08","title":"Metaphor: cross-pollination of ideas","titleCN":"比喻：思想的相互传播与启发","definition":"the movement of ideas between fields or people so that both develop","definitionCN":"观念在领域或人之间流动，使双方都得到发展","example":"The residency encourages pollination between poets and engineers.","exampleCN":"这个驻留计划鼓励诗人与工程师之间的相互启发。","why":"the metaphor keeps the image of fertile material carried from one flower to another.","whyCN":"比喻保留了「肥沃材料从一朵花被带到另一朵」的意象。"}],"etymology":{"intro":{"en":"Pollination is the noun of pollinate, built on Latin pollen 'fine flour, dust', which was applied to the dust of flowers. The deeper origin of pollen is uncertain. Dates are approximate.","cn":"pollination 是 pollinate 的名词，建立在拉丁 pollen「细面粉、粉尘」之上，这个词被用来指花上的粉末。pollen 的更早来源不确定。年代均为约数。"},"items":[{"era":"LATIN POLLEN","en":"Pollen meant 'fine flour, mill dust'; the transfer to the dust of anthers is a metaphor of appearance, not of function.","cn":"pollen 意为「细面粉、磨坊粉尘」；转指花药粉末是凭外观取的比喻，并非按功能命名。"},{"era":"UNCERTAIN ORIGIN","en":"Source uncertain: the pre-Latin origin of pollen is unsettled; links to polenta 'peeled barley' and to pulvis 'dust' are hypotheses, and no single Indo-European form is proven.","cn":"来源不确定：pollen 在拉丁语之前的来源没有定论；与 polenta「去壳大麦」及 pulvis「粉尘」的联系都是假说，没有一种印欧形式得到证明。"},{"era":"BOTANICAL TERM","en":"Nineteenth-century botanists adopted pollen for the male gamete-bearing grains of flowers.","cn":"19 世纪的植物学家采用 pollen 指花中携带雄性配子的颗粒。"},{"era":"POLLINATION COINED","en":"The noun pollination appears in the nineteenth century as the study of flower fertilisation grew; it belongs to the same period as the modern sense of fertilize.","cn":"随着对花受精的研究发展，名词 pollination 于 19 世纪出现，与 fertilize 的现代义属同一时期。"},{"era":"COMPOUND EXTENSIONS","en":"Cross-pollination and self-pollination were formed later from the noun plus prefixes, and each also acquired a figurative use.","cn":"cross-pollination 与 self-pollination 后来由该名词加前缀构成，各自也获得了比喻用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (coining date): the exact first appearance of pollination in print is not firmly established, so the nineteenth-century dating is approximate.","cn":"来源不确定（造词年代）：pollination 首次见于印刷的确切时间尚无定论，因此 19 世纪的系年只是约数。"}]},"similar":{"note":{"en":"Group one separates the pollen words that look alike; group two separates the delivery stage from the fusion stage and from the agents.","cn":"第一组区分外形相近的 pollen 系词；第二组区分投递阶段、融合阶段与执行者。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pollen","ipa":"/ˈpɒlən/","tag":"the grains themselves","definition":"The substance carried; it is the material, while pollination is the journey it makes.","definitionCN":"被搬运的物质本身；pollination 指它所走的旅程。"},{"word":"pollinate","ipa":"/ˈpɒlɪneɪt/","tag":"the verb","definition":"To carry out the transfer; the verb takes a flower as object, the noun takes the process as subject.","definitionCN":"执行这次转移；动词以花为宾语，名词以过程为主语。"},{"word":"pollinator","ipa":"/ˈpɒlɪneɪtə/","tag":"the agent","definition":"The animal or wind that does the carrying, formed with -or 'one who acts'.","definitionCN":"完成搬运的动物或风，由 -or「行动者」构成。"},{"word":"pollination","ipa":"/ˌpɒlɪˈneɪʃən/","tag":"the process","definition":"The whole event, formed with -ation; it is neither the grain nor the visitor.","definitionCN":"整个事件，由 -ation 构成；既不是颗粒也不是来访者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fertilization","ipa":"/ˌfɜːtɪlaɪˈzeɪʃən/","tag":"fusion, not delivery","definition":"The joining of gametes; pollination is the earlier delivery that makes it possible in flowering plants.","definitionCN":"配子的结合；传粉是开花植物中使之前成为可能的更早投递。"},{"word":"dispersal","ipa":"/dɪˈspɜːsəl/","tag":"seeds, not pollen","definition":"The spreading of seeds or spores away from the parent; pollination moves male grains to a stigma instead.","definitionCN":"种子或孢子离开母体扩散；传粉则是把雄性颗粒送到柱头。"},{"word":"germination","ipa":"/ˌdʒɜːmɪˈneɪʃən/","tag":"sprouting, not delivery","definition":"The start of growth from a seed or spore, which happens after both pollination and fertilization.","definitionCN":"种子或孢子开始生长，发生在传粉与受精之后。"},{"word":"nectar","ipa":"/ˈnektə/","tag":"the reward","definition":"The sugar liquid that attracts pollinators; it is the payment, not the transfer.","definitionCN":"吸引传粉者的糖液；是报酬，而不是转移本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real ecological phrases and real relatives.","cn":"正常联想：真实的构词成分、真实的生态学搭配与真实同族词。"},"normal":[{"en":"pollen + -ation: the noun of what is done with pollen.","cn":"pollen + -ation：对花粉所做之事的名称。"},{"en":"Three agents share the word: wind, insects, and human hands.","cn":"三种执行者共用这个词：风、昆虫与人的手。"},{"en":"Prefixes split the routes: cross-pollination, self-pollination, hand pollination.","cn":"前缀分出路径：异花传粉、自花传粉、人工授粉。"},{"en":"The order is fixed: pollination, then fertilization, then seed set.","cn":"顺序固定：先传粉，再受精，然后结实。"},{"en":"The family runs pollen, pollinate, pollinator, pollination.","cn":"同族词包括 pollen、pollinate、pollinator、pollination。"}],"abstract":[{"en":"Picture a letter carried between two houses that never speak directly.","cn":"想象一封信在两户从不直接交谈的人家之间被传递。"},{"en":"Picture a kitchen exchanging recipes until both families cook better.","cn":"想象两户人家交换菜谱，直到两家都做得更好吃。"},{"en":"Picture a library whose books keep moving from shelf to shelf, changing every reader.","cn":"想象一座图书馆，书不断在架间移动，改变每一个读者。"}]},"examples":[{"en":"Pollination fails when the night is too cold for moths.","cn":"夜里太冷、蛾子不飞时，传粉就会失败。"},{"en":"The orchard depends on insect pollination for most of its crop.","cn":"这片果园的大部分收成依靠虫媒传粉。"},{"en":"Cross-pollination between the two labs sped up the discovery.","cn":"两个实验室之间的相互启发加快了这项发现。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pollen（花粉）+ ation」——花粉从这朵花跑到那朵花 → 传粉","word":"pollination"},"root":"拉丁 pollen, pollinis「细面粉、粉尘」→ 花上的粉末；加 -ation 构成 pollination。pollen 的更早来源不确定，与 polenta、pulvis 的联系均为假说。","sensesIntro":{"en":"Eight senses of pollination follow one journey: male dust leaves one flower and arrives at another, whether the carrier is wind, an animal or a hand.","cn":"pollination 的八个义项沿同一段旅程展开：雄性粉末离开一朵花、抵达另一朵，无论载体是风、动物还是人的手。"},"semanticMap":{"core":{"en":"CORE IMAGE: a golden dust grain lifted from one flower and set down on another.","cn":"核心意象：一粒金色粉末从一朵花被抬起，落在另一朵上。"},"chain":["POLLEN LEAVES","POLLEN ARRIVES","CROSS PATH","SELF LOOP","WIND","ANIMAL OR HAND"],"branches":[{"senses":"01 · 02","en":"DELIVERY: the journey between two different plants is the basic event.","cn":"投递：在两株不同植物之间的旅程是基本事件。"},{"senses":"03","en":"CLOSED LOOP: the same plant can send pollen to itself.","cn":"闭环：同一株植物可以把花粉送给自己。"},{"senses":"04 · 05","en":"CARRIERS: air or an animal does the moving, with different precision and cost.","cn":"载体：空气或动物负责搬运，精准度与代价不同。"},{"senses":"06 · 07","en":"BY HAND AND BY DESIGN: people can replace a missing animal, and a flower's shape records which visitor it expects.","cn":"人工与设计：人可以替代缺失的动物，花的形状则记录它期待哪种来访者。"},{"senses":"08","en":"IDEA TRAFFIC: what is carried can be an idea rather than a grain.","cn":"观念流动：被搬运的可以是观念而非颗粒。"}]},"affixes":{"intro":{"en":"Pollination is a Latin noun of material plus an action suffix, and the family names material, action and agent separately.","cn":"pollination 是拉丁物质名词加动作后缀，其词族把材料、动作与执行者分开命名。"},"latinIntro":{"en":"Latin pollen, pollinis 'fine flour, dust' gives English pollen; pollinate and pollination were formed in modern scientific Latin and English.","cn":"拉丁 pollen, pollinis「细面粉、粉尘」衍生英语 pollen；pollinate 与 pollination 是在近代科学拉丁语与英语中构成的。"},"items":[{"word":"pollen","structure":"pollen, pollinis (n., third declension)","meaning":"fine flour, dust","meaningCN":"细面粉；粉尘","example":"The anther sheds pollen as a fine dust.","exampleCN":"花药把花粉作为细粉撒出。"},{"word":"-ate","structure":"-atus (Latin participle and verb suffix)","meaning":"to perform an action on","meaningCN":"对……施行动作","example":"Pollinate means to perform the pollen transfer.","exampleCN":"pollinate 意为执行花粉的转移。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"the act or process of","meaningCN":"动作或过程","example":"Pollination names the process as a whole.","exampleCN":"pollination 把整个过程作为整体来命名。"},{"word":"-or","structure":"-or (Latin agent suffix)","meaning":"one who or that which acts","meaningCN":"行动者","example":"A pollinator is the agent of the transfer.","exampleCN":"pollinator 是这次转移的执行者。"},{"word":"pollinate","structure":"pollen + -ate","meaning":"to transfer pollen","meaningCN":"给……传粉","example":"Bees pollinate the clover.","exampleCN":"蜜蜂给三叶草传粉。"},{"word":"pollinator","structure":"pollinate + -or","meaning":"an animal or agent that carries pollen","meaningCN":"传粉者","example":"The moth is the only pollinator of that orchid.","exampleCN":"那种兰花唯一的传粉者是蛾子。"},{"word":"cross-pollination","structure":"cross- + pollination","meaning":"transfer between different plants","meaningCN":"异花传粉","example":"Cross-pollination requires two compatible plants.","exampleCN":"异花传粉需要两株亲和的植物。"},{"word":"self-pollination","structure":"self- + pollination","meaning":"transfer within one plant","meaningCN":"自花传粉","example":"Self-pollination can produce weaker offspring over time.","exampleCN":"长期自花传粉可能产生较弱的后代。"},{"word":"hand pollination","structure":"hand + pollination (compound term)","meaning":"transfer done by people","meaningCN":"人工授粉","example":"Hand pollination replaces absent insects.","exampleCN":"人工授粉替代了缺席的昆虫。"}],"latinEntries":[{"word":"pollen","structure":"pollen, pollinis (n., third declension)","meaning":"fine flour, dust","meaningCN":"细面粉；粉尘"},{"word":"pollinare","structure":"pollinare (verb, Modern Latin, first conjugation)","meaning":"to dust with pollen","meaningCN":"给……撒花粉"},{"word":"pollinatio","structure":"pollinatio, pollinationis (f., Modern Latin)","meaning":"a pollen transfer","meaningCN":"花粉转移；传粉"}]}},{"word":"pollinate","ipa_uk":"/ˈpɒlɪneɪt/","ipa_us":"/ˈpɑːləneɪt/","definition_zh":"给……传粉；把花粉送到（花的）柱头上","definition_en":"to carry pollen to the part of a flower that receives it, whether by wind, an animal or a human hand","core_image":"一小团金色粉尘从花药被提起，稳稳落在另一朵花的黏性柱头上","scene":"清晨，养蜂人把蜂箱搬到梨园边，让蜜蜂开始一天的工作。 Honeybees pollinate the pear blossoms as they collect nectar at dawn.","sceneCN":"这里 pollinate 指「给花传粉」（第 1 个义项：把花粉送到柱头上）；句意为蜜蜂清晨采蜜时把梨树的花授了粉。","pos":[{"tag":"vt.","zh":"给……传粉；给……授粉"}],"collocations":[{"phrase":"pollinate flowers","zh":"给花传粉"},{"phrase":"pollinate crops","zh":"给作物授粉"},{"phrase":"hand-pollinate","zh":"人工授粉"},{"phrase":"pollinate orchards","zh":"给果园授粉"},{"phrase":"insect-pollinated","zh":"虫媒传粉的"},{"phrase":"wind-pollinated","zh":"风媒传粉的"}],"forms":[{"label":"三单（he/she/it）","form":"pollinates"},{"label":"过去式","form":"pollinated"},{"label":"过去分词","form":"pollinated"},{"label":"现在分词","form":"pollinating"},{"label":"名词（传粉）","form":"pollination"},{"label":"名词（传粉者）","form":"pollinator"}],"derivatives":[{"word":"pollination","pos":"n.","zh":"传粉；授粉"},{"word":"pollinator","pos":"n.","zh":"传粉者"},{"word":"pollen","pos":"n.","zh":"花粉"},{"word":"self-pollinate","pos":"v.","zh":"自花传粉；自花受精"},{"word":"cross-pollinate","pos":"v.","zh":"异花传粉；相互启发"}],"senses":[{"no":"01","title":"Carry pollen to a stigma","titleCN":"把花粉送到柱头","definition":"to move pollen from the male part of a flower onto the part that receives it","definitionCN":"把花粉从花的雄性部位移到接受花粉的部位","example":"Bees pollinate the clover as they work the field.","exampleCN":"蜜蜂在田间劳作时给三叶草传粉。","why":"the verb names only the delivery; whether the pollen then fuses with an egg is a later, separate event.","whyCN":"这个动词只命名投递；花粉之后是否与卵融合，是另一个更晚的事件。"},{"no":"02","title":"Of wind or insects doing the work","titleCN":"由风或昆虫完成传粉","definition":"of an animal or the wind, to act as the carrier of pollen between flowers","definitionCN":"指动物或风充任花与花之间花粉的搬运者","example":"A warm breeze pollinated the whole meadow in a single afternoon.","exampleCN":"一阵暖风在一个下午就给整片草地传了粉。","why":"the carrier can be the subject because the verb does not require a human agent.","whyCN":"搬运者可以作主语，因为这个动词并不要求施动者是人。"},{"no":"03","title":"Do it by hand","titleCN":"人工给作物授粉","definition":"to apply pollen by hand with a brush, stick or vibrating tool","definitionCN":"用毛刷、木针或振动工具亲手施用花粉","example":"Growers pollinate the vanilla vines one flower at a time.","exampleCN":"种植者一朵一朵地给香草藤授粉。","why":"a hand can take the place of an absent insect without changing what the verb means.","whyCN":"手可以取代缺席的昆虫，而动词的含义并不改变。"},{"no":"04","title":"Make a flower set fruit","titleCN":"使花坐果、结实","definition":"to cause a flower to develop fruit or seed by bringing it pollen","definitionCN":"通过送来花粉使花发育成果实或种子","example":"Two visits pollinate the female flower and the fruit begins to swell.","exampleCN":"两次造访就给雌花授了粉，果实开始膨大。","why":"the result stands in for the means: what the grower wants is fruit, and pollen is how it is obtained.","whyCN":"结果替代了手段：种植者要的是果实，花粉是取得它的方式。"},{"no":"05","title":"Apply pollen to a receptive surface","titleCN":"把花粉施到可接受的表面","definition":"to place pollen on a stigma that is chemically ready to receive it","definitionCN":"把花粉放到化学上已准备好接受它的柱头上","example":"Only a receptive stigma can be pollinated successfully.","exampleCN":"只有处于可接受状态的柱头才能成功授粉。","why":"technical writing separates the act from the timing, so the verb can take the surface itself as object.","whyCN":"技术写作把动作与时机分开，因此这个动词可以直接以接受面为宾语。"},{"no":"06","title":"Self-pollinate within one plant","titleCN":"使同株自花授粉","definition":"to bring a plant's own pollen to its own stigma","definitionCN":"把植物自己的花粉送到自己的柱头","example":"The species can pollinate itself when no partner is near.","exampleCN":"附近没有同伴时，这个物种能给自己授粉。","why":"the reflexive form closes the loop, so carrier and receiver are the same individual.","whyCN":"反身形式闭合了环路，搬运者与接受者因此是同一个个体。"},{"no":"07","title":"Metaphor: spread ideas into another field","titleCN":"比喻：把观念播散到另一领域","definition":"to carry an idea from one field into another so that it takes root there","definitionCN":"把一种观念从某个领域带入另一个领域，使其在那里生根","example":"Engineers pollinate biology with methods the biologists had never tried.","exampleCN":"工程师把生物学家从未试过的方法带进了生物学。","why":"the metaphor keeps the direction of travel and the fertility that follows arrival.","whyCN":"比喻保留了移动的方向，以及抵达之后随之而来的丰产。"},{"no":"08","title":"Manage pollination in a greenhouse","titleCN":"在温室或果园中安排授粉","definition":"to arrange for pollen to reach plants that lack natural carriers","definitionCN":"为缺少自然传粉者的植物安排花粉送达","example":"Staff pollinate the greenhouse rows with a vibrating wand twice a week.","exampleCN":"工作人员每周两次用振动棒给温室的几行植株授粉。","why":"indoors there are no bees, so the verb becomes a task on a schedule rather than a natural event.","whyCN":"室内没有蜜蜂，这个动词于是变成日程表上的一项工作，而非自然事件。"}],"etymology":{"intro":{"en":"Pollinate is formed from Latin pollen 'fine flour, dust' plus -ate; the word was built in modern scientific Latin to name what is done with the dust of flowers. The deeper origin of pollen is uncertain.","cn":"pollinate 由拉丁 pollen「细面粉、粉尘」加 -ate 构成；这个词是在近代科学拉丁语中造出的，用来命名对花上粉末所做之事。pollen 的更早来源不确定。"},"items":[{"era":"LATIN POLLEN","en":"Pollen meant 'fine flour, mill dust'; calling the anther grains pollen was a metaphor based on how they look.","cn":"pollen 意为「细面粉、磨坊粉尘」；把花药颗粒称作 pollen，是依据外观取的比喻。"},{"era":"UNCERTAIN ORIGIN","en":"Source uncertain: pollen's pre-Latin ancestry is unsettled; the suggested links to polenta 'peeled barley' and pulvis 'dust' remain hypotheses.","cn":"来源不确定：pollen 在拉丁语之前的谱系没有定论；与 polenta「去壳大麦」及 pulvis「粉尘」的联系仍属假说。"},{"era":"MODERN LATIN COINAGE","en":"Modern Latin pollinare 'to dust with pollen' supplied the model for the English verb; the coinage belongs to nineteenth-century botany.","cn":"近代拉丁 pollinare「给……撒花粉」为英语动词提供了模型；这一造词属 19 世纪植物学。"},{"era":"ENGLISH VERB","en":"English pollinate became common as plant breeding and orchard management developed.","cn":"随着植物育种与果园管理的发展，英语 pollinate 变得常用。"},{"era":"PREFIXED FORMS","en":"Self-pollinate and cross-pollinate were formed later from the verb, and both also carry figurative senses.","cn":"self-pollinate 与 cross-pollinate 后来由该动词构成，二者也都有比喻义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first citation): the earliest printed use of pollinate is not firmly dated, so the nineteenth-century placement is approximate.","cn":"来源不确定（首见书证）：pollinate 最早见于印刷的时间没有确证，因此归于 19 世纪只是约数。"}]},"similar":{"note":{"en":"Group one separates the pollen family that looks alike; group two separates the delivery act from the fusion act and from the spreading of seeds.","cn":"第一组区分外形相近的 pollen 词族；第二组区分投递动作、融合动作与种子扩散。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pollination","ipa":"/ˌpɒlɪˈneɪʃən/","tag":"the noun","definition":"The process as a whole; the verb is what an agent does, the noun is the event itself.","definitionCN":"整个过程；动词是行动者所做的，名词是事件本身。"},{"word":"pollinator","ipa":"/ˈpɒlɪneɪtə/","tag":"the agent","definition":"The animal that carries pollen, formed with -or; it does the action named by the verb.","definitionCN":"搬运花粉的动物，由 -or 构成；它执行动词所指的动作。"},{"word":"pollen","ipa":"/ˈpɒlən/","tag":"the material","definition":"The grains themselves; the verb needs this material to have anything to carry.","definitionCN":"颗粒本身；动词必须有这种材料才有东西可搬。"},{"word":"polinate","ipa":"/ˈpɒlɪneɪt/","tag":"misspelling","definition":"Not an English word: the single l is a common error, since the Latin pollen has two.","definitionCN":"并非英语词：只写一个 l 是常见错误，因为拉丁 pollen 有两个 l。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fertilize","ipa":"/ˈfɜːtɪlaɪz/","tag":"fusion, later stage","definition":"To join gametes, or to feed soil; in flowers it follows pollination rather than replacing it.","definitionCN":"使配子结合，或给土壤施肥；在花中它发生在传粉之后，而非取代传粉。"},{"word":"cross-pollinate","ipa":"/ˌkrɒsˈpɒlɪneɪt/","tag":"between two plants","definition":"To carry pollen from one plant to a genetically different one, or metaphorically to mix ideas from two fields.","definitionCN":"把一株的花粉带到基因上不同的另一株，或比喻混合两个领域的观念。"},{"word":"disperse","ipa":"/dɪˈspɜːs/","tag":"seeds, not pollen","definition":"To spread seeds or spores away from the parent; the direction is outward from the plant, not onto a stigma.","definitionCN":"把种子或孢子带离母体；方向是从植物向外，而不是落到柱头。"},{"word":"hand-pollinate","ipa":"/ˈhænd ˈpɒlɪneɪt/","tag":"human agent","definition":"A compound verb naming pollination done by people; it specifies the agent that plain pollinate leaves open.","definitionCN":"由人完成的授粉的复合动词；它指明普通 pollinate 未指明的执行者。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real orchard phrases and real relatives.","cn":"正常联想：真实的构词成分、真实的果园搭配与真实同族词。"},"normal":[{"en":"pollen + -ate: to do the pollen thing to a flower.","cn":"pollen + -ate：对花做「花粉那件事」。"},{"en":"Three carriers in one verb: bees, wind, and a person with a brush.","cn":"一个动词里有三种载体：蜜蜂、风，以及拿刷子的人。"},{"en":"Fixed phrases: pollinate flowers, pollinate crops, hand-pollinate.","cn":"固定搭配：给花传粉、给作物授粉、人工授粉。"},{"en":"The order is fixed: pollinate, then fertilize, then fruit.","cn":"顺序固定：先传粉，再受精，然后结果。"},{"en":"The family runs pollen, pollinate, pollination, pollinator.","cn":"同族词包括 pollen、pollinate、pollination、pollinator。"}],"abstract":[{"en":"Picture a courier who never speaks to either household but still connects them.","cn":"想象一名信使，从不与两户人家交谈，却仍把他们连在一起。"},{"en":"Picture a cook borrowing a technique from a neighbouring kitchen and making it work.","cn":"想象一位厨师从邻家厨房借来一种做法，并让它奏效。"},{"en":"Picture a gardener with a soft brush standing in for a missing bee.","cn":"想象园丁拿一支软刷，替代缺席的蜜蜂。"}]},"examples":[{"en":"Bees pollinate the apple trees in spring.","cn":"春天，蜜蜂给苹果树授粉。"},{"en":"Workers pollinate the vanilla flowers before noon, when they open.","cn":"工人在中午前给开放的香草花授粉。"},{"en":"The two disciplines pollinate each other more than either admits.","cn":"这两个学科相互启发，程度超过双方所承认的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pollen（花粉）+ ate」——把花粉送到花上去 → 给……传粉","word":"pollinate"},"root":"拉丁 pollen, pollinis「细面粉、粉尘」+ -ate；近代拉丁 pollinare「给……撒花粉」。pollen 更早来源不确定，与 polenta、pulvis 的联系均为假说。","sensesIntro":{"en":"Eight senses of pollinate all describe one delivery: pollen leaves a male part and arrives somewhere able to receive it, by wind, by animal or by hand.","cn":"pollinate 的八个义项都描述同一次投递：花粉离开雄性部位，抵达能接受它的地方，靠风、靠动物或靠人手。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dust grain lifted and set down where it can begin to grow.","cn":"核心意象：一粒粉末被抬起，放到它能开始生长的地方。"},"chain":["TAKE POLLEN","CARRY IT","SET IT DOWN","RECEIVE IT","SET FRUIT","SPREAD IDEAS"],"branches":[{"senses":"01 · 02","en":"THE CARRY: the transfer itself, whether the carrier is an insect or a breeze.","cn":"搬运：转移本身，无论载体是昆虫还是微风。"},{"senses":"03 · 08","en":"THE HAND: people can replace a missing carrier, outdoors or in a greenhouse.","cn":"人手：人能在露天或温室中替代缺失的载体。"},{"senses":"04 · 05","en":"THE RESULT: fruit follows, provided the receiving surface is ready.","cn":"结果：只要接受面已准备好，果实随后出现。"},{"senses":"06","en":"THE CLOSED LOOP: a plant can deliver to itself.","cn":"闭环：植物可以给自己投递。"},{"senses":"07","en":"THE METAPHOR: ideas travel the same route and take root.","cn":"比喻：观念走同一条路线并生根。"}]},"affixes":{"intro":{"en":"Pollinate is a Latin noun of material turned into a verb, so the same stock yields material, action and agent.","cn":"pollinate 是拉丁物质名词转成的动词，同一词干因此衍生出材料、动作与执行者。"},"latinIntro":{"en":"Latin pollen, pollinis 'fine flour, dust' gives pollen; Modern Latin pollinare supplies the verb, and English adds pollination and pollinator.","cn":"拉丁 pollen, pollinis「细面粉、粉尘」衍生 pollen；近代拉丁 pollinare 提供动词，英语再加 pollination 与 pollinator。"},"items":[{"word":"pollen","structure":"pollen, pollinis (n., third declension)","meaning":"fine flour, dust","meaningCN":"细面粉；粉尘","example":"Pollen is shed as a dry dust.","exampleCN":"花粉以干粉形式被撒出。"},{"word":"-ate","structure":"-atus (Latin verb and participle suffix)","meaning":"to perform an action on an object","meaningCN":"对……施行动作","example":"Pollinate means to perform the transfer.","exampleCN":"pollinate 意为执行这次转移。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"the act or process of","meaningCN":"动作或过程","example":"Pollination names the whole process.","exampleCN":"pollination 命名整个过程。"},{"word":"-or","structure":"-or (Latin agent suffix)","meaning":"one who or that which acts","meaningCN":"行动者","example":"A pollinator is the acting agent.","exampleCN":"pollinator 是行动的执行者。"},{"word":"pollination","structure":"pollinate + -ation","meaning":"the process of transferring pollen","meaningCN":"传粉过程","example":"Pollination depends on the weather.","exampleCN":"传粉取决于天气。"},{"word":"pollinator","structure":"pollinate + -or","meaning":"an animal that carries pollen","meaningCN":"传粉者","example":"The bee is a generalist pollinator.","exampleCN":"蜜蜂是泛性传粉者。"},{"word":"self-pollinate","structure":"self- + pollinate","meaning":"to pollinate oneself","meaningCN":"自花传粉","example":"The plant self-pollinates in closed buds.","exampleCN":"这种植物在闭合的花蕾中自花传粉。"},{"word":"cross-pollinate","structure":"cross- + pollinate","meaning":"to pollinate a different plant","meaningCN":"异花传粉","example":"Growers cross-pollinate the two varieties.","exampleCN":"种植者让两个品种异花传粉。"},{"word":"wind-pollinated","structure":"wind + pollinated (compound adjective)","meaning":"pollinated by moving air","meaningCN":"风媒传粉的","example":"Wind-pollinated grasses release enormous amounts of pollen.","exampleCN":"风媒传粉的禾草释放大量花粉。"}],"latinEntries":[{"word":"pollen","structure":"pollen, pollinis (n., third declension)","meaning":"fine flour, dust","meaningCN":"细面粉；粉尘"},{"word":"pollinare","structure":"pollinare (verb, Modern Latin, first conjugation)","meaning":"to dust with pollen","meaningCN":"给……撒花粉"},{"word":"pollinatio","structure":"pollinatio, pollinationis (f., Modern Latin)","meaning":"a pollen transfer","meaningCN":"花粉转移；传粉"}]}},{"word":"pollinator","ipa_uk":"/ˈpɒlɪneɪtə/","ipa_us":"/ˈpɑːləneɪtɚ/","definition_zh":"传粉者；传播花粉的动物或媒介","definition_en":"an animal, or sometimes the wind, that carries pollen from one flower to another","core_image":"一只毛茸茸的蜂腿上沾满金色花粉团，正落在下一朵花的花蕊上","scene":"园丁在田埂边留出一块不除草的地，野花茂密，蜂蝶往来。 That strip of wildflowers serves as a pollinator refuge between the crop rows.","sceneCN":"这里 pollinator 指「传粉者」（第 1 个义项：搬运花粉的动物）；句意为那条野花带在作物行间充当传粉者的庇护所。","pos":[{"tag":"n.","zh":"传粉者；传粉动物；传粉媒介"}],"collocations":[{"phrase":"pollinator decline","zh":"传粉者数量下降"},{"phrase":"pollinator garden","zh":"传粉者花园"},{"phrase":"pollinator conservation","zh":"传粉者保护"},{"phrase":"key pollinator","zh":"关键传粉者"},{"phrase":"pollinator network","zh":"传粉者网络"},{"phrase":"native pollinator","zh":"本地传粉者"}],"forms":[{"label":"原形","form":"pollinator"},{"label":"复数","form":"pollinators"},{"label":"同根动词","form":"pollinate"},{"label":"同根名词（过程）","form":"pollination"},{"label":"同根名词（花粉）","form":"pollen"},{"label":"形容词用法","form":"pollinator-friendly"}],"derivatives":[{"word":"pollinate","pos":"v.","zh":"给……传粉"},{"word":"pollination","pos":"n.","zh":"传粉；授粉"},{"word":"pollen","pos":"n.","zh":"花粉"},{"word":"pollinator-friendly","pos":"adj.","zh":"对传粉者友好的"},{"word":"pollinator-dependent","pos":"adj.","zh":"依赖传粉者的"}],"senses":[{"no":"01","title":"An animal that carries pollen","titleCN":"搬运花粉的动物","definition":"any animal that regularly moves pollen from one flower to another","definitionCN":"经常把花粉从一朵花搬到另一朵花的动物","example":"The bee is the most familiar pollinator in temperate farmland.","exampleCN":"蜜蜂是温带农田中最常见的传粉者。","why":"the -or suffix names the doer, so the word answers who does the carrying rather than what the carrying is.","whyCN":"后缀 -or 命名执行者，因此这个词回答「谁在搬运」，而不是「搬运是什么」。"},{"no":"02","title":"An insect pollinator","titleCN":"昆虫传粉者","definition":"an insect such as a bee, wasp, fly, beetle or moth that moves pollen","definitionCN":"蜜蜂、黄蜂、蝇、甲虫或蛾等搬运花粉的昆虫","example":"Flies take over as pollinators in cold, wet weather.","exampleCN":"在寒冷潮湿的天气里，蝇类接手传粉工作。","why":"insects are the largest group of carriers, so the general word is often used where insect is understood.","whyCN":"昆虫是最大的载体类群，因此这个通名常用于默认指昆虫的语境。"},{"no":"03","title":"A vertebrate pollinator","titleCN":"脊椎动物传粉者","definition":"a bird, bat or small mammal that moves pollen while feeding","definitionCN":"取食时搬运花粉的鸟、蝙蝠或小型哺乳动物","example":"The long-tongued bat is the main pollinator of that cactus.","exampleCN":"长舌蝙蝠是那种仙人掌的主要传粉者。","why":"body size and flight allow vertebrates to serve the same role as insects, so the term covers them without change.","whyCN":"体型与飞行让脊椎动物能担任与昆虫相同的角色，因此这个词不加改变地覆盖它们。"},{"no":"04","title":"Wind as an abiotic carrier","titleCN":"作为非生物媒介的风","definition":"moving air treated as the carrier in wind-pollinated plants","definitionCN":"在风媒植物中被视为载体的流动空气","example":"For grasses, the wind is the only pollinator that matters.","exampleCN":"对禾草而言，风是唯一重要的传粉者。","why":"the word normally implies a living agent, so using it for wind is a deliberate extension of the role, not of the meaning of animal.","whyCN":"这个词通常暗示活的媒介，因此用于风是对「角色」的有意延伸，而不是把词义改指动物。"},{"no":"05","title":"A specialist pollinator","titleCN":"专性传粉者","definition":"a species that pollinates only one or a few plant species","definitionCN":"只为一种或少数几种植物传粉的物种","example":"The fig wasp is an obligate specialist pollinator.","exampleCN":"榕小蜂是严格的专性传粉者。","why":"specialisation is measured by the number of partners, so the term needs a qualifier rather than a new noun.","whyCN":"专化程度以伙伴数量衡量，因此这个词需要限定语而非另造新名词。"},{"no":"06","title":"A generalist pollinator","titleCN":"泛性传粉者","definition":"a species that visits many kinds of flowers","definitionCN":"访问许多种类花的物种","example":"Honeybees are generalists, which makes them useful in mixed orchards.","exampleCN":"蜜蜂是泛性传粉者，因此在混种果园中很有用。","why":"a visitor that accepts many hosts is described by the range of its diet, not by a different word.","whyCN":"接受许多寄主的来访者以其食谱范围来描述，而不是另用一词。"},{"no":"07","title":"A garden built for pollinators","titleCN":"传粉者花园（为其营造的栖息地）","definition":"a planting designed to feed and shelter pollinating animals","definitionCN":"为传粉动物提供食物与庇护的种植区","example":"The school planted a pollinator strip along the fence.","exampleCN":"学校沿围栏种了一条传粉者花带。","why":"the noun moves from the animal to the place prepared for it, a common pattern in ecology compounds.","whyCN":"名词从动物转到为它准备的地方，这是生态复合词中常见的转移。"},{"no":"08","title":"Metaphor: a person who spreads ideas","titleCN":"比喻：在领域间传递想法的人","definition":"figurative, a person who carries a method or idea from one field into another","definitionCN":"比喻用法，指把方法或观念从一个领域带进另一个领域的人","example":"She became a pollinator between laboratory science and classroom practice.","exampleCN":"她成了实验室科学与课堂实践之间的传递者。","why":"the metaphor keeps only the carrying role, dropping the flower and the pollen.","whyCN":"比喻只保留搬运角色，舍去花与花粉。"}],"etymology":{"intro":{"en":"Pollinator is pollinate plus the Latin agent suffix -or, so it means 'the one that pollinates'. The base pollen 'fine flour, dust' has an uncertain deeper origin.","cn":"pollinator 是 pollinate 加拉丁施事后缀 -or，意为「执行传粉的那一个」。词基 pollen「细面粉、粉尘」的更早来源不确定。"},"items":[{"era":"LATIN POLLEN","en":"Pollen meant 'fine flour, mill dust', and the flower grains were named by resemblance.","cn":"pollen 意为「细面粉、磨坊粉尘」，花上的颗粒是凭相似而得名的。"},{"era":"UNCERTAIN ORIGIN","en":"Source uncertain: the ancestry of pollen before Latin is unresolved; the polenta and pulvis connections are hypotheses only.","cn":"来源不确定：pollen 在拉丁语之前的谱系尚无定论；与 polenta、pulvis 的联系仅为假说。"},{"era":"VERB FIRST","en":"Modern Latin pollinare and English pollinate came first; the agent noun followed when ecologists needed to name the carrier.","cn":"先有近代拉丁 pollinare 与英语 pollinate；生态学家需要为搬运者命名时，施事名词才随之出现。"},{"era":"AGENT SUFFIX","en":"Latin -or marks the person or thing that performs an action, as in actor and conveyor.","cn":"拉丁 -or 标记执行动作的人或物，如 actor 与 conveyor。"},{"era":"ECOLOGICAL USE","en":"Pollinator became a standard term in the twentieth century as studies of crop dependence on insects expanded.","cn":"随着作物对昆虫依赖的研究扩展，pollinator 在 20 世纪成为标准术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact first use of pollinator for an animal is not firmly recorded, so the dating here is approximate.","cn":"来源不确定（首见年代）：pollinator 首次用于指动物的确切记录不详，此处系年为约数。"}]},"similar":{"note":{"en":"Group one separates the words of the same pollen family; group two separates the carrier from the things carried and from other ecological roles.","cn":"第一组区分同一 pollen 词族的词；第二组区分载体与被搬运之物以及其他生态角色。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pollinate","ipa":"/ˈpɒlɪneɪt/","tag":"the verb","definition":"The action of carrying pollen; the pollinator is the one that performs it.","definitionCN":"搬运花粉的动作；pollinator 是执行这一动作的那一个。"},{"word":"pollination","ipa":"/ˌpɒlɪˈneɪʃən/","tag":"the process","definition":"The event as a whole, named with -ation; it includes the carrier but is not the carrier.","definitionCN":"整个事件，由 -ation 命名；包含载体，但并不等于载体。"},{"word":"pollen","ipa":"/ˈpɒlən/","tag":"the cargo","definition":"The grains moved; the pollinator is the vehicle, pollen is what it carries.","definitionCN":"被搬运的颗粒；传粉者是载具，花粉是它所载之物。"},{"word":"predator","ipa":"/ˈpredətə/","tag":"same suffix, different role","definition":"Also -or 'one who acts', but it acts by eating; the shared ending does not make the words related in meaning.","definitionCN":"同样由 -or「行动者」构成，但它的行动是捕食；相同的词尾并不使二者词义相关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"disperser","ipa":"/dɪˈspɜːsə/","tag":"moves seeds, not pollen","definition":"An animal or agent that carries seeds or spores away from the parent plant; the destination is the ground, not a stigma.","definitionCN":"把种子或孢子带离母株的动物或媒介；目的地是地面，而不是柱头。"},{"word":"visitor","ipa":"/ˈvɪzɪtə/","tag":"neutral ecological word","definition":"An animal that comes to a flower, whether or not it carries pollen effectively; pollinators are the subset that does.","definitionCN":"来到花上的动物，无论是否有效搬运花粉；传粉者是其中真正做到的那一部分。"},{"word":"vector","ipa":"/ˈvektə/","tag":"technical carrier word","definition":"A general term for an agent that transmits something, including disease; pollinator is the specific ecological case.","definitionCN":"泛指传递某种东西的媒介，包括疾病；pollinator 是其中特定的生态学情形。"},{"word":"nectar","ipa":"/ˈnektə/","tag":"the reward offered","definition":"The sugary liquid a plant provides; it attracts the pollinator but is not the pollinator.","definitionCN":"植物提供的糖液；它吸引传粉者，但不是传粉者本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the agent suffix, the real ecological phrases and the real relatives.","cn":"正常联想：施事后缀、真实的生态学搭配与真实同族词。"},"normal":[{"en":"pollinate + -or: the one that does the pollinating.","cn":"pollinate + -or：执行传粉的那一个。"},{"en":"The same ending names actor and predator, all doers.","cn":"同一词尾构成 actor 与 predator，都是执行者。"},{"en":"Fixed phrases: pollinator decline, pollinator garden, key pollinator.","cn":"固定搭配：传粉者衰退、传粉者花园、关键传粉者。"},{"en":"Four kinds of carrier: bee, fly, bird, bat; wind is the odd fifth.","cn":"四类载体：蜂、蝇、鸟、蝙蝠；风算特殊的第五种。"},{"en":"The family runs pollen, pollinate, pollination, pollinator.","cn":"同族词包括 pollen、pollinate、pollination、pollinator。"}],"abstract":[{"en":"Picture a courier whose bag is full of gold dust.","cn":"想象一名信使，包里装满金粉。"},{"en":"Picture a field edge left unmown on purpose so that the carriers survive the season.","cn":"想象田边特意留着一片不割的草，好让这些搬运者熬过一季。"},{"en":"Picture a person who brings a borrowed method home and makes it work.","cn":"想象一个人把借来的方法带回家，并让它奏效。"}]},"examples":[{"en":"Pollinator numbers have fallen sharply in the region.","cn":"该地区的传粉者数量急剧下降。"},{"en":"The orchard plantings a pollinator strip beside every block.","cn":"果园在每一片地块旁种上一条传粉者花带。"},{"en":"A single generalist pollinator can serve many crops.","cn":"一种泛性传粉者就能服务许多作物。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pollinate（传粉）+ or（做某事者）」——负责传粉的那一位 → 传粉者","word":"pollinator"},"root":"拉丁 pollen, pollinis「细面粉、粉尘」→ pollinate + -or（施事）。pollen 更早来源不确定，与 polenta、pulvis 的联系仅为假说。","sensesIntro":{"en":"Eight senses of pollinator stay close to one role: whoever or whatever performs the carrying, from a bee to a bat to the wind, and finally to a person carrying ideas.","cn":"pollinator 的八个义项都围绕一个角色：执行搬运的那一位或那一种，从蜂到蝙蝠再到风，最后到搬运观念的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pollen-laden body arriving at the next flower.","cn":"核心意象：沾满花粉的身体抵达下一朵花。"},"chain":["CARRIER","INSECT","VERTEBRATE","WIND","SPECIALIST","GENERALIST"],"branches":[{"senses":"01 · 02","en":"THE BASIC ROLE: an insect that moves pollen is the default case.","cn":"基本角色：搬运花粉的昆虫是默认情形。"},{"senses":"03 · 04","en":"WIDER CARRIERS: vertebrates and moving air can do the same work.","cn":"更广的载体：脊椎动物与流动空气能做同样的工作。"},{"senses":"05 · 06","en":"NARROW OR BROAD DIET: specialists and generalists split the role by range of hosts.","cn":"窄食或广食：专性与泛性按寄主范围划分这一角色。"},{"senses":"07","en":"PLACE FOR THE ROLE: a garden can be named after the animals it supports.","cn":"为角色留地：花园可以按它所供养的动物来命名。"},{"senses":"08","en":"HUMAN CARRIER: only the transporting part survives the metaphor.","cn":"人的载体：比喻中只剩下「搬运」这一部分。"}]},"affixes":{"intro":{"en":"Pollinator is a verb plus an agent suffix, and its family names the cargo, the action, the process and the carrier separately.","cn":"pollinator 是动词加施事后缀，其词族把货物、动作、过程与载体分开命名。"},"latinIntro":{"en":"Latin pollen 'dust' gives pollen and pollinare; English builds pollinate, pollination and pollinator on that base.","cn":"拉丁 pollen「粉尘」衍生 pollen 与 pollinare；英语在此基础上构成 pollinate、pollination 与 pollinator。"},"items":[{"word":"pollen","structure":"pollen, pollinis (n., third declension)","meaning":"fine flour, dust","meaningCN":"细面粉；粉尘","example":"Pollen is the cargo the carrier moves.","exampleCN":"花粉是载体搬运的货物。"},{"word":"-ate","structure":"-atus (Latin verb suffix)","meaning":"to perform an action","meaningCN":"执行动作","example":"Pollinate means to move the grains.","exampleCN":"pollinate 意为搬运这些颗粒。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"the process","meaningCN":"过程","example":"Pollination is the process the carrier performs.","exampleCN":"pollination 是载体所执行的过程。"},{"word":"-or","structure":"-or (Latin agent suffix)","meaning":"one who or that which performs","meaningCN":"执行者","example":"The -or marks the doer of the action.","exampleCN":"-or 标记动作的执行者。"},{"word":"pollinate","structure":"pollen + -ate","meaning":"to carry pollen","meaningCN":"给……传粉","example":"The bee pollinates the blossom.","exampleCN":"蜜蜂给花传粉。"},{"word":"pollination","structure":"pollinate + -ation","meaning":"the carrying of pollen","meaningCN":"传粉","example":"Pollination happens before fertilization.","exampleCN":"传粉发生在受精之前。"},{"word":"pollinator-friendly","structure":"pollinator + -friendly (compound adjective)","meaning":"designed to support pollinators","meaningCN":"对传粉者友好的","example":"The farm uses pollinator-friendly borders.","exampleCN":"农场采用对传粉者友好的边界种植。"},{"word":"pollinator-dependent","structure":"pollinator + dependent (compound adjective)","meaning":"relying on animals for pollen transfer","meaningCN":"依赖传粉者的","example":"Most orchard crops are pollinator-dependent.","exampleCN":"大多数果园作物依赖传粉者。"}],"latinEntries":[{"word":"pollen","structure":"pollen, pollinis (n., third declension)","meaning":"fine flour, dust","meaningCN":"细面粉；粉尘"},{"word":"pollinare","structure":"pollinare (verb, Modern Latin, first conjugation)","meaning":"to dust with pollen","meaningCN":"给……撒花粉"},{"word":"pollinator","structure":"pollinator, pollinatoris (m., Modern Latin, third declension)","meaning":"one that carries pollen","meaningCN":"传粉者"}]}},{"word":"germination","ipa_uk":"/ˌdʒɜːmɪˈneɪʃən/","ipa_us":"/ˌdʒɝːməˈneɪʃən/","definition_zh":"萌发；发芽；开始生长","definition_en":"the beginning of growth in a seed or spore, especially the moment it breaks out of its coat","core_image":"一粒种子吸水膨胀，白色的胚根顶破种皮，伸进湿土","scene":"培养箱里，一排培养皿放在恒温架上，第七天早晨其中几粒种子先后裂开。 Germination began on the seventh day, when the first radicle broke through the coat.","sceneCN":"这里 germination 指「萌发」（第 1 个义项：胚根突破种皮开始生长）；句意为萌发在第七天开始，第一支胚根突破了种皮。","pos":[{"tag":"n.","zh":"萌发；发芽；萌发过程"}],"collocations":[{"phrase":"seed germination","zh":"种子萌发"},{"phrase":"germination rate","zh":"发芽率"},{"phrase":"germination test","zh":"发芽试验"},{"phrase":"germination percentage","zh":"发芽百分率"},{"phrase":"spore germination","zh":"孢子萌发"},{"phrase":"pollen germination","zh":"花粉萌发"}],"forms":[{"label":"原形","form":"germination"},{"label":"复数","form":"germinations"},{"label":"同根动词","form":"germinate"},{"label":"同根形容词","form":"germinative"},{"label":"相关名词（胚）","form":"germ"},{"label":"相关形容词","form":"germinal"}],"derivatives":[{"word":"germinate","pos":"v.","zh":"发芽；使发芽"},{"word":"germ","pos":"n.","zh":"胚；芽；病菌"},{"word":"germinal","pos":"adj.","zh":"胚的；初期的"},{"word":"germinative","pos":"adj.","zh":"有发芽力的"},{"word":"germinability","pos":"n.","zh":"发芽能力"}],"senses":[{"no":"01","title":"Breaking out of the seed coat","titleCN":"胚根突破种皮","definition":"the first visible step of growth, when the young root emerges from the seed","definitionCN":"生长的第一个可见步骤，幼根从种子中伸出","example":"Germination is complete once the radicle has emerged.","exampleCN":"胚根一旦伸出，萌发就完成了。","why":"the word marks a threshold rather than a gradual process: something enclosed becomes something exposed.","whyCN":"这个词标记的是一个门槛，而不是渐进过程：被包住的东西变成暴露的东西。"},{"no":"02","title":"The uptake of water that starts it","titleCN":"启动萌发的吸水（吸胀）","definition":"the swelling that follows water uptake and precedes visible growth","definitionCN":"吸水之后、可见生长之前的膨胀","example":"Germination begins with imbibition, long before any root appears.","exampleCN":"萌发从吸胀开始，远在根出现之前。","why":"water is the switch, so the same noun is used for the hidden stage that makes the visible stage possible.","whyCN":"水是开关，因此同一个名词也用于那个使可见阶段成为可能的隐藏阶段。"},{"no":"03","title":"The rate at which seeds sprout","titleCN":"发芽率；萌发速率","definition":"the proportion or speed of seeds that successfully sprout in a batch","definitionCN":"一批种子中成功发芽的比例或速度","example":"Cold storage lowered the germination rate to sixty percent.","exampleCN":"冷藏把发芽率降到了六成。","why":"a mass process needs a number, so the noun becomes the measurable quantity rather than the single event.","whyCN":"群体过程需要一个数，因此名词变成可计量的量，而不只是单次事件。"},{"no":"04","title":"A test of seed quality","titleCN":"发芽试验","definition":"a standard procedure for counting how many seeds in a sample sprout","definitionCN":"统计样本中有多少种子发芽的标准程序","example":"The lab runs a germination test before the lot is sold.","exampleCN":"实验室在出售这批种子之前做发芽试验。","why":"the process is turned into an industrial check, so the noun names the procedure itself.","whyCN":"这一过程被变成工业检验，因此名词命名的是程序本身。"},{"no":"05","title":"Sprouting of a spore","titleCN":"孢子萌发","definition":"the emergence of a growth tube from a fungal, fern or moss spore","definitionCN":"真菌、蕨或苔藓的孢子伸出生长管","example":"Spore germination requires a damp film on the leaf.","exampleCN":"孢子萌发需要叶面有一层水膜。","why":"spores use the same threshold as seeds, so the botanical noun is borrowed for them unchanged.","whyCN":"孢子与种子跨过同样的门槛，因此植物学的名词原样借用于它们。"},{"no":"06","title":"Pollen tube growth on a stigma","titleCN":"花粉在柱头上的萌发","definition":"the growth of a pollen tube after a grain lands on a compatible stigma","definitionCN":"花粉落到亲和的柱头后长出花粉管","example":"Pollen germination fails on a stigma of the wrong species.","exampleCN":"花粉落到异种柱头上时萌发失败。","why":"the grain behaves like a seed on soil, so the term travels to the flower's receiving surface.","whyCN":"花粉粒在柱头上的表现如同种子落在土上，这个词因此移到花的接受面。"},{"no":"07","title":"Sprouting after dormancy ends","titleCN":"休眠解除后的萌发","definition":"the resumption of growth once a dormant seed's block is removed","definitionCN":"休眠种子的阻碍被解除后重新开始生长","example":"Scarifying the coat synchronised germination across the batch.","exampleCN":"划破种皮使整批种子同步萌发。","why":"dormancy is defined as the absence of germination, so the noun also names what happens when the absence ends.","whyCN":"休眠被定义为「不萌发」，因此名词也命名这种缺席结束时所发生的事。"},{"no":"08","title":"Metaphor: an idea beginning to grow","titleCN":"比喻：想法开始生发","definition":"figurative, the first stage of an idea or plan becoming active","definitionCN":"比喻用法，指想法或计划开始活跃的第一阶段","example":"The germination of the project took a year of quiet conversations.","exampleCN":"这个项目的萌生用了一年安静的交谈。","why":"the metaphor keeps the threshold image: something small and enclosed becomes visible and growing.","whyCN":"比喻保留门槛意象：小而封闭的东西变得可见并开始生长。"}],"etymology":{"intro":{"en":"Germination is the noun of germinate, from Latin germinare 'to sprout', built on germen 'sprout, bud, seed'. The deeper origin of germen is uncertain. Dates are approximate.","cn":"germination 是 germinate 的名词，来自拉丁 germinare「发芽」，建立在 germen「芽、胚、种子」之上。germen 的更早来源不确定。年代均为约数。"},"items":[{"era":"LATIN GERMEN","en":"Germen meant 'sprout, bud, offshoot, seed'; it named the living point from which a plant extends.","cn":"germen 意为「芽、幼枝、种子」；它命名的是一株植物向外伸展的那个活的起点。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain: the pre-Latin ancestry of germen is not established; the link to a root meaning 'to produce, beget' is a common reconstruction rather than a demonstrated derivation.","cn":"来源不确定：germen 在拉丁语之前的谱系未得证明；把它连到意为「产生、生育」的词根，是常见的重构，而非已证实的派生。"},{"era":"LATIN GERMINARE","en":"Germinare 'to sprout, bud' gave the verb whose noun is germinatio.","cn":"germinare「发芽、抽芽」提供了动词，其名词形式为 germinatio。"},{"era":"ENGLISH VERB","en":"English germinate is recorded in the seventeenth century, and germination follows as its noun.","cn":"英语 germinate 自 17 世纪有记录，germination 随之成为其名词。"},{"era":"SCIENTIFIC USE","en":"Seed-testing laboratories in the nineteenth century made germination a measured quantity rather than a single observed event.","cn":"19 世纪的种子检验实验室把萌发变成可计量的量，而不只是一次观察到的个别事件。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest printed use of germination is not firmly dated, so the seventeenth-century placement is approximate.","cn":"来源不确定（首见年代）：germination 最早见于印刷的时间没有确证，因此归于 17 世纪只是约数。"}]},"similar":{"note":{"en":"Group one separates the germ- words that look alike; group two separates the start of growth from the stages that follow or precede it.","cn":"第一组区分外形相近的 germ- 系词；第二组区分生长的开始与其前后阶段。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"germinate","ipa":"/ˈdʒɜːmɪneɪt/","tag":"the verb","definition":"To sprout; the verb is what the seed does, the noun is what happens.","definitionCN":"发芽；动词是种子所做的，名词是所发生的事。"},{"word":"germ","ipa":"/ˈdʒɜːm/","tag":"the source point","definition":"The embryo inside a seed, or a disease-causing microbe; the shared root means 'sprout', not 'disease'.","definitionCN":"种子内的胚，或致病微生物；共同词根意为「芽」，并非「疾病」。"},{"word":"germinal","ipa":"/ˈdʒɜːmɪnəl/","tag":"adjective of the germ","definition":"Relating to a germ or to an early stage; it describes a stage, not the act of sprouting.","definitionCN":"与胚或早期阶段有关；描述阶段，而非发芽的动作。"},{"word":"german","ipa":"/ˈdʒɜːmən/","tag":"different word entirely","definition":"The name of a people and a language, unrelated to germen despite the spelling; it comes from Latin Germanus.","definitionCN":"民族与语言的名称，尽管拼写相似，却与 germen 无关；它来自拉丁 Germanus。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sprouting","ipa":"/ˈspraʊtɪŋ/","tag":"everyday word","definition":"The common word for a shoot appearing; germination is the technical term for the same threshold, extended to spores and pollen.","definitionCN":"嫩芽出现的日常说法；germination 是同一门槛的术语说法，并扩展到孢子与花粉。"},{"word":"fertilization","ipa":"/ˌfɜːtɪlaɪˈzeɪʃən/","tag":"earlier stage in flowers","definition":"The fusion of gametes, which in flowering plants precedes germination of the resulting seed.","definitionCN":"配子的融合；在开花植物中，它先于由此形成的种子萌发。"},{"word":"dormancy","ipa":"/ˈdɔːmənsi/","tag":"the paused state","definition":"The state in which a seed will not sprout even when conditions seem right; germination is what dormancy blocks.","definitionCN":"即使条件看似合适种子也不发芽的状态；萌发正是休眠所阻止的事。"},{"word":"emergence","ipa":"/ɪˈmɜːdʒəns/","tag":"appearing above ground","definition":"The seedling's appearance above the soil surface, a later and separate event from germination underground.","definitionCN":"幼苗露出土面，是萌发之后另一个独立事件。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real root, the seed-testing phrases and the real relatives.","cn":"正常联想：真实的词根、种子检验搭配与真实同族词。"},"normal":[{"en":"germen 'sprout' + -ation: the sprouting, named as a process.","cn":"germen「芽」+ -ation：把发芽这件事作为过程来命名。"},{"en":"The same root gives germ, germinate, germinal.","cn":"同一词根衍生 germ、germinate、germinal。"},{"en":"Fixed phrases: germination rate, germination test, spore germination.","cn":"固定搭配：发芽率、发芽试验、孢子萌发。"},{"en":"The threshold is visible: nothing shows until the radicle breaks through.","cn":"门槛是可见的：胚根突破之前什么也看不见。"},{"en":"Water starts it; dormancy delays it; scarifying synchronises it.","cn":"水启动它，休眠推迟它，划破种皮让它同步。"}],"abstract":[{"en":"Picture a sealed packet that splits along one seam and lets light in.","cn":"想象一个密封的包裹沿一条缝裂开，光透了进来。"},{"en":"Picture a conversation so quiet that nobody notices until a plan exists.","cn":"想象一场安静的交谈，直到计划成形才有人注意到。"},{"en":"Picture a dormant field that turns green within a week of the first rain.","cn":"想象一片休眠的田，在初雨之后一周内变绿。"}]},"examples":[{"en":"Germination was uneven because the seed lot was old.","cn":"由于种子批次陈旧，萌发参差不齐。"},{"en":"The germination test showed ninety percent viability.","cn":"发芽试验显示九成的存活率。"},{"en":"Pollen germination on the stigma takes about six hours.","cn":"花粉在柱头上萌发约需六小时。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「germ（芽）+ ination」——芽从种皮里冒出来 → 萌发","word":"germination"},"root":"拉丁 germen, germinis「芽、胚、种子」→ germinare「发芽」→ germinatio → 英语 germination。germen 的更早来源不确定，与「产生、生育」词根的联系属重构。","sensesIntro":{"en":"Eight senses of germination follow one threshold: something enclosed takes in water, swells, and breaks out, whether it is a seed, a spore, a pollen grain or an idea.","cn":"germination 的八个义项跨过同一个门槛：封闭之物吸水、膨胀、破壳而出，无论那是种子、孢子、花粉粒还是一个想法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pale root pushing through a split coat into wet soil.","cn":"核心意象：一支白色的根从裂开的种皮里顶出，伸进湿土。"},"chain":["WATER UPTAKE","SWELLING","RUPTURE","FIRST ROOT","MEASURED RATE","IDEA SPROUTS"],"branches":[{"senses":"01 · 02","en":"THE THRESHOLD: invisible swelling turns into a visible break.","cn":"门槛：看不见的膨胀变成看得见的突破。"},{"senses":"03 · 04","en":"THE NUMBER: a batch is counted, so the event becomes a rate and a test.","cn":"数字：对一批种子计数，事件因此变成比率与试验。"},{"senses":"05 · 06","en":"OTHER BODIES: spores and pollen grains cross the same threshold.","cn":"其他个体：孢子与花粉粒跨过同一门槛。"},{"senses":"07","en":"THE BLOCK REMOVED: dormancy is defined by the absence of this event.","cn":"阻碍解除：休眠正以这件事的缺席来定义。"},{"senses":"08","en":"THE METAPHOR: a plan can swell and break out too.","cn":"比喻：计划也会膨胀并破壳。"}]},"affixes":{"intro":{"en":"Germination is a Latin root plus a noun suffix, and the family covers both the living point and the act of emerging from it.","cn":"germination 是拉丁词根加名词后缀，其词族既覆盖那个活的起点，也覆盖从它冒出的动作。"},"latinIntro":{"en":"Latin germen 'sprout' yields germinare and germinatio; English draws germ, germinate, germination, germinal and germinative from the same stock.","cn":"拉丁 germen「芽」衍生 germinare 与 germinatio；英语的 germ、germinate、germination、germinal 与 germinative 都取自同一词族。"},"items":[{"word":"germen","structure":"germen, germinis (n., third declension)","meaning":"sprout, bud, seed","meaningCN":"芽；胚；种子","example":"The root names the point of new growth.","exampleCN":"这个词根命名新生的起点。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"the act or process of","meaningCN":"动作或过程","example":"Germination names the process of sprouting.","exampleCN":"germination 命名发芽的过程。"},{"word":"germ","structure":"germen shortened in English","meaning":"embryo of a seed; a microbe","meaningCN":"胚；病菌","example":"The germ is the living point inside the seed.","exampleCN":"胚是种子内部那个活的起点。"},{"word":"germinate","structure":"germen + -ate","meaning":"to sprout","meaningCN":"发芽","example":"The seeds germinate within a week.","exampleCN":"这些种子一周内发芽。"},{"word":"germinative","structure":"germinate + -ive","meaning":"having the power to sprout","meaningCN":"有发芽力的","example":"The germinative capacity fell after storage.","exampleCN":"贮藏之后发芽能力下降。"},{"word":"germinal","structure":"germen + -al","meaning":"relating to a germ or early stage","meaningCN":"胚的；初期的","example":"The idea was still germinal at that meeting.","exampleCN":"那次会上这个想法仍处初期。"},{"word":"germinability","structure":"germinable + -ity","meaning":"the ability to sprout","meaningCN":"发芽能力","example":"Germinability varies with harvest date.","exampleCN":"发芽能力随收获日期而变化。"},{"word":"germination rate","structure":"germination + rate (compound term)","meaning":"the share of seeds that sprout","meaningCN":"发芽率","example":"The germination rate was recorded after ten days.","exampleCN":"十天后记录了发芽率。"}],"latinEntries":[{"word":"germen","structure":"germen, germinis (n., third declension)","meaning":"sprout, bud, seed","meaningCN":"芽；胚；种子"},{"word":"germinare","structure":"germinare, germinavi, germinatum (verb, first conjugation)","meaning":"to sprout, bud","meaningCN":"发芽；抽芽"},{"word":"germinatio","structure":"germinatio, germinationis (f., third declension)","meaning":"a sprouting","meaningCN":"发芽；萌发"},{"word":"germinalis","structure":"germinalis, germinale (adjective, third declension)","meaning":"of a sprout, budding","meaningCN":"芽的；初生的"}]}},{"word":"germinate","ipa_uk":"/ˈdʒɜːmɪneɪt/","ipa_us":"/ˈdʒɝːməneɪt/","definition_zh":"发芽；萌发；使发芽","definition_en":"to begin to grow from a seed or spore, or to make such a thing begin to grow","core_image":"一粒豆子在湿纸巾里撑开种皮，白色的小根向下探","scene":"厨房里，一把湿纸巾裹着几粒豆子，放在温暖的窗边。 After five days in damp paper, the beans germinate and push a pale root out of their coats.","sceneCN":"这里 germinate 指「发芽」（第 1 个义项：种子开始长出幼根）；句意为在湿纸里放了五天后，豆子发芽，把白色的根顶出种皮。","pos":[{"tag":"vi.","zh":"发芽；萌发；开始生长"},{"tag":"vt.","zh":"使发芽；催芽"}],"collocations":[{"phrase":"germinate seeds","zh":"使种子发芽；催芽"},{"phrase":"germinate barley","zh":"使大麦发芽（制麦）"},{"phrase":"germinate quickly","zh":"很快发芽"},{"phrase":"germinate in the dark","zh":"在暗处发芽"},{"phrase":"germinate readily","zh":"容易发芽"},{"phrase":"germinate on the stigma","zh":"在柱头上萌发"}],"forms":[{"label":"三单（he/she/it）","form":"germinates"},{"label":"过去式","form":"germinated"},{"label":"过去分词","form":"germinated"},{"label":"现在分词","form":"germinating"},{"label":"名词（萌发）","form":"germination"},{"label":"名词（胚）","form":"germ"}],"derivatives":[{"word":"germination","pos":"n.","zh":"萌发；发芽"},{"word":"germ","pos":"n.","zh":"胚；病菌"},{"word":"germinal","pos":"adj.","zh":"胚的；初期的"},{"word":"germinative","pos":"adj.","zh":"有发芽力的"},{"word":"ungerminated","pos":"adj.","zh":"未发芽的"}],"senses":[{"no":"01","title":"A seed begins to grow","titleCN":"种子发芽","definition":"of a seed, to break out of its coat and start growing","definitionCN":"指种子突破种皮并开始生长","example":"The beans germinate in about five days.","exampleCN":"豆子约五天发芽。","why":"the verb is intransitive here: the seed is the one that crosses the threshold, with no outside hand.","whyCN":"这里动词是不及物的：跨过门槛的是种子自己，没有外来的手。"},{"no":"02","title":"Make seeds sprout on purpose","titleCN":"使种子发芽；催芽","definition":"to cause seeds to begin growing before they are planted","definitionCN":"在播种之前使种子开始生长","example":"Soak the peas and germinate them on a tray.","exampleCN":"把豌豆泡水，然后在托盘上催芽。","why":"the transitive use adds an agent who controls the conditions, so the same verb takes a gardener as subject.","whyCN":"及物用法增加了一个控制条件的施动者，因此同一个动词可以以园丁为主语。"},{"no":"03","title":"Sprout grain for malting","titleCN":"使谷物发芽（制麦）","definition":"to start the growth of barley or other grain so that its starch changes","definitionCN":"使大麦等谷物开始生长，从而改变其中的淀粉","example":"Maltsters germinate the barley for four days.","exampleCN":"制麦师让大麦发芽四天。","why":"controlled sprouting is a manufacturing step, so the verb enters industry unchanged.","whyCN":"受控发芽是一道制造工序，动词因此原样进入工业。"},{"no":"04","title":"A spore begins to grow","titleCN":"孢子萌发","definition":"of a fungal or fern spore, to produce a first growth tube","definitionCN":"指真菌或蕨的孢子长出第一根生长管","example":"The spores germinate only on a wet surface.","exampleCN":"这些孢子只在湿润表面萌发。","why":"spores repeat the seed's gesture, so the botanical verb extends to them without a new word.","whyCN":"孢子重复种子的动作，因此植物学动词不加新词便延伸到它们。"},{"no":"05","title":"A pollen grain grows a tube","titleCN":"花粉在柱头上萌发","definition":"of a pollen grain, to produce a tube after landing on a compatible stigma","definitionCN":"指花粉粒落在亲和柱头后长出花粉管","example":"The pollen grains germinate within hours of landing.","exampleCN":"花粉粒落地数小时内就萌发。","why":"the tube is the grain's root, so the verb keeps its literal growing sense inside a flower.","whyCN":"花粉管就是花粉粒的根，因此动词在花内仍保留字面的生长义。"},{"no":"06","title":"Metaphor: an idea starts to develop","titleCN":"比喻：想法开始萌生","definition":"figurative, of a plan or feeling, to begin to develop from a small beginning","definitionCN":"比喻用法，指计划或情感从小处开始发展","example":"The idea germinated while she was walking home.","exampleCN":"这个想法在她走路回家时萌生了。","why":"the metaphor keeps the threshold and the hidden start, so nothing is visible until it breaks out.","whyCN":"比喻保留了门槛与隐蔽的起点，因此在破壳之前什么也看不见。"},{"no":"07","title":"Sprout under the right conditions","titleCN":"在适宜条件下萌发","definition":"to begin growth when warmth, moisture and air allow it","definitionCN":"在温度、水分与空气允许时开始生长","example":"These seeds germinate only when the soil reaches fifteen degrees.","exampleCN":"这些种子只有在土温达到十五度时才发芽。","why":"conditions are the gate, so the verb often appears with an only-when clause.","whyCN":"条件是闸门，因此这个动词常与「只有……才」从句连用。"},{"no":"08","title":"Chit seed potatoes before planting","titleCN":"播前催芽（种薯）","definition":"to encourage short shoots on tubers before they go into the ground","definitionCN":"在入土之前促使块茎长出短芽","example":"Gardeners germinate their seed potatoes in a cool, bright shed.","exampleCN":"园丁在阴凉明亮的棚里给种薯催芽。","why":"a tuber is not a seed but behaves like one at planting time, so the verb follows the practical resemblance.","whyCN":"块茎不是种子，但在播种时表现得像种子，动词于是跟着实际相似性走。"}],"etymology":{"intro":{"en":"Germinate comes from Latin germinare 'to sprout', from germen 'sprout, bud, seed'. The deeper origin of germen is uncertain. Dates are approximate.","cn":"germinate 来自拉丁 germinare「发芽」，后者出自 germen「芽、胚、种子」。germen 的更早来源不确定。年代均为约数。"},"items":[{"era":"LATIN GERMEN","en":"Germen named a sprout or bud, the living point from which a plant extends.","cn":"germen 指芽或幼枝，即植物向外伸展的那个活的起点。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain: the ancestry of germen before Latin is not settled; a link to a root meaning 'produce, beget' is a reconstruction, not a demonstrated derivation.","cn":"来源不确定：germen 在拉丁语之前的谱系没有定论；把它连到意为「产生、生育」的词根属于重构，而非已证实的派生。"},{"era":"LATIN GERMINARE","en":"Germinare 'to sprout' is a first-conjugation verb built on germen; its noun is germinatio.","cn":"germinare「发芽」是建立在 germen 上的第一变位动词；其名词为 germinatio。"},{"era":"ENGLISH VERB","en":"English germinate appears in the seventeenth century, first of plants and later of spores and pollen.","cn":"英语 germinate 于 17 世纪出现，先指植物，后指孢子与花粉。"},{"era":"INDUSTRIAL SENSE","en":"Malting gave the verb a manufacturing sense, since controlled sprouting is how barley starch is made available.","cn":"制麦给了这个动词工业义，因为受控发芽正是让大麦淀粉变得可用的方式。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest printed use of germinate is not firmly established; the seventeenth-century placement is approximate.","cn":"来源不确定（首见年代）：germinate 最早见于印刷的时间没有确证；归于 17 世纪只是约数。"}]},"similar":{"note":{"en":"Group one separates the germ- family by word class and spelling; group two separates sprouting from the stages before and after it.","cn":"第一组按词类与拼写区分 germ- 词族；第二组区分发芽与其前后阶段。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"germination","ipa":"/ˌdʒɜːmɪˈneɪʃən/","tag":"the noun","definition":"The process the verb names; the verb says what happens, the noun says what it is called.","definitionCN":"动词所指的过程；动词说发生了什么，名词说它叫什么。"},{"word":"germ","ipa":"/dʒɜːm/","tag":"the living point","definition":"The embryo or a microbe; the verb needs a germ to act on, but the germ is not the action.","definitionCN":"胚或微生物；动词需要有胚才能作用，但胚不是动作。"},{"word":"germinal","ipa":"/ˈdʒɜːmɪnəl/","tag":"adjective of stage","definition":"Relating to an early stage; it describes where something is, not that it is sprouting.","definitionCN":"与早期阶段有关；描述事物所处的位置，而非它正在发芽。"},{"word":"germane","ipa":"/dʒɜːˈmeɪn/","tag":"different root","definition":"From Latin germanus 'closely related', not germen; it means relevant, and the resemblance is accidental.","definitionCN":"来自拉丁 germanus「近亲的」，并非 germen；意为相关，相似纯属巧合。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sprout","ipa":"/spraʊt/","tag":"everyday word","definition":"The common verb for a shoot appearing; germinate is its technical counterpart, used in labs and seed testing.","definitionCN":"嫩芽出现的日常动词；germinate 是它在实验室与种子检验中的术语对应词。"},{"word":"bud","ipa":"/bʌd/","tag":"a different structure","definition":"To form a bud, the small swelling that will become a shoot or flower; buds form after germination, not during it.","definitionCN":"形成芽，即日后长成枝条或花的小突起；芽在发芽之后形成，而不在发芽之中。"},{"word":"fertilize","ipa":"/ˈfɜːtɪlaɪz/","tag":"fusion, not sprouting","definition":"To join gametes or feed soil; in a flower it happens before the seed can germinate.","definitionCN":"使配子结合或给土壤施肥；在花中它发生在种子能够发芽之前。"},{"word":"incubate","ipa":"/ˈɪŋkjubeɪt/","tag":"keeping conditions right","definition":"To keep eggs or cultures at the right warmth so that development can proceed; it names the care, not the emergence.","definitionCN":"把卵或培养物保持在合适温度，使发育得以进行；它指照料，而非破出。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real root, the real agricultural phrases and the real relatives.","cn":"正常联想：真实的词根、真实的农事搭配与真实同族词。"},"normal":[{"en":"germen 'sprout' + -ate: to do the sprout thing.","cn":"germen「芽」+ -ate：做「发芽」这件事。"},{"en":"The same root gives germ, germinal, germination.","cn":"同一词根衍生 germ、germinal、germination。"},{"en":"Fixed phrases: germinate seeds, germinate barley, germinate quickly.","cn":"固定搭配：催芽、使大麦发芽、很快发芽。"},{"en":"Water, warmth and air are the three gates the verb waits behind.","cn":"水、温度与空气是这个动词所等待的三道闸门。"},{"en":"Both seeds and spores take the same verb.","cn":"种子与孢子都接受同一个动词。"}],"abstract":[{"en":"Picture a parcel splitting at one seam and a small root slipping out.","cn":"想象一个包裹沿一条缝裂开，一小段根滑了出来。"},{"en":"Picture a bare field that shows green only after the third warm day.","cn":"想象一片裸地，只在第三个暖日之后才露绿。"},{"en":"Picture a remark that stays quiet for months and then becomes a plan.","cn":"想象一句话安静了几个月，然后变成一项计划。"}]},"examples":[{"en":"The seeds germinate within a week if kept moist.","cn":"保持湿润的话，这些种子一周内发芽。"},{"en":"Farmers germinate barley before it goes to the malt floor.","cn":"农民在把大麦送去制麦之前先让它发芽。"},{"en":"The idea germinated during a long walk.","cn":"这个想法在一次长距离散步中萌生。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「germ（芽）+ inate」——让芽从种皮里出来 → 发芽","word":"germinate"},"root":"拉丁 germen, germinis「芽、胚、种子」→ germinare「发芽」→ 英语 germinate。germen 更早来源不确定，与「产生、生育」词根的联系属重构。","sensesIntro":{"en":"Eight senses of germinate all cross one threshold: something enclosed starts to grow, whether the grower is nature, a gardener, a maltster or a laboratory.","cn":"germinate 的八个义项都跨过同一个门槛：封闭之物开始生长，无论促成者是自然、园丁、制麦师还是实验室。"},"semanticMap":{"core":{"en":"CORE IMAGE: a coat splits and a root reaches down.","cn":"核心意象：种皮裂开，一支根向下探。"},"chain":["SEED BREAKS","INTENTIONAL CHITTING","GRAIN FOR MALT","SPORE TUBE","POLLEN TUBE","IDEA BEGINS"],"branches":[{"senses":"01 · 07","en":"NATURAL START: the seed does it itself once the conditions allow.","cn":"自然开始：条件许可时，种子自己完成。"},{"senses":"02 · 08","en":"HUMAN START: a gardener can force the same event on a tray or a tuber.","cn":"人为开始：园丁能在托盘或块茎上促成同样的事件。"},{"senses":"03","en":"INDUSTRIAL START: controlled sprouting makes grain starch usable.","cn":"工业开始：受控发芽使谷物淀粉变得可用。"},{"senses":"04 · 05","en":"OTHER GRAINS: spores and pollen repeat the gesture at a smaller scale.","cn":"其他颗粒：孢子与花粉在更小尺度上重复同一动作。"},{"senses":"06","en":"METAPHOR: a plan crosses the same threshold quietly.","cn":"比喻：计划同样安静地跨过这一门槛。"}]},"affixes":{"intro":{"en":"Germinate is a Latin noun turned into a verb, and the same base yields the embryo, the act and the capacity.","cn":"germinate 是拉丁名词转成的动词，同一词基衍生出胚、动作与能力。"},"latinIntro":{"en":"Latin germen 'sprout' gives germinare; English builds germ, germinate, germination and germinal from the same stock.","cn":"拉丁 germen「芽」衍生 germinare；英语在同一词族上构成 germ、germinate、germination 与 germinal。"},"items":[{"word":"germen","structure":"germen, germinis (n., third declension)","meaning":"sprout, bud, seed","meaningCN":"芽；胚；种子","example":"Germen names the point of new growth.","exampleCN":"germen 命名新生的起点。"},{"word":"-ate","structure":"-atus (Latin verb suffix)","meaning":"to make or perform","meaningCN":"使……；执行","example":"Germinate means to perform the sprouting.","exampleCN":"germinate 意为执行发芽。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"the process of","meaningCN":"……的过程","example":"Germination names the process.","exampleCN":"germination 命名这一过程。"},{"word":"-ive","structure":"-ivus (Latin adjective suffix)","meaning":"tending to, having the power to","meaningCN":"有……倾向或能力的","example":"Germinative seeds sprout readily.","exampleCN":"有发芽力的种子容易发芽。"},{"word":"germ","structure":"germen shortened in English","meaning":"seed embryo; a microbe","meaningCN":"胚；病菌","example":"Each germ holds a tiny plant.","exampleCN":"每个胚里都藏着一株小小的植物。"},{"word":"germination","structure":"germinate + -ation","meaning":"the act of sprouting","meaningCN":"萌发","example":"Germination needs moisture.","exampleCN":"萌发需要水分。"},{"word":"germinal","structure":"germen + -al","meaning":"of a germ or an early stage","meaningCN":"胚的；初期的","example":"The plan was still germinal.","exampleCN":"这项计划仍处初期。"},{"word":"germinability","structure":"germinable + -ity","meaning":"the capacity to sprout","meaningCN":"发芽能力","example":"Germinability drops with long storage.","exampleCN":"长期贮藏会使发芽能力下降。"}],"latinEntries":[{"word":"germen","structure":"germen, germinis (n., third declension)","meaning":"sprout, bud, seed","meaningCN":"芽；胚；种子"},{"word":"germinare","structure":"germinare, germinavi, germinatum (verb, first conjugation)","meaning":"to sprout","meaningCN":"发芽"},{"word":"germinatio","structure":"germinatio, germinationis (f., third declension)","meaning":"a sprouting","meaningCN":"发芽"},{"word":"germinalis","structure":"germinalis, germinale (adjective, third declension)","meaning":"of a sprout","meaningCN":"芽的；初生的"}]}},{"word":"seedling","ipa_uk":"/ˈsiːdlɪŋ/","ipa_us":"/ˈsiːdlɪŋ/","definition_zh":"幼苗；由种子长成的小苗","definition_en":"a very young plant that has grown from a seed and is not yet mature","core_image":"育苗盘里一株小小的番茄苗，两片圆圆的子叶顶在细茎上","scene":"温室里，育苗盘排成几行，刚出土的番茄只有两片圆叶。 Each seedling in the tray has two seed leaves and a thread-like root.","sceneCN":"这里 seedling 指「幼苗」（第 1 个义项：由种子长出的幼小植株）；句意为托盘里每一株幼苗都有两片子叶和一根线一样的根。","pos":[{"tag":"n.","zh":"幼苗；实生苗；小苗"}],"collocations":[{"phrase":"seedling stage","zh":"幼苗期"},{"phrase":"tree seedling","zh":"树苗"},{"phrase":"seedling vigor","zh":"幼苗活力"},{"phrase":"transplant seedlings","zh":"移栽幼苗"},{"phrase":"seedling bed","zh":"苗床"},{"phrase":"seedling establishment","zh":"幼苗定植；成苗"}],"forms":[{"label":"原形","form":"seedling"},{"label":"复数","form":"seedlings"},{"label":"相关名词","form":"seed"},{"label":"相关名词（发芽）","form":"germination"},{"label":"相关名词（苗圃）","form":"nursery"},{"label":"相关名词（移植）","form":"transplant"}],"derivatives":[{"word":"seed","pos":"n.","zh":"种子"},{"word":"seeding","pos":"n.","zh":"播种； seeding 操作"},{"word":"seedbed","pos":"n.","zh":"苗床；温床"},{"word":"seedling","pos":"n.","zh":"幼苗"},{"word":"seedless","pos":"adj.","zh":"无籽的"}],"senses":[{"no":"01","title":"A young plant from a seed","titleCN":"由种子长出的幼小植株","definition":"a plant that has recently grown from a seed and has only a few leaves","definitionCN":"刚从种子长出、只有几片叶子的植物","example":"Each seedling was labelled with its parent line.","exampleCN":"每株幼苗都标着亲本编号。","why":"seed plus the diminutive -ling makes 'a little seed-thing', which is exactly what the noun names.","whyCN":"seed 加指小后缀 -ling 构成「小小的种子之物」，正是这个名词所指。"},{"no":"02","title":"The seedling stage of growth","titleCN":"幼苗期","definition":"the growth stage between sprouting and the appearance of mature leaves","definitionCN":"从发芽到长出成熟叶之间的生长阶段","example":"The plants are most vulnerable at the seedling stage.","exampleCN":"这些植物在幼苗期最为脆弱。","why":"the noun can name a stage because young plants are defined by being at that age.","whyCN":"名词可以命名一个阶段，因为幼小植株正是以「处于这个年龄」来定义的。"},{"no":"03","title":"A plant ready to be transplanted","titleCN":"可以移栽的苗","definition":"a young plant raised in a tray or bed and then moved to the field","definitionCN":"在托盘或苗床育成、随后移入田间的幼株","example":"The seedlings were hardened off before transplanting.","exampleCN":"幼苗在移栽前经过了炼苗。","why":"nursery practice turns the age word into a handling category, meaning the plant is old enough to move.","whyCN":"苗圃实践把这个年龄词变成操作类别，意为植株已大到可以搬动。"},{"no":"04","title":"A young tree","titleCN":"树苗","definition":"a tree grown from seed and still small enough to be lifted","definitionCN":"由种子长成、仍小到可以起苗的树","example":"Two thousand tree seedlings went into the hillside.","exampleCN":"两千株树苗被种进山坡。","why":"the same noun works for woody plants because the age, not the habit, is what it measures.","whyCN":"同一个名词适用于木本植物，因为它量的是年龄，而不是生长习性。"},{"no":"05","title":"A measure of early vigour","titleCN":"幼苗活力（作为质量指标）","definition":"the quality of early growth, judged by size, colour and root development","definitionCN":"早期生长的质量，以大小、颜色与根系发育衡量","example":"Seedling vigour predicted how many would survive the winter.","exampleCN":"幼苗活力预示了有多少能越冬存活。","why":"the noun becomes a quality index because the first weeks decide the rest of the season.","whyCN":"名词变成质量指标，因为最初几周决定了整个季节。"},{"no":"06","title":"A plant living in a nursery bed","titleCN":"苗床上的苗","definition":"a plant raised densely in a bed or tray before being spaced out","definitionCN":"在苗床或托盘中密集育成、之后才分开的植株","example":"The seedling bed was covered with fleece for the cold nights.","exampleCN":"苗床在寒夜里盖上了保温布。","why":"the noun attaches to the plant, and the place is named by compounding it with bed.","whyCN":"名词附着于植株，地点则通过与「床」复合来命名。"},{"no":"07","title":"A plant that survives establishment","titleCN":"定植成活的苗","definition":"a young plant that has taken root in its final position","definitionCN":"在最终位置扎根成活的幼株","example":"Seedling establishment failed on the exposed slope.","exampleCN":"在裸露的坡面上幼苗定植失败。","why":"establishment is germination's second test, so the noun marks the plant that has passed both.","whyCN":"定植是萌发之后的第二道考验，名词因此标记通过了这两关的植株。"},{"no":"08","title":"Metaphor: an early-stage venture","titleCN":"比喻：处于初期的事业或项目","definition":"figurative, an organisation or project in its first fragile period","definitionCN":"比喻用法，处于最初脆弱阶段的机构或项目","example":"The grant was meant for seedlings, not for established firms.","exampleCN":"这笔资助是给初创者的，而不是给成熟企业的。","why":"the metaphor keeps fragility and small size, and drops the soil.","whyCN":"比喻保留脆弱与幼小，舍去土壤。"}],"etymology":{"intro":{"en":"Seedling is an English compound of seed, from Old English sæd, and the diminutive suffix -ling 'one belonging to or young'. It has no Latin ancestor of its own. Dates are approximate.","cn":"seedling 是英语复合词，由古英语 sæd「种子」与指小后缀 -ling「属于……的、年幼的」构成，本身没有拉丁语来源。年代均为约数。"},"items":[{"era":"OLD ENGLISH SÆD","en":"Sæd meant 'seed' and descends from Proto-Germanic *sediz; the verb sow and the noun seed split early in English.","cn":"sæd 意为「种子」，源自原始日耳曼语 *sediz；动词 sow 与名词 seed 在英语中很早就分开了。"},{"era":"SUFFIX -LING","en":"The suffix -ling marks a person or animal belonging to a class, or a young one, as in duckling and yearling.","cn":"后缀 -ling 标记属于某类的幼小者，如 duckling 与 yearling。"},{"era":"COMPOUND","en":"Seedling therefore reads as 'a young thing of the seed kind', i.e. a plant raised from seed rather than from a cutting.","cn":"因此 seedling 读作「种子一类的幼小者」，即由种子而非插条育成的植株。"},{"era":"NURSERY USE","en":"The word became standard in forestry and horticulture once nurseries separated seed-raised from cutting-raised stock.","cn":"当苗圃把实生苗与扦插苗分开之后，这个词在林业与园艺中成为标准用语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest recorded use of seedling is not firmly dated here; the -ling suffix has been productive since Old English.","cn":"来源不确定（首见年代）：seedling 最早的书证年代在此未能确证；-ling 后缀自上古英语起一直能产。"}]},"similar":{"note":{"en":"Group one separates the -ling words that look alike; group two separates a seed-raised plant from plants raised other ways or at other stages.","cn":"第一组区分外形相近的 -ling 词；第二组区分实生苗与其他繁殖方式或阶段的植株。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seed","ipa":"/siːd/","tag":"the starting unit","definition":"The reproductive unit itself; a seedling is what it becomes after germination.","definitionCN":"繁殖单位本身；幼苗是它萌发之后变成的样子。"},{"word":"seeding","ipa":"/ˈsiːdɪŋ/","tag":"the act","definition":"The act of sowing, or the young crop as a mass; it names the operation or the whole stand, not one plant.","definitionCN":"播种这一动作，或作为整体的幼苗；命名操作或整片植株，而非单株。"},{"word":"duckling","ipa":"/ˈdʌklɪŋ/","tag":"same suffix, different base","definition":"A young duck, built exactly like seedling from base plus -ling; the pattern is shared but the meaning is not.","definitionCN":"小鸭，构词方式与 seedling 完全相同；模式相同而词义无关。"},{"word":"yearling","ipa":"/ˈjɪəlɪŋ/","tag":"age word, not plant","definition":"An animal one year old, formed with -ling; it shows the suffix measures age, which is why seedling works for stage two.","definitionCN":"一岁的动物，由 -ling 构成；说明这个后缀量的是年龄，这也是 seedling 能指幼苗阶段的原因。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sapling","ipa":"/ˈsæplɪŋ/","tag":"a young tree only","definition":"A young tree, especially one with a slender trunk; it is narrower than seedling, which can be any young plant.","definitionCN":"幼树，尤指树干细长者；比 seedling 窄，后者可指任何幼小植株。"},{"word":"sprout","ipa":"/spraʊt/","tag":"a shoot, often edible","definition":"A shoot growing from a seed or root, often eaten as a vegetable; a seedling is the whole young plant.","definitionCN":"从种子或根长出的新芽，常作蔬菜食用；幼苗则是整株幼小植物。"},{"word":"cutting","ipa":"/ˈkʌtɪŋ/","tag":"raised without a seed","definition":"A piece of stem or leaf rooted to make a new plant; a seedling by definition comes from a seed.","definitionCN":"一段茎或叶生根形成新株；幼苗按定义来自种子。"},{"word":"transplant","ipa":"/trænsˈplɑːnt/","tag":"the operation","definition":"The act of moving a young plant to its final place; the plant before the move is the seedling.","definitionCN":"把幼株移到最终位置的动作；移动之前的植株就是幼苗。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real compound, the real nursery phrases and the real relatives.","cn":"正常联想：真实的复合构词、真实的苗圃搭配与真实同族词。"},"normal":[{"en":"seed + -ling: a little seed-thing, now a plant.","cn":"seed + -ling：小小的种子之物，如今成了一株植物。"},{"en":"The same suffix gives duckling and yearling, all young things.","cn":"同一后缀构成 duckling 与 yearling，都是幼小者。"},{"en":"Fixed phrases: seedling stage, seedling vigour, transplant seedlings.","cn":"固定搭配：幼苗期、幼苗活力、移栽幼苗。"},{"en":"The tray is the first home; the field is the second.","cn":"育苗盘是第一个家，田间是第二个。"},{"en":"The family runs seed, seedbed, seeding, seedling, seedless.","cn":"同族词包括 seed、seedbed、seeding、seedling、seedless。"}],"abstract":[{"en":"Picture a fragile green thing the size of a finger, standing in a vast bare field.","cn":"想象一株手指大小的脆弱绿苗，站在空旷的大田里。"},{"en":"Picture a new firm with three people and one borrowed desk.","cn":"想象一家新公司，三个人，一张借来的桌子。"},{"en":"Picture a small idea that has roots but no height yet.","cn":"想象一个小想法，已生根，却还没有高度。"}]},"examples":[{"en":"The seedlings were ready to go out after three weeks.","cn":"三周后这些幼苗可以出圃了。"},{"en":"Seedling vigour depends on the quality of the seed lot.","cn":"幼苗活力取决于种子批次的质量。"},{"en":"Deer browsed every seedling on the lower slope.","cn":"鹿把低坡上的幼苗全都啃了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「seed（种子）+ ling（小的）」——种子变成的小东西 → 幼苗","word":"seedling"},"root":"古英语 sæd「种子」（原始日耳曼语 *sediz）+ 指小后缀 -ling；英语本族复合词，无拉丁语来源。","sensesIntro":{"en":"Eight senses of seedling follow one small plant from the tray to the field, from a stage to a measure of vigour, and finally to any young enterprise.","cn":"seedling 的八个义项跟着一株小苗从托盘走到田间，从阶段变成活力指标，最后延伸到任何初创的事物。"},"semanticMap":{"core":{"en":"CORE IMAGE: a finger-sized green thing standing in a tray of soil.","cn":"核心意象：一株手指大小的绿色小苗立在土盘里。"},"chain":["SEED-BORN","TWO SEED LEAVES","STAGE","READY TO MOVE","VIGOUR","YOUNG VENTURE"],"branches":[{"senses":"01 · 02","en":"THE PLANT AND ITS AGE: one noun covers the individual and the stage it is in.","cn":"植株与年龄：一个名词同时覆盖个体与它所处的阶段。"},{"senses":"03 · 06 · 07","en":"NURSERY LIFE: raised in a bed, moved out, and finally rooted in place.","cn":"苗圃生涯：在苗床育成、移出、最终在原地扎根。"},{"senses":"04","en":"WOODY CASE: the same word serves a young tree.","cn":"木本情形：同一个词也用于幼树。"},{"senses":"05","en":"MEASURED QUALITY: early growth becomes a number for growers.","cn":"可量的质量：早期生长成为种植者的指标。"},{"senses":"08","en":"METAPHOR: a new venture is small, rooted and fragile.","cn":"比喻：新事业同样幼小、有根而脆弱。"}]},"affixes":{"intro":{"en":"Seedling is a native English compound, so its parts are an old noun and an old suffix rather than Latin morphemes.","cn":"seedling 是英语本族复合词，其成分是古老的名词与古老的后缀，而非拉丁语素。"},"latinIntro":{"en":"No Latin entry applies: seed descends from Old English sæd and -ling is a Germanic diminutive suffix.","cn":"没有适用的拉丁词条：seed 源自上古英语 sæd，-ling 是日耳曼语指小后缀。"},"items":[{"word":"seed","structure":"Old English sæd (n.)","meaning":"the reproductive unit of a plant","meaningCN":"植物的繁殖单位","example":"The seed carries its own food store.","exampleCN":"种子自带养分储备。"},{"word":"-ling","structure":"-ling (Germanic diminutive suffix)","meaning":"a young or lesser one of a kind","meaningCN":"同类中幼小或次要者","example":"A seedling is a young plant of the seed kind.","exampleCN":"幼苗就是种子一类中幼小的一株。"},{"word":"seedling","structure":"seed + -ling","meaning":"a young plant raised from seed","meaningCN":"由种子育成的幼株","example":"Each seedling had two seed leaves.","exampleCN":"每株幼苗都有两片子叶。"},{"word":"seedbed","structure":"seed + bed","meaning":"a bed where seeds are sown","meaningCN":"播种的苗床","example":"The seedbed was kept under glass.","exampleCN":"苗床被置于玻璃罩下。"},{"word":"seeding","structure":"seed + -ing","meaning":"the act of sowing, or a sown stand","meaningCN":"播种；播下的植株","example":"Early seeding avoided the summer heat.","exampleCN":"早播避开了夏季高温。"},{"word":"seedless","structure":"seed + -less","meaning":"having no seeds","meaningCN":"无籽的","example":"Seedless grapes are grown from cuttings.","exampleCN":"无籽葡萄由插条繁殖。"},{"word":"sapling","structure":"sap + -ling","meaning":"a young tree","meaningCN":"幼树","example":"The sapling bent but did not break.","exampleCN":"幼树弯了，却没有折断。"},{"word":"transplant","structure":"trans- + plant","meaning":"to move a plant to another place","meaningCN":"移栽","example":"They transplant the seedlings in May.","exampleCN":"他们在五月移栽幼苗。"}],"latinEntries":[]}},{"word":"seed","ipa_uk":"/siːd/","ipa_us":"/siːd/","definition_zh":"种子；籽；起源；播种；挑选为种子选手","definition_en":"the small unit produced by a plant from which a new plant can grow, or the source from which something develops","core_image":"一枚扁平的果核躺在掌心，里面封着一株未来的树","scene":"果园里，工人把一枚枚扁平的果核埋进育苗盘，覆上一层薄土。 A single seed can carry the whole plan of a tree inside its coat.","sceneCN":"这里 seed 指「种子」（第 1 个义项：植物用以繁殖的单元）；句意为一粒种子就能在种皮里装着整棵树的设计。","pos":[{"tag":"n.","zh":"种子；籽；起源；种子选手"},{"tag":"vt.","zh":"播种；播撒（云）；挑选为种子选手；给……提供初始数据"}],"collocations":[{"phrase":"seed dispersal","zh":"种子传播"},{"phrase":"seed bank","zh":"种子库"},{"phrase":"sow seeds","zh":"播种"},{"phrase":"seed of doubt","zh":"怀疑的萌芽"},{"phrase":"top seed","zh":"头号种子选手"},{"phrase":"cloud seeding","zh":"人工播云"},{"phrase":"seed capital","zh":"种子资金"}],"forms":[{"label":"原形","form":"seed"},{"label":"复数","form":"seeds"},{"label":"三单（he/she/it）","form":"seeds"},{"label":"过去式","form":"seeded"},{"label":"过去分词","form":"seeded"},{"label":"现在分词","form":"seeding"}],"derivatives":[{"word":"seeding","pos":"n.","zh":"播种； seeding 操作"},{"word":"seedling","pos":"n.","zh":"幼苗"},{"word":"seedbed","pos":"n.","zh":"苗床；温床"},{"word":"seedless","pos":"adj.","zh":"无籽的"},{"word":"seedy","pos":"adj.","zh":"多籽的；破旧的；不体面的"}],"senses":[{"no":"01","title":"The reproductive unit of a plant","titleCN":"植物的繁殖单元","definition":"the small fertilised unit produced by a plant that can grow into a new plant","definitionCN":"植物产生的、能长成新植株的细小受精单元","example":"A single seed can carry the whole plan of a tree.","exampleCN":"一粒种子能装下整棵树的设计。","why":"the core is a package: a young plant plus food plus a coat, small enough to travel.","whyCN":"核心是一个包裹：幼株、养料与种皮，小到可以远行。"},{"no":"02","title":"Material kept for sowing","titleCN":"留作播种的种子","definition":"grain or kernels set aside and traded for planting rather than eating","definitionCN":"留作播种而非食用、并作为商品交易的籽粒","example":"The seed arrives in sealed bags with a germination rating.","exampleCN":"种子装在密封袋里，标有发芽率。","why":"agriculture turns the unit into a commodity, so the noun means a batch rather than a single seed.","whyCN":"农业把这个单元变成商品，因此名词指一整批，而非单粒。"},{"no":"03","title":"Grain of a cereal crop","titleCN":"谷粒","definition":"the part of wheat, rice or maize that is harvested and milled","definitionCN":"小麦、稻或玉米中被收获并磨制的部分","example":"The seed is ground between stones before it becomes flour.","exampleCN":"谷粒在石间磨碎，之后才成为面粉。","why":"a grain is the plant's seed used as food, so the same noun covers both botany and milling.","whyCN":"谷粒就是被当作食物的植物种子，因此同一个名词覆盖植物学与制粉两头。"},{"no":"04","title":"The origin of a feeling or idea","titleCN":"情感或观念的起源、萌芽","definition":"the small beginning from which something larger develops","definitionCN":"某件更大的事由之发展起来的微小开端","example":"One careless remark planted a seed of doubt.","exampleCN":"一句不慎的话埋下了怀疑的种子。","why":"the metaphor keeps the disproportion: a small enclosed thing later becomes large and visible.","whyCN":"比喻保留了那种不成比例：小而封闭的东西后来变得巨大可见。"},{"no":"05","title":"A ranked player in a tournament","titleCN":"种子选手（赛事排位）","definition":"a competitor placed in a protected position in a tournament draw","definitionCN":"在赛事抽签中被安排在受保护位置的参赛者","example":"The top seed lost in the second round.","exampleCN":"头号种子在第二轮就输了。","why":"ranking is called seeding because strong players are distributed like seed across the draw, so they do not meet early.","whyCN":"排位被称为 seeding，因为强手像种子一样被撒在签表各处，以免过早相遇。"},{"no":"06","title":"An initial value for a process","titleCN":"初始值；随机数种子","definition":"a starting value fed to an algorithm or database so that later results can be reproduced","definitionCN":"输入算法或数据库的起始值，使之后的结果可以复现","example":"The model is reproducible if you fix the random seed.","exampleCN":"只要固定随机种子，这个模型的结果就可复现。","why":"computing borrows the agricultural image: one value is planted and a whole sequence grows from it.","whyCN":"计算借用了农业意象：栽下一个值，整串结果便从中长出。"},{"no":"07","title":"Offspring or descendants, archaic","titleCN":"后裔；子嗣（古语与宗教语）","definition":"archaic or biblical, descendants or offspring considered as a line","definitionCN":"古语或宗教语，指作为血脉延续的后代","example":"The promise was made to his seed forever.","exampleCN":"那个许诺是对他的后裔永远立下的。","why":"a line of descent was imagined as a plant continuing through its seeds, so the noun came to mean offspring.","whyCN":"血脉延续被想象成一株植物通过种子延续，名词因此转指后代。"},{"no":"08","title":"To scatter particles into a cloud","titleCN":"向云中播撒（人工降雨）","definition":"to release small particles into a cloud so that rain or snow may form","definitionCN":"把微粒释放进云中，促使雨或雪形成","example":"Pilots seed the clouds with silver iodide.","exampleCN":"飞行员用碘化银播云。","why":"the verb keeps the scattering gesture of sowing, applied to a sky instead of a field.","whyCN":"这个动词保留了播种的撒播动作，只是把田换成了天空。"}],"etymology":{"intro":{"en":"Seed is a native English word from Old English sæd, from Proto-Germanic *sediz, with relatives in Dutch zaad and German Saat. It has no Latin ancestor, so no Latin entry is listed. Dates are approximate.","cn":"seed 是英语本族词，来自古英语 sæd，源自原始日耳曼语 *sediz，与荷兰语 zaad、德语 Saat 同源。它没有拉丁语来源，因此不列拉丁词条。年代均为约数。"},"items":[{"era":"OLD ENGLISH SÆD","en":"Sæd meant both 'seed' and 'sowing', and it already covered the grain of a plant and the idea of offspring.","cn":"sæd 既指「种子」也指「播种」，并且已经覆盖谷粒与后代两义。"},{"era":"GERMANIC RELATIVES","en":"Dutch zaad and German Saat continue the same Proto-Germanic noun, which shows the word is old and widely shared.","cn":"荷兰语 zaad 与德语 Saat 延续同一个原始日耳曼名词，说明这个词古老且分布广泛。"},{"era":"RECONSTRUCTED ROOT","en":"The Indo-European root is usually reconstructed as *se-, 'to sow'; this root is a reconstruction, not a recorded form.","cn":"其印欧词根通常重构为 *se-「播种」；这是重构形式，并非有记录的形式。"},{"era":"VERB SEED","en":"The verb seed is formed from the noun in English and later acquired technical senses: tournament seeding and computer seeding.","cn":"动词 seed 在英语中由名词构成，后来又获得技术义：赛事排位与计算机播种值。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first technical dates): the sporting and computing uses are nineteenth- and twentieth-century extensions whose first citations are not fixed here.","cn":"来源不确定（技术义首见年代）：体育与计算用法是 19、20 世纪的延伸，其最早书证在此未确证。"}]},"similar":{"note":{"en":"Group one separates the seed family by part of speech; group two separates the reproductive unit from look-alike plant parts and related concepts.","cn":"第一组按词类区分 seed 词族；第二组区分繁殖单元与形似的植物结构及相关概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seeding","ipa":"/ˈsiːdɪŋ/","tag":"the act or the stand","definition":"The act of sowing, or the whole crop as sown; it describes an operation or a mass, not one unit.","definitionCN":"播种这一动作，或播下的整片植株；描述操作或整体，而非单个单元。"},{"word":"seedling","ipa":"/ˈsiːdlɪŋ/","tag":"the young plant","definition":"What a seed becomes after germination; the -ling marks a young thing, not the starting unit.","definitionCN":"种子萌发之后长成的东西；-ling 标记幼小者，而非起始单元。"},{"word":"seedbed","ipa":"/ˈsiːdbed/","tag":"the place","definition":"A prepared bed for sowing, formed by compounding; it names where the seed goes, not what it is.","definitionCN":"为播种整理好的苗床，由复合构词形成；命名种子所去之处，而非种子本身。"},{"word":"cede","ipa":"/siːd/","tag":"different word, same sound","definition":"From Latin cedere 'to yield'; it sounds identical to seed but means to give up territory or rights.","definitionCN":"来自拉丁 cedere「让出」；与 seed 读音相同，意为让出领土或权利。"}]},{"heading":"NEAR MEANING","entries":[{"word":"grain","ipa":"/ɡreɪn/","tag":"harvested cereal","definition":"The harvested kernel of a cereal, especially as food or a crop; it is the seed seen from the harvest side.","definitionCN":"收获后的谷物籽粒，尤指作为食物或作物；它是从收获角度看的种子。"},{"word":"spore","ipa":"/spɔː/","tag":"single-celled unit","definition":"A reproductive cell of fungi, ferns or mosses, usually one cell and without a stored food supply.","definitionCN":"真菌、蕨或苔藓的繁殖细胞，通常为单细胞且不储养分。"},{"word":"pit","ipa":"/pɪt/","tag":"the stone of a fruit","definition":"The hard stone inside a fleshy fruit; it contains a seed but is not the seed itself.","definitionCN":"肉质果内的硬核；它包着种子，但不是种子本身。"},{"word":"origin","ipa":"/ˈɒrɪdʒɪn/","tag":"abstract start","definition":"The beginning or source of something; seed as a metaphor adds the image of a small living start.","definitionCN":"某物的开端或来源；作为比喻的 seed 增添了「活的微小起点」这一意象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Germanic root, the real phrases and the real family.","cn":"正常联想：真实的日耳曼词根、真实搭配与真实词族。"},"normal":[{"en":"One package holds three things: embryo, food, coat.","cn":"一个包裹装三样：胚、养料、种皮。"},{"en":"Fixed phrases: seed dispersal, seed bank, seed capital, top seed.","cn":"固定搭配：种子传播、种子库、种子资金、头号种子。"},{"en":"The metaphor works because the small start is disproportionate to the result.","cn":"比喻成立，因为微小的开端与结果极不相称。"},{"en":"The family runs seeding, seedling, seedbed, seedless, seedy.","cn":"同族词包括 seeding、seedling、seedbed、seedless、seedy。"},{"en":"The verb extends to skies: cloud seeding.","cn":"动词延伸到天空：人工播云。"}],"abstract":[{"en":"Picture a pocket-sized parcel that contains a whole tree folded flat.","cn":"想象一个口袋大小的包裹，里面平折着一整棵树。"},{"en":"Picture a single remark left in a room, growing quietly for years.","cn":"想象一句留在房间里的话，安静地长了多年。"},{"en":"Picture a number dropped into a machine, from which an endless sequence unfolds.","cn":"想象一个数被投进机器，无穷的序列由此展开。"}]},"examples":[{"en":"The seed needs moisture and warmth before it can sprout.","cn":"种子需要水分与温度才能发芽。"},{"en":"Farmers store seed in cool, dry rooms.","cn":"农民把种子存放在阴凉干燥的房间里。"},{"en":"A single seed of doubt was enough to derail the plan.","cn":"一粒怀疑的种子就足以毁掉这项计划。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「seed（种子）」——一切从这一小粒开始 → 种子、起源","word":"seed"},"root":"古英语 sæd「种子、播种」，源自原始日耳曼语 *sediz；无拉丁语来源。印欧词根常重构为 *se-「播种」，属重构形式。","sensesIntro":{"en":"Eight senses of seed all begin with one small package that carries a future: a plant, a crop, an idea, a ranking, a computation or a descendant line.","cn":"seed 的八个义项都始于一个装着未来的小包裹：一株植物、一季作物、一个想法、一个排位、一段计算或一条血脉。"},"semanticMap":{"core":{"en":"CORE IMAGE: a flat pip in a palm, holding an entire tree in compressed form.","cn":"核心意象：掌心一枚扁平的籽，压缩着一整棵树。"},"chain":["SEED AS PACKAGE","SOWING STOCK","GRAIN AS FOOD","SMALL ORIGIN","START VALUE","DESCENDANTS"],"branches":[{"senses":"01 · 02 · 03","en":"THE AGRICULTURAL LINE: unit, commodity and food grain are the same object at three stages.","cn":"农业线：单元、商品与食用谷粒是同一物件在三个阶段。"},{"senses":"04","en":"THE METAPHOR: a tiny enclosed start grows out of proportion.","cn":"比喻：封闭的微小起点长成不相称的结果。"},{"senses":"05 · 06","en":"THE TECHNICAL LINE: ranking and computation both plant a value and let order grow.","cn":"技术线：排位与计算都栽下一个值，让顺序从中长出。"},{"senses":"07","en":"THE LINEAGE LINE: descent imagined as a plant continuing through seed.","cn":"血脉线：把世系想象成一株植物通过种子延续。"},{"senses":"08","en":"THE SKY LINE: sowing becomes scattering particles into a cloud.","cn":"天空线：播种变成向云中撒播微粒。"}]},"affixes":{"intro":{"en":"Seed is a native Germanic word, so its morphology is English and Germanic rather than Latin.","cn":"seed 是日耳曼本族词，其构词属英语与日耳曼系统，而非拉丁系统。"},"latinIntro":{"en":"No Latin entry applies: the word descends from Old English sæd through Proto-Germanic *sediz.","cn":"没有适用的拉丁词条：这个词经原始日耳曼语 *sediz 来自古英语 sæd。"},"items":[{"word":"seed","structure":"Old English sæd (n.)","meaning":"the reproductive unit; sowing","meaningCN":"繁殖单元；播种","example":"The seed holds an embryo and a food store.","exampleCN":"种子包含胚与养分储备。"},{"word":"-s","structure":"-s (English plural and third-person ending)","meaning":"plural or present tense","meaningCN":"复数或现在时","example":"Seeds travel by wind and by animals.","exampleCN":"种子靠风与动物传播。"},{"word":"-ed","structure":"-ed (English past-tense suffix)","meaning":"past action","meaningCN":"过去动作","example":"They seeded the meadow last autumn.","exampleCN":"他们去年秋天给草地播了种。"},{"word":"-ing","structure":"-ing (English participle suffix)","meaning":"ongoing action or verbal noun","meaningCN":"进行动作或动名词","example":"Seeding begins after the last frost.","exampleCN":"最后一场霜过后开始播种。"},{"word":"seedling","structure":"seed + -ling","meaning":"a young plant from seed","meaningCN":"幼苗","example":"The seedling has two seed leaves.","exampleCN":"幼苗有两片子叶。"},{"word":"seedbed","structure":"seed + bed","meaning":"a bed prepared for sowing","meaningCN":"苗床","example":"The seedbed was raked smooth.","exampleCN":"苗床被耙平。"},{"word":"seedless","structure":"seed + -less","meaning":"without seeds","meaningCN":"无籽的","example":"Seedless fruit is grown from cuttings.","exampleCN":"无籽果实由插条繁殖。"},{"word":"seedy","structure":"seed + -y","meaning":"full of seeds; shabby","meaningCN":"多籽的；破旧的","example":"The old hotel had a seedy carpet.","exampleCN":"那家老旅馆的地毯很破旧。"},{"word":"seeding","structure":"seed + -ing","meaning":"sowing, or a sown crop","meaningCN":"播种；播下的植株","example":"Early seeding avoids the dry spell.","exampleCN":"早播可避开干旱期。"}],"latinEntries":[]}},{"word":"spore","ipa_uk":"/spɔː/","ipa_us":"/spɔːr/","definition_zh":"孢子；（细菌的）芽孢","definition_en":"a single reproductive cell of fungi, ferns, mosses or bacteria that can grow into a new individual","core_image":"蕨叶背面的褐色小点裂开，细到看不见的粉末被风带走","scene":"蕨叶背面排列着一圈褐色的小点，手指一碰便有细粉落下。 Each spore is a single cell that can grow into a new plant without any partner.","sceneCN":"这里 spore 指「孢子」（第 1 个义项：能单独长成新个体的繁殖细胞）；句意为每个孢子都是一个单细胞，无需任何伙伴就能长成新植株。","pos":[{"tag":"n.","zh":"孢子；芽孢；孢粉"},{"tag":"vi.","zh":"形成孢子（较少用）"}],"collocations":[{"phrase":"fungal spore","zh":"真菌孢子"},{"phrase":"bacterial spore","zh":"细菌芽孢"},{"phrase":"spore-forming","zh":"产孢的；形成芽孢的"},{"phrase":"spore print","zh":"孢子印"},{"phrase":"spore dispersal","zh":"孢子传播"},{"phrase":"dormant spore","zh":"休眠孢子"}],"forms":[{"label":"原形","form":"spore"},{"label":"复数","form":"spores"},{"label":"形容词","form":"sporal"},{"label":"相关名词（产孢）","form":"sporulation"},{"label":"指小形式（孢子）","form":"sporule"},{"label":"相关结构（孢子囊）","form":"sporangium"}],"derivatives":[{"word":"sporulation","pos":"n.","zh":"孢子形成；产孢"},{"word":"sporulate","pos":"v.","zh":"形成孢子"},{"word":"sporangium","pos":"n.","zh":"孢子囊"},{"word":"sporophyte","pos":"n.","zh":"孢子体"},{"word":"sporule","pos":"n.","zh":"小孢子"}],"senses":[{"no":"01","title":"A reproductive cell of fungi or ferns","titleCN":"真菌或蕨类的繁殖细胞","definition":"a single cell that can develop into a new individual without fusing with another cell","definitionCN":"无需与另一个细胞融合就能发育成新个体的单细胞","example":"Each spore can grow into a new plant on its own.","exampleCN":"每个孢子都能独自长成一株新植物。","why":"the word names a unit of reproduction that needs no partner, which is what separates it from a seed.","whyCN":"这个词命名一种无需伙伴的繁殖单元，这正是它与种子的分界。"},{"no":"02","title":"A bacterial endospore","titleCN":"细菌芽孢","definition":"a tough resting body formed inside a bacterium to survive hard conditions","definitionCN":"细菌内部形成的坚韧休眠体，用以度过恶劣条件","example":"The spore survives boiling and returns to growth later.","exampleCN":"芽孢能挺过煮沸，之后重新生长。","why":"the same noun covers the bacterial case because both are resistant single-cell stages.","whyCN":"同一个名词覆盖细菌情形，因为二者都是抗逆的单细胞阶段。"},{"no":"03","title":"The dust on a fern's frond","titleCN":"蕨叶背面的孢子","definition":"the small brown bodies clustered under a fern leaf","definitionCN":"聚在蕨叶背面小片上的褐色颗粒","example":"The brown spots under the frond are clusters of spores.","exampleCN":"叶背的褐色斑点是成簇的孢子。","why":"visible fern spores are the everyday sight that fixed the word's popular meaning.","whyCN":"可见的蕨孢子正是固定这个词通俗含义的日常景象。"},{"no":"04","title":"A mushroom's spore print","titleCN":"蘑菇的孢子印","definition":"the pattern left when a mushroom cap drops its spores onto paper","definitionCN":"蘑菇菌盖把孢子落在纸上留下的图案","example":"The spore print was white, which narrowed the identification.","exampleCN":"孢子印是白色的，这缩小了鉴定范围。","why":"the print makes invisible spores visible, so the noun names a diagnostic tool as well.","whyCN":"孢子印让看不见的孢子变得可见，因此名词也命名一种鉴定工具。"},{"no":"05","title":"Of bacteria that form spores","titleCN":"形成芽孢的（细菌）","definition":"used of species that can build a resistant spore inside the cell","definitionCN":"用于能在细胞内形成抗逆芽孢的物种","example":"Spore-forming bacteria survived the cleaning cycle.","exampleCN":"产孢细菌挺过了清洗循环。","why":"the compound adjective uses spore as a classifying feature, not as an object.","whyCN":"复合形容词把孢子作为分类特征，而非作为对象。"},{"no":"06","title":"A unit that travels through air","titleCN":"随气流传播的繁殖单元","definition":"a reproductive body adapted to be carried by wind or animals","definitionCN":"适应由风或动物携带的繁殖体","example":"Spore dispersal lets a fungus reach a new log before the old one decays.","exampleCN":"孢子传播让真菌在老木腐坏之前抵达新木。","why":"size and weight make spores travellers, so the noun also names a dispersal stage.","whyCN":"大小与重量使孢子成为旅者，因此名词也命名一个传播阶段。"},{"no":"07","title":"A moss spore from a capsule","titleCN":"苔藓蒴果中的孢子","definition":"a cell released from the capsule of a moss or liverwort","definitionCN":"从苔藓或地钱蒴果中释放的细胞","example":"Moss spores need a damp surface before they will grow.","exampleCN":"苔藓孢子需要湿润表面才会生长。","why":"mosses repeat the fern pattern with a capsule, so the general noun covers both groups.","whyCN":"苔藓用蒴果重复蕨类的模式，因此通名覆盖两类。"},{"no":"08","title":"A dormant stage that waits","titleCN":"休眠等待的孢子","definition":"a spore in a paused state that resumes growth when conditions improve","definitionCN":"处于暂停状态、条件改善后恢复生长的孢子","example":"The dormant spore waited in the soil for years.","exampleCN":"休眠孢子在土壤里等了多年。","why":"waiting is the whole point of the bacterial spore, and the noun is used for that pause as well.","whyCN":"等待正是细菌芽孢存在的全部意义，名词也因此用于这段暂停。"}],"etymology":{"intro":{"en":"Spore comes from Greek spora 'a sowing, seed, offspring', related to speirein 'to sow, scatter'. It entered scientific English in the nineteenth century through Modern Latin spora. The deeper origin is reconstructed.","cn":"spore 来自希腊 spora「播种、种子、后代」，与 speirein「播撒」相关；19 世纪经近代拉丁 spora 进入科学英语。更早来源属重构。"},"items":[{"era":"GREEK SPORA","en":"Spora meant 'a sowing' and by extension 'seed, offspring'; the image is scattering rather than enclosing.","cn":"spora 意为「播种」，引申为「种子、后代」；意象是撒播，而非包裹。"},{"era":"GREEK SPEIREIN","en":"Speirein 'to sow, scatter' is the verb behind spora; the two words are generally treated as related within Greek.","cn":"speirein「播种、撒播」是 spora 背后的动词；在希腊语内部二者一般被视为相关。"},{"era":"RECONSTRUCTED ROOT","en":"An Indo-European root meaning 'to strew' is reconstructed for this family; it is a reconstruction, not a recorded form.","cn":"这一词族常被重构出一个意为「撒布」的印欧词根；这是重构形式，并非有记录的形式。"},{"era":"MODERN LATIN","en":"Modern Latin adopted spora for the reproductive bodies of cryptogams, and English took the word in the nineteenth century.","cn":"近代拉丁采用 spora 指隐花植物的繁殖体，英语在 19 世纪引入这个词。"},{"era":"BACTERIAL EXTENSION","en":"Microbiology later applied spore to the heat-resistant body inside a bacterium, extending the word to a different kingdom.","cn":"微生物学后来把 spore 用于细菌内部的耐热体，使这个词跨到另一个界。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first botanical date): the first English use for fern and fungus bodies is not precisely dated here; the Greek-to-Latin route is clear but the earliest citation is not.","cn":"来源不确定（植物学义首见年代）：英语首次用于蕨与真菌繁殖体的时间在此未能确证；希腊到拉丁的路径清楚，最早书证则不确定。"}]},"similar":{"note":{"en":"Group one separates the spore family by word class; group two separates single-celled reproductive units from seeds and from bacterial resting bodies.","cn":"第一组按词类区分 spore 词族；第二组区分单细胞繁殖单元与种子及细菌休眠体。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sporulation","ipa":"/ˌspɔːrəˈleɪʃən/","tag":"the process","definition":"The forming of spores; the noun names the event, while spore names the product.","definitionCN":"孢子的形成；名词命名事件，而 spore 命名产物。"},{"word":"sporulate","ipa":"/ˈspɔːrjʊleɪt/","tag":"the verb","definition":"To form spores; it is what the organism does before any spore exists.","definitionCN":"形成孢子；这是生物在孢子出现之前所做的事。"},{"word":"sporangium","ipa":"/spəˈrændʒiəm/","tag":"the container","definition":"The structure that produces and holds spores, formed with Greek angeion 'vessel'.","definitionCN":"产生并容纳孢子的结构，由希腊 angeion「容器」构成。"},{"word":"sperm","ipa":"/spɜːm/","tag":"different Greek word","definition":"From Greek sperma 'seed', a different noun from spora, though both belong to the same sowing image.","definitionCN":"来自希腊 sperma「种子」，与 spora 是不同名词，尽管都属同一「播种」意象。"}]},{"heading":"NEAR MEANING","entries":[{"word":"seed","ipa":"/siːd/","tag":"multi-celled package","definition":"A fertilised unit with an embryo, food store and coat; a spore is usually one cell with no stored food.","definitionCN":"含胚、养分与种皮的受精单元；孢子通常是单细胞且不储养分。"},{"word":"endospore","ipa":"/ˈendəspɔː/","tag":"bacterial case","definition":"The specific heat-resistant body inside a bacterium; it is a kind of spore, named with endo- 'within'.","definitionCN":"细菌内部特定的耐热体；它是孢子的一种，由 endo-「在内」命名。"},{"word":"pollen","ipa":"/ˈpɒlən/","tag":"male partner needed","definition":"The male gamete-bearing grain of a flower; unlike a spore, it must reach an egg to produce anything.","definitionCN":"花中携带雄配子的颗粒；与孢子不同，它必须到达卵才能产生新个体。"},{"word":"cyst","ipa":"/sɪst/","tag":"resting stage, different origin","definition":"A resistant resting stage of some protozoa or insects, not a reproductive cell in the spore sense.","definitionCN":"某些原生动物或昆虫的抗逆休眠阶段，并非孢子意义上的繁殖细胞。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek root, the real microbiological phrases and the real relatives.","cn":"正常联想：真实的希腊词根、真实的微生物学搭配与真实同族词。"},"normal":[{"en":"spora 'sowing' + the scientific ending: the scattered unit.","cn":"spora「播种」加科学词尾：被撒播的单元。"},{"en":"One cell, no partner: that is what makes a spore a spore.","cn":"一个细胞，无需伙伴：这正是孢子之为孢子。"},{"en":"Fixed phrases: fungal spore, bacterial spore, spore print, spore dispersal.","cn":"固定搭配：真菌孢子、细菌芽孢、孢子印、孢子传播。"},{"en":"The family runs sporulation, sporulate, sporangium, sporophyte.","cn":"同族词包括 sporulation、sporulate、sporangium、sporophyte。"},{"en":"Ferns show it as brown dots; mushrooms show it as a print.","cn":"蕨类把它显成褐点，蘑菇把它显成印痕。"}],"abstract":[{"en":"Picture dust that needs no partner and can wait for years.","cn":"想象一种不需要伙伴、能等待多年的尘埃。"},{"en":"Picture a sealed capsule opening only when the air turns damp.","cn":"想象一个只在空气转湿时才打开的密封蒴果。"},{"en":"Picture a message so light that the wind carries it without effort.","cn":"想象一则轻得让风毫不费力就能带走的讯息。"}]},"examples":[{"en":"Fungal spores spread through the greenhouse in a single day.","cn":"真菌孢子在一天之内传遍温室。"},{"en":"The spore print helped identify the mushroom.","cn":"孢子印帮助鉴定了这种蘑菇。"},{"en":"Spore-forming bacteria can survive drying for decades.","cn":"产孢细菌能在干燥环境中存活数十年。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「spor（撒播）+ e」——被风吹散的单细胞 → 孢子","word":"spore"},"root":"希腊 spora「播种、种子、后代」← speirein「播撒」；近代拉丁 spora → 英语 spore。其印欧词根常重构为意为「撒布」的形式。","sensesIntro":{"en":"Eight senses of spore all describe one light, self-sufficient cell: it is scattered, waits, and then grows without needing a partner.","cn":"spore 的八个义项都描述同一个轻而自足的细胞：它被撒散、等待，然后在无需伙伴的情况下生长。"},"semanticMap":{"core":{"en":"CORE IMAGE: brown dust falling from a fern frond into the wind.","cn":"核心意象：褐色粉末从蕨叶落进风里。"},"chain":["SINGLE CELL","NO PARTNER","FERN BODY","MUSHROOM PRINT","BACTERIAL BODY","DORMANT WAIT"],"branches":[{"senses":"03 · 07","en":"PLANT AND MOSS CASES: ferns and mosses release the same kind of cell.","cn":"蕨与苔藓：两类植物释放同一种细胞。"},{"senses":"02 · 08","en":"THE BACTERIAL CASE: the spore is a tough body that waits.","cn":"细菌情形：孢子是等待中的坚韧体。"},{"senses":"04 · 05","en":"IDENTIFICATION AND CLASSIFICATION: the print names a species, the trait names a group.","cn":"鉴定与分类：印痕命名物种，特征命名类群。"},{"senses":"06","en":"TRAVEL: lightness is the adaptation that lets it leave.","cn":"旅行：轻是让它得以离开的适应。"},{"senses":"01","en":"THE KEY CONTRAST: no partner is needed, unlike pollen or a sperm.","cn":"关键对照：与花粉或精子不同，它不需要伙伴。"}]},"affixes":{"intro":{"en":"Spore is a Greek noun taken into scientific Latin, so its family is built with Greek and Latin elements rather than Germanic ones.","cn":"spore 是进入科学拉丁语的希腊名词，其词族由希腊与拉丁成分构成，而非日耳曼成分。"},"latinIntro":{"en":"Greek spora 'sowing' passed into Modern Latin as spora; sporula is its diminutive, and sporulatio names the forming of spores.","cn":"希腊 spora「播种」作为 spora 进入近代拉丁语；sporula 是其指小形式，sporulatio 命名孢子的形成。"},"items":[{"word":"spora","structure":"spora (Greek noun, 'a sowing, seed')","meaning":"a sowing; seed","meaningCN":"播种；种子","example":"The root names scattering rather than enclosing.","exampleCN":"这个词根命名撒播，而非包裹。"},{"word":"-e","structure":"English spelling of the Latin -a ending","meaning":"noun ending","meaningCN":"名词词尾","example":"Spore keeps the Latin singular in English.","exampleCN":"spore 在英语中保留了拉丁单数形式。"},{"word":"sporal","structure":"spore + -al","meaning":"relating to spores","meaningCN":"孢子的","example":"Sporal walls resist drying.","exampleCN":"孢子壁能抗干燥。"},{"word":"sporule","structure":"Modern Latin sporula, diminutive of spora","meaning":"a small spore","meaningCN":"小孢子","example":"The sporule germinates on damp bark.","exampleCN":"小孢子在湿树皮上萌发。"},{"word":"sporulate","structure":"spore + -ulate","meaning":"to form spores","meaningCN":"形成孢子","example":"The cells sporulate when food runs out.","exampleCN":"食物耗尽时细胞形成孢子。"},{"word":"sporulation","structure":"sporulate + -ation","meaning":"the forming of spores","meaningCN":"孢子形成","example":"Sporulation began after the nutrient drop.","exampleCN":"养分下降后产孢开始。"},{"word":"sporangium","structure":"sporo- + Greek angeion 'vessel'","meaning":"a spore container","meaningCN":"孢子囊","example":"The sporangium bursts when mature.","exampleCN":"孢子囊成熟时裂开。"},{"word":"sporophyte","structure":"sporo- + Greek phyton 'plant'","meaning":"the spore-producing plant generation","meaningCN":"孢子体","example":"The sporophyte is the visible fern plant.","exampleCN":"孢子体是可见的蕨株。"},{"word":"spore-forming","structure":"spore + forming (compound adjective)","meaning":"able to produce spores","meaningCN":"能形成孢子的","example":"Spore-forming bacteria survive heat.","exampleCN":"产孢细菌能耐受高温。"}],"latinEntries":[{"word":"spora","structure":"spora, sporae (f., first declension, from Greek)","meaning":"a sowing, seed","meaningCN":"播种；种子"},{"word":"sporula","structure":"sporula, sporulae (f., Modern Latin diminutive)","meaning":"a small spore","meaningCN":"小孢子"},{"word":"sporulatio","structure":"sporulatio, sporulationis (f., Modern Latin)","meaning":"the forming of spores","meaningCN":"孢子形成"}]}},{"word":"sporulation","ipa_uk":"/ˌspɔːrəˈleɪʃən/","ipa_us":"/ˌspɔːrəˈleɪʃən/","definition_zh":"产孢；孢子形成","definition_en":"the process by which a cell or an organism forms spores","core_image":"培养瓶里的细胞在养分耗尽后，内部亮起一颗折光的圆体","scene":"培养瓶里的细菌在养分耗尽后，细胞内部出现明亮的折光小体。 Under starvation, sporulation turns each cell into a tough dormant body.","sceneCN":"这里 sporulation 指「产孢」（第 1 个义项：细胞形成孢子的过程）；句意为在饥饿条件下，产孢把每个细胞变成一个坚韧的休眠体。","pos":[{"tag":"n.","zh":"产孢；孢子形成；孢子化"}],"collocations":[{"phrase":"bacterial sporulation","zh":"细菌产孢"},{"phrase":"fungal sporulation","zh":"真菌产孢"},{"phrase":"sporulation cycle","zh":"产孢周期"},{"phrase":"sporulation rate","zh":"产孢速率"},{"phrase":"induced sporulation","zh":"诱导产孢"},{"phrase":"sporulation medium","zh":"产孢培养基"}],"forms":[{"label":"原形","form":"sporulation"},{"label":"复数","form":"sporulations"},{"label":"同根动词","form":"sporulate"},{"label":"同根名词（孢子）","form":"spore"},{"label":"同根形容词","form":"sporulating"},{"label":"相关结构（孢子囊）","form":"sporangium"}],"derivatives":[{"word":"sporulate","pos":"v.","zh":"形成孢子"},{"word":"spore","pos":"n.","zh":"孢子"},{"word":"sporulating","pos":"adj.","zh":"正在产孢的"},{"word":"sporangium","pos":"n.","zh":"孢子囊"},{"word":"sporophyte","pos":"n.","zh":"孢子体"}],"senses":[{"no":"01","title":"The forming of spores in general","titleCN":"孢子形成（总称）","definition":"the process by which any organism produces reproductive spores","definitionCN":"任何生物产生繁殖孢子的过程","example":"Sporulation is the first step in the fungus's spread.","exampleCN":"产孢是真菌扩散的第一步。","why":"the noun names the making rather than the made thing, so it is the process counterpart of spore.","whyCN":"这个名词命名「制造」而非「被造之物」，因此是 spore 的过程对应词。"},{"no":"02","title":"Bacterial endospore formation","titleCN":"细菌芽孢形成","definition":"the change by which a bacterium wraps its DNA in a tough coat","definitionCN":"细菌把自身的遗传物质包进坚韧外壳的变化","example":"Bacterial sporulation begins when nitrogen runs low.","exampleCN":"当氮源不足时，细菌开始形成芽孢。","why":"the bacterial case is a survival programme, so the noun also carries the idea of a triggered response.","whyCN":"细菌情形是一种生存程序，因此名词也带有「被触发反应」的意思。"},{"no":"03","title":"Fungal spore production","titleCN":"真菌产孢","definition":"the production of spores by moulds, mushrooms or yeasts","definitionCN":"霉菌、蘑菇或酵母产生孢子","example":"Fungal sporulation peaked two days after the culture was exposed.","exampleCN":"培养物暴露两天后，真菌产孢达到高峰。","why":"moulds use spores as their main reproductive route, so the process is their normal growth phase.","whyCN":"霉菌以孢子为主要繁殖途径，因此这一过程是它们正常的生长阶段。"},{"no":"04","title":"A repeating sporulation cycle","titleCN":"产孢周期","definition":"the regular alternation between growth and spore formation","definitionCN":"生长与产孢之间的规律交替","example":"The sporulation cycle matches the seasonal drying of the pond.","exampleCN":"产孢周期与池塘季节性干涸相合。","why":"a cycle is a process with a period, so the noun appears in schedules and ecology as well as in cells.","whyCN":"周期是有节律的过程，因此名词既出现在细胞研究，也出现在日程与生态学中。"},{"no":"05","title":"What triggers sporulation","titleCN":"触发产孢的条件","definition":"the depletion of nutrients or another stress that starts the process","definitionCN":"养分耗尽或其他压力，启动这一过程","example":"Phosphate limitation is a common trigger for sporulation.","exampleCN":"磷酸盐限制是常见的产孢触发条件。","why":"the word can name the condition as well as the event because the condition is what the process responds to.","whyCN":"这个词既能命名事件也能命名条件，因为条件正是过程所回应者。"},{"no":"06","title":"Spore formation in ferns and mosses","titleCN":"蕨类与苔藓的产孢","definition":"the release of spores from the sporangia of a fern or moss","definitionCN":"蕨或苔藓从孢子囊中释放孢子","example":"Sporulation in the fern is visible as browning under the fronds.","exampleCN":"蕨的产孢表现为叶背变褐。","why":"the process looks different across groups, but the noun stays the same because the product is the same.","whyCN":"不同类群的过程外观不同，但因为产物相同，名词保持不变。"},{"no":"07","title":"The measured rate of spore output","titleCN":"产孢速率（作为指标）","definition":"the number or proportion of cells that form spores in a given time","definitionCN":"在给定时间内形成孢子的细胞数量或比例","example":"Sporulation rate fell sharply at low humidity.","exampleCN":"湿度低时产孢速率急剧下降。","why":"industry and ecology need a number, so the process noun becomes a measurable rate.","whyCN":"工业与生态学需要一个数，过程名词因此变成可量的比率。"},{"no":"08","title":"Controlled sporulation in industry","titleCN":"工业上的受控产孢","definition":"spore formation managed deliberately to produce starter cultures or biocontrol agents","definitionCN":"为生产发酵剂或生物防治剂而有意管理的孢子形成","example":"The plant induces sporulation in a closed fermenter.","exampleCN":"工厂在密闭发酵罐中诱导产孢。","why":"once the process can be switched on, the noun names a manufacturing step.","whyCN":"一旦这个过程能被开启，名词就命名一道制造工序。"}],"etymology":{"intro":{"en":"Sporulation is Modern Latin sporulatio, built on spora 'sowing, seed' with a diminutive and an action suffix. The Greek base goes back to speirein 'to scatter'.","cn":"sporulation 是近代拉丁 sporulatio，建立在 spora「播种、种子」之上，带指小与动作后缀。希腊词基上溯到 speirein「撒播」。"},"items":[{"era":"GREEK SPORA","en":"Spora 'a sowing' supplied the image of something scattered rather than planted in one place.","cn":"spora「播种」提供了「被撒散、而非栽在一处」的意象。"},{"era":"LATIN SPORULA","en":"The diminutive sporula 'small spore' is Modern Latin, formed to name the individual bodies seen under early microscopes.","cn":"指小形式 sporula「小孢子」是近代拉丁语，为命名早期显微镜下见到的单个小体而造。"},{"era":"MODERN LATIN NOUN","en":"Sporulatio named the forming of these small bodies, following the regular -atio pattern for processes.","cn":"sporulatio 命名这些小体的形成，遵循表示过程的常规 -atio 模式。"},{"era":"MICROBIOLOGY","en":"Nineteenth-century microbiology extended the term from fungi to bacteria when heat-resistant bodies were recognised as spores.","cn":"19 世纪微生物学把耐热体认定为孢子后，把这个词从真菌扩展到细菌。"},{"era":"INDUSTRIAL USE","en":"Twentieth-century fermentation made sporulation a controllable production step, which added rate and trigger senses.","cn":"20 世纪的发酵工业使产孢成为可控的生产步骤，由此增加速率与触发条件两义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first citation): the earliest printed use of sporulation is not firmly dated here; the Modern Latin formation itself is clear, the dating is not.","cn":"来源不确定（首见书证）：sporulation 最早见于印刷的时间在此未能确证；近代拉丁的构词方式清楚，系年则不确定。"}]},"similar":{"note":{"en":"Group one separates the spore family by word class and ending; group two separates the process from the product and from unrelated resting stages.","cn":"第一组按词类与词尾区分 spore 词族；第二组区分过程与产物以及无关的休眠阶段。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"spore","ipa":"/spɔː/","tag":"the product","definition":"The cell that results; sporulation is the making, spore is the made.","definitionCN":"由此产生的细胞；sporulation 是制造，spore 是被造之物。"},{"word":"sporulate","ipa":"/ˈspɔːrjʊleɪt/","tag":"the verb","definition":"To carry out the process; the verb is what the cell does, the noun is what the cell undergoes.","definitionCN":"执行这一过程；动词是细胞所做的，名词是细胞所经历的。"},{"word":"sporangium","ipa":"/spəˈrændʒiəm/","tag":"the vessel","definition":"The structure that holds spores, built with Greek angeion 'vessel'; it is a place, not a process.","definitionCN":"容纳孢子的结构，由希腊 angeion「容器」构成；是场所，而不是过程。"},{"word":"sporulation","ipa":"/ˌspɔːrəˈleɪʃən/","tag":"process noun","definition":"The -ation ending marks a process, which is exactly why the word cannot name a single spore.","definitionCN":"-ation 词尾标记过程，这正是这个词不能命名单个孢子的原因。"}]},{"heading":"NEAR MEANING","entries":[{"word":"germination","ipa":"/ˌdʒɜːmɪˈneɪʃən/","tag":"the opposite direction","definition":"The end of dormancy and the start of growth; sporulation usually creates the dormant state that germination later ends.","definitionCN":"休眠结束、生长开始；产孢通常制造出后来由萌发终结的休眠状态。"},{"word":"fruiting","ipa":"/ˈfruːtɪŋ/","tag":"macroscopic reproduction","definition":"The formation of fruit bodies or fruiting structures in fungi or plants; sporulation may occur inside them.","definitionCN":"真菌或植物形成子实体或结果结构；产孢可在其中发生。"},{"word":"encystment","ipa":"/ɪnˈsɪstmənt/","tag":"resting, not reproducing","definition":"The forming of a protective cyst by a protozoan; it is a survival stage, not a spore-producing process.","definitionCN":"原生动物形成保护性胞囊；属生存阶段，而非产孢过程。"},{"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃən/","tag":"the wider category","definition":"The general production of new individuals; sporulation is one route within it, alongside seeds and division.","definitionCN":"产生新个体的一般过程；产孢是其中一条路径，与种子和分裂并列。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real suffixes, the real microbiological phrases and the real family.","cn":"正常联想：真实的后缀、真实的微生物学搭配与真实词族。"},"normal":[{"en":"sporula 'small spore' + -ation: the making of small spores.","cn":"sporula「小孢子」+ -ation：制造小孢子的过程。"},{"en":"-ation always names a process, so the word cannot mean one spore.","cn":"-ation 总是命名过程，因此这个词不能指单个孢子。"},{"en":"Fixed phrases: bacterial sporulation, sporulation cycle, sporulation rate.","cn":"固定搭配：细菌产孢、产孢周期、产孢速率。"},{"en":"Starvation is the switch: no food, then spores.","cn":"饥饿是开关：没有食物，然后形成孢子。"},{"en":"The family runs spore, sporulate, sporulation, sporangium, sporophyte.","cn":"同族词包括 spore、sporulate、sporulation、sporangium、sporophyte。"}],"abstract":[{"en":"Picture a cell sealing itself into a small, bright, sleeping capsule.","cn":"想象一个细胞把自己封进一只明亮的小睡眠舱。"},{"en":"Picture a factory that only starts when the raw material runs out.","cn":"想象一家只在原料耗尽时才开工的工厂。"},{"en":"Picture a message copied thousands of times so that at least one survives the winter.","cn":"想象一则讯息被复制上千次，好让至少一份熬过冬天。"}]},"examples":[{"en":"Sporulation began when the culture ran out of phosphate.","cn":"培养物耗尽磷酸盐时，产孢开始了。"},{"en":"Fungal sporulation stained the whole jar grey.","cn":"真菌产孢使整个罐子变灰。"},{"en":"The sporulation rate is used as a measure of stress.","cn":"产孢速率被用作衡量胁迫的指标。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「spore（孢子）+ ulation」——孢子的形成过程 → 产孢","word":"sporulation"},"root":"近代拉丁 sporulatio ← sporula（spora「播种、种子」的指小形式）+ -atio（过程后缀）；英语 sporulation。希腊 spora 上溯 speirein「撒播」。","sensesIntro":{"en":"Eight senses of sporulation all name one response: under stress, a cell builds a small resistant copy of itself and lets the old body go.","cn":"sporulation 的八个义项都命名同一种反应：在压力下，细胞造出一个坚韧的小复制体，让旧的身体退场。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cell sealing itself into a bright, sleeping capsule.","cn":"核心意象：细胞把自己封进一只明亮的睡眠舱。"},"chain":["MAKING SPORES","STRESS TRIGGER","BACTERIAL CASE","FUNGAL CASE","CYCLE","RATE"],"branches":[{"senses":"01 · 02","en":"THE RESPONSE: the process is triggered by shortage, not by abundance.","cn":"反应：这一过程由匮乏而非丰足触发。"},{"senses":"03 · 04 · 06","en":"ACROSS KINGDOMS: fungi, ferns and mosses run the same production line.","cn":"跨类群：真菌、蕨与苔藓走同一条生产线。"},{"senses":"05","en":"THE SWITCH: what starts it can be named as well as the event.","cn":"开关：启动它的条件也能与事件一同被命名。"},{"senses":"07","en":"THE NUMBER: a process becomes a rate for comparison.","cn":"数字：过程变成可比对的速率。"},{"senses":"08","en":"THE FACTORY: once switchable, the process becomes a production step.","cn":"工厂：一旦可开关，过程就成为生产工序。"}]},"affixes":{"intro":{"en":"Sporulation is a Modern Latin process noun, so its suffixes mark small size and action in turn.","cn":"sporulation 是近代拉丁的过程名词，其后缀依次标记「小」与「动作」。"},"latinIntro":{"en":"Greek spora 'sowing' gives Latin spora and the Modern Latin diminutive sporula; sporulatio and English sporulation follow the -atio pattern.","cn":"希腊 spora「播种」衍生拉丁 spora 与近代拉丁指小形式 sporula；sporulatio 与英语 sporulation 沿用 -atio 模式。"},"items":[{"word":"spora","structure":"spora (from Greek, 'a sowing, seed')","meaning":"seed, sowing","meaningCN":"种子；播种","example":"The base names what is scattered.","exampleCN":"这个词基命名被撒散之物。"},{"word":"-ula","structure":"-ula (Latin diminutive suffix)","meaning":"small","meaningCN":"小的","example":"Sporula means a small spore.","exampleCN":"sporula 意为小孢子。"},{"word":"-ation","structure":"-atio, -ationis (Latin process suffix)","meaning":"the act or process of","meaningCN":"动作或过程","example":"Sporulation names the process of forming spores.","exampleCN":"sporulation 命名形成孢子的过程。"},{"word":"spore","structure":"spora + English spelling","meaning":"a reproductive cell","meaningCN":"繁殖细胞；孢子","example":"Each spore can grow alone.","exampleCN":"每个孢子都能单独生长。"},{"word":"sporulate","structure":"spore + -ulate","meaning":"to form spores","meaningCN":"形成孢子","example":"The cells sporulate under stress.","exampleCN":"细胞在胁迫下形成孢子。"},{"word":"sporulating","structure":"sporulate + -ing","meaning":"in the act of forming spores","meaningCN":"正在产孢的","example":"Sporulating cells look brighter under the lens.","exampleCN":"正在产孢的细胞在镜下显得更亮。"},{"word":"sporangium","structure":"sporo- + Greek angeion 'vessel'","meaning":"a spore case","meaningCN":"孢子囊","example":"The sporangium releases spores when dry.","exampleCN":"干燥时孢子囊释放孢子。"},{"word":"sporophyte","structure":"sporo- + Greek phyton 'plant'","meaning":"the spore-producing generation","meaningCN":"孢子体","example":"The sporophyte is the leafy fern.","exampleCN":"孢子体是长叶的蕨株。"},{"word":"sporulation medium","structure":"sporulation + medium (compound term)","meaning":"a culture medium that induces spores","meaningCN":"诱导产孢的培养基","example":"The lab switched to a sporulation medium.","exampleCN":"实验室换用了产孢培养基。"}],"latinEntries":[{"word":"spora","structure":"spora, sporae (f., first declension, from Greek)","meaning":"a sowing, seed","meaningCN":"播种；种子"},{"word":"sporula","structure":"sporula, sporulae (f., Modern Latin diminutive)","meaning":"a small spore","meaningCN":"小孢子"},{"word":"sporulatio","structure":"sporulatio, sporulationis (f., Modern Latin)","meaning":"the forming of spores","meaningCN":"孢子形成"}]}},{"word":"plant","ipa_uk":"/plɑːnt/","ipa_us":"/plænt/","definition_zh":"植物；工厂；设备；种植；安放；安插","definition_en":"a living organism that grows in soil or water, or a factory with its machinery, or to place something firmly or secretly","core_image":"一株带根的绿苗被按进土里，旁边是一座有烟囱的厂房","scene":"河边一块湿地被划为保护区，禁止采挖与填土。 The rare plant grows only in the shaded strip beside the stream.","sceneCN":"这里 plant 指「植物」（第 1 个义项：在土或水中生长的活体）；句意为这种稀有植物只长在小溪旁那条背阴的地带。","pos":[{"tag":"n.","zh":"植物；工厂；设备；装置"},{"tag":"vt.","zh":"种植；安放；安插（眼线、证据）；建立"}],"collocations":[{"phrase":"power plant","zh":"发电厂"},{"phrase":"plant species","zh":"植物物种"},{"phrase":"plant a tree","zh":"种树"},{"phrase":"manufacturing plant","zh":"制造厂"},{"phrase":"plant evidence","zh":"放置（栽赃）证据"},{"phrase":"plant oneself","zh":"站稳；一屁股坐下"}],"forms":[{"label":"原形","form":"plant"},{"label":"复数","form":"plants"},{"label":"三单（he/she/it）","form":"plants"},{"label":"过去式","form":"planted"},{"label":"过去分词","form":"planted"},{"label":"现在分词","form":"planting"}],"derivatives":[{"word":"planting","pos":"n.","zh":"种植；栽植"},{"word":"plantation","pos":"n.","zh":"种植园"},{"word":"planter","pos":"n.","zh":"花盆；种植者"},{"word":"implant","pos":"v./n.","zh":"植入 / 植入物"},{"word":"transplant","pos":"v./n.","zh":"移栽；移植 / 移植手术"}],"senses":[{"no":"01","title":"A living organism rooted in soil","titleCN":"扎根土中的活体植物","definition":"a living thing that usually grows in the ground, takes in water and light, and does not move about","definitionCN":"通常长在地上、吸水与光、不会移动的活体","example":"The rare plant grows only in the shaded strip.","exampleCN":"这种稀有植物只长在背阴地带。","why":"the root sense is a rooted shoot: Latin planta named a cutting or sprout set into the ground.","whyCN":"核心义是「扎根的枝条」：拉丁 planta 指插进土里的插条或新芽。"},{"no":"02","title":"To set a seedling in the ground","titleCN":"把苗栽进土里","definition":"to put a young plant or a seed into soil so that it can grow","definitionCN":"把幼株或种子放进土中，使其得以生长","example":"They plant the saplings along the fence in March.","exampleCN":"他们在三月沿围栏栽下树苗。","why":"the verb reverses the noun: what was a rooted thing becomes the act of rooting it.","whyCN":"动词与名词互为反面：原本扎根之物，变成使它扎根的动作。"},{"no":"03","title":"A factory with its machinery","titleCN":"工厂及其设备","definition":"a building or site where goods are made, together with its machines","definitionCN":"制造货物的建筑或场地，连同其机器","example":"The plant runs three shifts through the summer.","exampleCN":"这家工厂整个夏天开三班。","why":"industrial English extended 'the thing set in place' to the whole installed works, machines included.","whyCN":"工业英语把「被安置之物」扩展到整套安装好的设施，包括机器。"},{"no":"04","title":"A set of installed equipment","titleCN":"一整套安装好的设备装置","definition":"the buildings, machines and equipment needed for an industrial process, considered as one installation","definitionCN":"某项工业过程所需的建筑、机器与设备，作为一整套装置","example":"The pumping plant sits at the low end of the canal.","exampleCN":"抽水装置位于渠道的低端。","why":"equipment that has been set in place is literally 'planted', so the noun can name the installation rather than the product.","whyCN":"已安置到位的设备字面上就是「被栽下」的，因此名词可命名整套装置而非产品。"},{"no":"05","title":"To fix the body firmly in place","titleCN":"把身体牢牢站定","definition":"to set one's feet or body firmly so that it cannot be moved","definitionCN":"把脚或身体牢牢放稳，使其无法被推动","example":"He planted his feet and refused to move an inch.","exampleCN":"他站稳双脚，寸步不移。","why":"a body set firmly behaves like a rooted thing, which is the literal image of the Latin noun.","whyCN":"牢牢站定的身体表现得像扎根之物，这正是拉丁名词的字面意象。"},{"no":"06","title":"To place something secretly","titleCN":"秘密安放（安插、栽赃）","definition":"to put an object or a person somewhere without the knowledge of others","definitionCN":"在他人不知情的情况下放置物件或安排人员","example":"Someone had planted a microphone behind the vent.","exampleCN":"有人在通风口后面装了窃听器。","why":"the sense grows from firm placement plus concealment: the thing is set in, but the setting is hidden.","whyCN":"这一义由「牢固放置」加上「隐藏」发展而来：东西被安置进去，安置动作本身却被藏起。"},{"no":"07","title":"To establish a settlement or idea","titleCN":"建立（聚居地、观念）","definition":"to settle people or ideas in a new place so that they take root","definitionCN":"把人员或观念安置到新地方，使其扎根","example":"The order planted missions along the whole coast.","exampleCN":"该修会沿整条海岸建立了传教站。","why":"establishment is imagined as transplanting: people and ideas are cuttings set into new ground.","whyCN":"建立被想象成移栽：人与观念是插进新土的枝条。"},{"no":"08","title":"A person placed inside a group","titleCN":"被安插在群体中的人（卧底、眼线）","definition":"a person secretly placed in an organisation to report on it","definitionCN":"被秘密安置进某组织以进行汇报的人","example":"The clerk was a plant from the rival firm.","exampleCN":"那名职员是对手公司安插的人。","why":"the noun turns the secret placing into the person placed, exactly as a planting becomes a plant.","whyCN":"名词把「秘密安放」这件事转成被安放的人，正如栽下之物变成一株植物。"}],"etymology":{"intro":{"en":"Plant is taken from Latin planta 'sprout, shoot, cutting', which also named the sole of the foot. The connection between the two is a hypothesis, not a proven derivation.","cn":"plant 取自拉丁 planta「芽、枝条、插条」，这个词也指脚掌。两者之间的联系是假说，并非已证实的派生。"},"items":[{"era":"LATIN PLANTA","en":"Planta meant 'sprout, shoot, cutting' and also 'sole of the foot'; which sense came first is debated.","cn":"planta 既指「芽、枝条、插条」，也指「脚掌」；哪个义项在先仍有争论。"},{"era":"UNCERTAIN LINK","en":"Source uncertain: the common explanation that planta 'sprout' comes from planta 'sole', because a cutting is pressed in with the foot, is a hypothesis and is not demonstrated.","cn":"来源不确定：常见解释认为 planta「芽」来自 planta「脚掌」，因为插条是用脚踩进土里的；这一说法是假说，未获证明。"},{"era":"OLD ENGLISH BORROWING","en":"Old English plante 'young tree or shrub' was borrowed from Latin, and the verb planten followed in Middle English.","cn":"古英语 plante「幼树或灌木」借自拉丁语，动词 planten 在中古英语随之出现。"},{"era":"INDUSTRIAL SENSE","en":"The factory sense is eighteenth-century, when a complete set of installed machinery was called a plant; its precise route is uncertain.","cn":"工厂义出现于 18 世纪，当时把一整套安装好的机械称作 plant；其确切来源路径不确定。"},{"era":"SECRET SENSE","en":"The sense 'to place secretly' grew from 'to set firmly in position', as an informant or a device is set into a group.","cn":"「秘密安放」义由「牢牢置于某处」发展而来：眼线或装置被安置进一个群体。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (factory sense): the first use of plant for a factory is variously dated to the late eighteenth century; the dating and the route from French are not settled.","cn":"来源不确定（工厂义）：plant 用于工厂的首见时间被定在 18 世纪晚期，但具体系年与是否经由法语均无定论。"}]},"similar":{"note":{"en":"Group one separates the plant family by word class and prefix; group two separates the living organism from the factory and from the act of placing.","cn":"第一组按词类与前缀区分 plant 词族；第二组区分活体植物、工厂与安放动作。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"plantation","ipa":"/plænˈteɪʃən/","tag":"the place","definition":"A large estate where a crop is planted, often worked by resident labour; it names land, not a single organism.","definitionCN":"大面积种植某种作物的庄园，常由驻留劳工耕作；命名土地，而非单个生物。"},{"word":"planter","ipa":"/ˈplɑːntə/","tag":"the person or pot","definition":"A person who plants, or a container for a plant, formed with -er 'one that does'.","definitionCN":"种植的人，或栽种植物的容器，由 -er「做某事者」构成。"},{"word":"implant","ipa":"/ɪmˈplɑːnt/","tag":"different prefix","definition":"Im- 'in' plus plant: to set something inside tissue or a mind, so the sense shifts from ground to interior.","definitionCN":"im-「在内」加 plant：把某物置入组织或头脑，词义因此从土地转向内部。"},{"word":"planet","ipa":"/ˈplænɪt/","tag":"different root","definition":"From Greek planetes 'wanderer', not from planta; the spelling resembles plant but the words are unrelated.","definitionCN":"来自希腊 planetes「漫游者」，并非 planta；拼写近似，但二者无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"factory","ipa":"/ˈfæktəri/","tag":"industrial building","definition":"A building where goods are manufactured; plant includes the machinery and the whole installed site, so it is broader.","definitionCN":"制造货物的建筑；plant 还包括机器与整套安装好的场地，因此更宽。"},{"word":"vegetation","ipa":"/ˌvedʒɪˈteɪʃən/","tag":"plant cover as a mass","definition":"Plants considered collectively as cover; a plant is one organism, vegetation is the whole stand.","definitionCN":"作为覆盖层考虑的植物总体；plant 是单个生物，vegetation 是整片。"},{"word":"sow","ipa":"/səʊ/","tag":"scatter seed","definition":"To scatter seed over ground; plant usually means setting a seedling or seed into a hole, which is more deliberate.","definitionCN":"把种子撒在地面；plant 通常指把苗或种子放进穴中，更刻意。"},{"word":"embed","ipa":"/ɪmˈbed/","tag":"place inside","definition":"To fix something deeply inside a surrounding mass; the secret sense of plant is close, but embed lacks the intent to deceive.","definitionCN":"把某物深深固定进周围之物；plant 的秘密义接近，但 embed 不含欺骗意图。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin root, the real industrial phrases and the real family.","cn":"正常联想：真实的拉丁词根、真实的工业搭配与真实词族。"},"normal":[{"en":"planta 'cutting' + English use: a shoot set into the ground.","cn":"planta「插条」+ 英语用法：插进土里的枝条。"},{"en":"One word spans a seedling and a factory because both are 'installed works'.","cn":"一个词横跨幼苗与工厂，因为二者都是「被安装起来的东西」。"},{"en":"Fixed phrases: power plant, manufacturing plant, plant a tree.","cn":"固定搭配：发电厂、制造厂、种树。"},{"en":"The verb has a secret sense: plant evidence, plant a bug.","cn":"动词有秘密义：栽赃证据、安装窃听器。"},{"en":"The family runs planting, plantation, planter, implant, transplant.","cn":"同族词包括 planting、plantation、planter、implant、transplant。"}],"abstract":[{"en":"Picture a cutting pressed into wet soil with the heel of a foot.","cn":"想象一根插条被脚跟踩进湿土。"},{"en":"Picture a whole factory that grew out of the idea of 'things set in place'.","cn":"想象一整座工厂从「把东西安置好」这一想法里长出来。"},{"en":"Picture an informant placed inside a group as if set into soil.","cn":"想象一名眼线被安置进一个群体，如同栽进土里。"}]},"examples":[{"en":"The plant needs six hours of direct sun.","cn":"这株植物需要六小时直射阳光。"},{"en":"They plant rice in flooded fields in June.","cn":"他们在六月于水田里插秧。"},{"en":"The old plant was converted into a museum.","cn":"那座旧工厂被改造成了博物馆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「plant（普兰特的苗）」——把苗按进土里，也把工厂安在地上 → 植物、工厂、种植","word":"plant"},"root":"拉丁 planta「芽、枝条、插条」，亦指「脚掌」；两义的先后与联系属假说，未获证明。英语 plant 由古英语借入。","sensesIntro":{"en":"The senses of plant follow one gesture: something is set into a medium and made to stay there, whether soil, a factory site, a position or a group.","cn":"plant 的各个义项沿同一个动作展开：把某物置入某种介质并让它留在那里，无论那是土壤、厂址、位置还是一个群体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shoot pressed into soil, and a works installed on a site.","cn":"核心意象：枝条被按进土里，设施被安装在场地。"},"chain":["ROOTED SHOOT","SET IN SOIL","INSTALLED WORKS","FACTORY","FIRM POSITION","PLACE SECRETLY"],"branches":[{"senses":"01 · 02","en":"THE LIVING LINE: the organism and the act of rooting it.","cn":"活的线：生物与使它扎根的动作。"},{"senses":"03","en":"THE INDUSTRIAL LINE: installed machinery takes the same name as a rooted thing.","cn":"工业线：安装好的机械与扎根之物共用一名。"},{"senses":"04 · 05","en":"THE FIXED LINE: feet, devices and evidence are all set firmly in place.","cn":"固定线：脚、装置与证据都是牢牢置于某处。"},{"senses":"06 · 08","en":"THE SECRET LINE: placing becomes planting without consent.","cn":"秘密线：安放变成未获同意的栽入。"},{"senses":"07","en":"THE COLONY LINE: people are settled like cuttings.","cn":"殖民线：人像插条一样被安置。"}]},"affixes":{"intro":{"en":"Plant is a Latin borrowing, and its prefixes separate setting something in from moving it elsewhere.","cn":"plant 是拉丁借词，其前缀把「置入」与「移往他处」分开。"},"latinIntro":{"en":"Latin planta 'sprout, cutting' gives plant, plantare 'to set' and plantatio; English implant and transplant add direction with Latin prefixes.","cn":"拉丁 planta「芽、插条」衍生 plant、plantare「栽种」与 plantatio；英语的 implant 与 transplant 用拉丁前缀添加方向。"},"items":[{"word":"planta","structure":"planta, plantae (f., first declension)","meaning":"sprout, shoot, cutting","meaningCN":"芽；枝条；插条","example":"Planta named the shoot set into the ground.","exampleCN":"planta 指被插进土里的枝条。"},{"word":"plant","structure":"planta + English noun use","meaning":"a living organism, or an installed works","meaningCN":"活体植物；安装好的设施","example":"The plant was moved into a larger pot.","exampleCN":"这株植物被移进更大的盆。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"the act or place of","meaningCN":"动作或场所","example":"Plantation names both the act and the estate.","exampleCN":"plantation 既指动作，也指庄园。"},{"word":"-er","structure":"-er (English agent suffix)","meaning":"one who or that which does","meaningCN":"做某事的人或物","example":"A planter both plants and holds soil.","exampleCN":"planter 既指种植者，也指盛土的盆。"},{"word":"plantation","structure":"plant + -ation","meaning":"a large planted estate","meaningCN":"种植园","example":"The plantation covered the whole valley.","exampleCN":"种植园覆盖了整个山谷。"},{"word":"planter","structure":"plant + -er","meaning":"a person or container that plants","meaningCN":"种植者；花盆","example":"She filled the planter with compost.","exampleCN":"她往花盆里装满了堆肥。"},{"word":"implant","structure":"im- 'in' + plant","meaning":"to set inside tissue or a mind","meaningCN":"植入；灌输","example":"The device was implanted under the skin.","exampleCN":"装置被植入皮下。"},{"word":"transplant","structure":"trans- 'across' + plant","meaning":"to move a plant or organ elsewhere","meaningCN":"移栽；移植","example":"They transplant the seedlings in May.","exampleCN":"他们在五月移栽幼苗。"},{"word":"planting","structure":"plant + -ing","meaning":"the act of setting plants","meaningCN":"种植","example":"Planting begins after the last frost.","exampleCN":"最后一场霜后开始种植。"}],"latinEntries":[{"word":"planta","structure":"planta, plantae (f., first declension)","meaning":"sprout, shoot; sole of the foot","meaningCN":"芽、枝条；脚掌"},{"word":"plantare","structure":"plantare, plantavi, plantatum (verb, first conjugation)","meaning":"to set in the ground","meaningCN":"栽入土中"},{"word":"plantatio","structure":"plantatio, plantationis (f., third declension)","meaning":"a planting, a plantation","meaningCN":"栽种；种植园"}]}},{"word":"botany","ipa_uk":"/ˈbɒtəni/","ipa_us":"/ˈbɑːtəni/","definition_zh":"植物学；（某地区的）植物志","definition_en":"the scientific study of plants, or the plant life of a particular region","core_image":"一张压制的叶片标本旁，摆着写满学名的标签与一把镊子","scene":"标本室里，学生把压制好的叶片按科属排进柜子，标签上写满学名。 Modern botany began when plants were classified by their parts rather than by their uses.","sceneCN":"这里 botany 指「植物学」（第 1 个义项：研究植物的科学）；句意为当植物按自身构造而非用途被分类时，现代植物学便开始了。","pos":[{"tag":"n.","zh":"植物学；植物区系；植物学著作"}],"collocations":[{"phrase":"field botany","zh":"野外植物学"},{"phrase":"economic botany","zh":"经济植物学"},{"phrase":"medical botany","zh":"药用植物学"},{"phrase":"botany class","zh":"植物学课"},{"phrase":"systematic botany","zh":"系统植物学"},{"phrase":"the botany of a region","zh":"某地区的植物志"}],"forms":[{"label":"原形","form":"botany"},{"label":"无复数","form":"botany"},{"label":"同根形容词","form":"botanic"},{"label":"同根形容词（常见）","form":"botanical"},{"label":"同根名词（植物学家）","form":"botanist"},{"label":"相关副词","form":"botanically"}],"derivatives":[{"word":"botanical","pos":"adj.","zh":"植物学的；植物的"},{"word":"botanist","pos":"n.","zh":"植物学家"},{"word":"botanize","pos":"v.","zh":"采集研究植物"},{"word":"ethnobotany","pos":"n.","zh":"民族植物学"},{"word":"botanic","pos":"adj.","zh":"植物的；植物学的"}],"senses":[{"no":"01","title":"The science of plants","titleCN":"研究植物的科学","definition":"the branch of biology that studies plants and their structure, growth and classification","definitionCN":"研究植物及其结构、生长与分类的生物学分支","example":"Modern botany began with systematic classification.","exampleCN":"现代植物学始于系统分类。","why":"the Greek root names herbage or fodder, so the science is literally the study of what grows as herb.","whyCN":"希腊词根指草料或饲草，因此这门科学字面上就是研究「长成草的东西」。"},{"no":"02","title":"The plant life of a region","titleCN":"某地区的植物区系","definition":"all the plants growing in a particular area, considered as a group","definitionCN":"某一地区生长的全部植物，作为整体来看","example":"The island's botany is dominated by ferns and mosses.","exampleCN":"这个岛的植物以蕨与苔藓为主。","why":"a discipline can lend its name to its subject matter, as geology names the rocks of a region.","whyCN":"学科名可以借给它的研究对象，正如地质学也用来说一个地区的岩石。"},{"no":"03","title":"The subject as taught","titleCN":"作为课程的植物学","definition":"the school or university subject in which plants are studied","definitionCN":"在学校或大学里研究植物的课程","example":"She took botany in her first year and never left the field.","exampleCN":"她一年级修了植物学，从此没离开这个领域。","why":"the noun names the course because the course teaches the science, with no change of form.","whyCN":"名词命名课程，因为课程所教的正是这门科学，词形没有变化。"},{"no":"04","title":"Economic botany","titleCN":"经济植物学（把植物作为资源）","definition":"the study of plants as crops, medicines and raw materials","definitionCN":"把植物作为作物、药材与原料来研究","example":"Economic botany traced the rubber plant from forest to factory.","exampleCN":"经济植物学追溯橡胶植物从森林到工厂的路径。","why":"the field is defined by its use of plants, so an adjective narrows the general noun.","whyCN":"这一领域以植物的用途来界定，因此用形容词收窄了通名。"},{"no":"05","title":"Field botany","titleCN":"野外植物学","definition":"the practical study of plants where they grow, chiefly by identifying them","definitionCN":"在植物生长地进行的实务研究，主要是识别它们","example":"Field botany needs a hand lens and a great deal of patience.","exampleCN":"野外植物学需要放大镜与极大的耐心。","why":"field marks the place of study, the opposite of laboratory botany.","whyCN":"「野外」一词标记研究场所，与实验室植物学相对。"},{"no":"06","title":"Medical botany","titleCN":"药用植物学","definition":"the study of plants used as drugs or remedies","definitionCN":"研究用作药物或疗法的植物","example":"Medical botany supplied most of the early pharmacopoeia.","exampleCN":"早期的药典大多来自药用植物学。","why":"the adjective names the purpose, so the same science is practised for healing.","whyCN":"形容词命名用途，同一门科学因此为治疗服务。"},{"no":"07","title":"A treatise or textbook of botany","titleCN":"植物学著作或教材","definition":"a written work setting out the science of plants","definitionCN":"系统阐述植物科学的著作","example":"He carried an old botany with him on every walk.","exampleCN":"每次散步他都带着一本旧植物学书。","why":"a book is named after its subject, a common shorthand among sciences.","whyCN":"书以主题命名，这是科学领域常见的简写。"},{"no":"08","title":"Systematic botany","titleCN":"系统植物学（分类研究）","definition":"the branch that names, describes and arranges plants into groups","definitionCN":"命名、描述并把植物编入类群的分支","example":"Systematic botany still revises the family tree of flowering plants.","exampleCN":"系统植物学仍在修订被子植物的谱系。","why":"systematic marks the classifying task, which is the oldest part of the science.","whyCN":"「系统的」一词标记分类任务，而这门科学最古老的部分正是分类。"}],"etymology":{"intro":{"en":"Botany is the noun of botanic, from Latin botanicus and Greek botanikos 'of herbs', from botane 'grass, herb, fodder'. The deeper origin of botane is uncertain. Dates are approximate.","cn":"botany 是 botanic 的名词，后者来自拉丁 botanicus 与希腊 botanikos「草本的」，出自 botane「草、草本、饲草」。botane 的更早来源不确定。年代均为约数。"},"items":[{"era":"GREEK BOTANE","en":"Botane meant 'grass, herb, pasture, fodder'; the science therefore began as the study of herbage rather than of all plants.","cn":"botane 意为「草、草本、牧场、饲草」；这门科学因此起初是研究草料，而非一切植物。"},{"era":"GREEK BOTANIKOS","en":"Botanikos 'of herbs' was the adjective used for knowledge about plants and their uses.","cn":"botanikos「草本的」是用于指植物及其用途知识的形容词。"},{"era":"LATIN BOTANICUS","en":"Latin took the Greek adjective as botanicus; the noun botanice followed in Medieval and Renaissance Latin.","cn":"拉丁语把希腊形容词借作 botanicus；名词 botanice 随后出现在中世纪与文艺复兴拉丁语中。"},{"era":"ENGLISH BOTANY","en":"English botany is recorded in the seventeenth century, when plant study separated from medicine and agriculture.","cn":"英语 botany 于 17 世纪有记录，当时植物研究从医学与农业中分离出来。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain: the pre-Greek origin of botane is unresolved; its link to boskein 'to feed' is generally accepted within Greek but the deeper root is reconstructed.","cn":"来源不确定：botane 在希腊语之前的来源没有定论；它与 boskein「喂养」的联系在希腊语内部一般被接受，但更深的词根属重构。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (coining date): the exact first appearance of botany in English print is not settled, so the seventeenth-century dating is approximate.","cn":"来源不确定（造词年代）：botany 首次见于英语印刷的确切时间尚无定论，因此 17 世纪的系年只是约数。"}]},"similar":{"note":{"en":"Group one separates the botanic family by part of speech; group two separates the science from its neighbouring disciplines and from plant cover.","cn":"第一组按词类区分 botanic 词族；第二组区分这门科学与相邻学科及植物覆盖。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"botanical","ipa":"/bəˈtænɪkəl/","tag":"the adjective","definition":"Relating to plants or to botany; the adjective describes, while botany names the field.","definitionCN":"与植物或植物学有关；形容词起描述作用，botany 命名领域。"},{"word":"botanist","ipa":"/ˈbɒtənɪst/","tag":"the person","definition":"A person who studies plants, formed with -ist; the field is botany, the practitioner is a botanist.","definitionCN":"研究植物的人，由 -ist 构成；领域是 botany，从业者是 botanist。"},{"word":"botanize","ipa":"/ˈbɒtənaɪz/","tag":"the activity","definition":"To collect and study plants in the field; it is the verb, not the science.","definitionCN":"在野外采集并研究植物；是动词，而非学科名。"},{"word":"botanic","ipa":"/bəˈtænɪk/","tag":"shorter adjective","definition":"The older adjective form, still used in names such as botanic garden; it is not a noun.","definitionCN":"较老的形容词形式，仍见于「植物园」等名称；它不是名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"biology","ipa":"/baɪˈɒlədʒi/","tag":"the wider science","definition":"The study of all living things; botany is the plant branch of it.","definitionCN":"研究一切生物的科学；botany 是其中研究植物的分支。"},{"word":"horticulture","ipa":"/ˌhɔːtɪˈkʌltʃə/","tag":"growing, not studying","definition":"The practice of growing garden plants; it applies botanical knowledge rather than producing it.","definitionCN":"栽培园林植物的实务；它应用植物学知识，而非生产知识。"},{"word":"flora","ipa":"/ˈflɔːrə/","tag":"the species list","definition":"The plant species of a region or period, usually listed systematically; botany can also name the study of that list.","definitionCN":"某地区或某时期的植物物种，通常系统列出；botany 也可指对这份名录的研究。"},{"word":"vegetation","ipa":"/ˌvedʒɪˈteɪʃən/","tag":"plant cover","definition":"Plants as ground cover, described by structure rather than by species; it is what botany studies, not the study.","definitionCN":"作为地面覆盖的植物，按结构而非物种描述；它是植物学的研究对象，而非这门学科。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek root, the real academic phrases and the real family.","cn":"正常联想：真实的希腊词根、真实的学术搭配与真实词族。"},"normal":[{"en":"botane 'herb' + -y: the study of herbs, now of all plants.","cn":"botane「草本」+ -y：研究草本之学，如今研究一切植物。"},{"en":"The family splits by word class: botany, botanic, botanical, botanist.","cn":"词族按词类分开：botany、botanic、botanical、botanist。"},{"en":"Fixed phrases: field botany, economic botany, medical botany.","cn":"固定搭配：野外植物学、经济植物学、药用植物学。"},{"en":"The subject also names the plants of a place: the botany of an island.","cn":"学科名也指一地植物：某岛的植物志。"},{"en":"Its neighbour is zoology; together they were natural history.","cn":"它的邻居是动物学；二者合起来曾是自然史。"}],"abstract":[{"en":"Picture a pressed leaf beside a label written in careful Latin.","cn":"想象一片压制的叶子，旁边是工整拉丁文的标签。"},{"en":"Picture a walk that turns into a survey because every plant gets a name.","cn":"想象一次散步变成调查，因为每株植物都被取了名。"},{"en":"Picture a library where the shelves are organised by family rather than by use.","cn":"想象一座图书馆，书架按科属而非用途排列。"}]},"examples":[{"en":"Botany and zoology were once taught together as natural history.","cn":"植物学与动物学曾作为自然史一起教授。"},{"en":"The botany of the delta includes more than four hundred species.","cn":"这片三角洲的植物超过四百种。"},{"en":"Economic botany studies how plants become food, fibre and medicine.","cn":"经济植物学研究植物如何变成食物、纤维与药物。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「botan（草）+ y」——研究草与植物的学问 → 植物学","word":"botany"},"root":"希腊 botane「草、草本、饲草」→ botanikos「草本的」→ 拉丁 botanicus → 英语 botany。botane 的更早来源不确定，与 boskein「喂养」的联系在希腊语内部一般被接受。","sensesIntro":{"en":"Eight senses of botany move from the science itself to the plants it studies, the course that teaches it, its applied branches and the book that records it.","cn":"botany 的八个义项从这门科学本身，移向它所研究的植物、教授它的课程、它的应用分支，以及记录它的书。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pressed leaf and a label written in Latin, side by side.","cn":"核心意象：一片压制的叶子与一张拉丁文标签并排放着。"},"chain":["STUDY OF PLANTS","PLANT LIFE OF A PLACE","SCHOOL SUBJECT","APPLIED USE","FIELD WORK","CLASSIFICATION"],"branches":[{"senses":"01 · 02","en":"SCIENCE AND SUBJECT MATTER: the discipline lends its name to the plants it studies.","cn":"学科与对象：学科名借给它所研究的植物。"},{"senses":"03 · 07","en":"TAUGHT AND WRITTEN: a course and a book both carry the name of the science.","cn":"教与写：课程与书都以这门科学命名。"},{"senses":"04 · 06","en":"APPLIED BRANCHES: crops and medicines narrow the field by purpose.","cn":"应用分支：作物与药材按用途收窄领域。"},{"senses":"05","en":"THE FIELD: identification outdoors is the oldest practical skill.","cn":"野外：户外识别是最古老的实务技能。"},{"senses":"08","en":"THE ORDER: naming and grouping is the backbone of the science.","cn":"秩序：命名与归群是这门科学的骨干。"}]},"affixes":{"intro":{"en":"Botany is a Greek adjective turned into an English noun, and its family names the field, the practitioner and the activity.","cn":"botany 是希腊形容词转成的英语名词，其词族命名领域、从业者与活动。"},"latinIntro":{"en":"Greek botane 'herb' gives botanikos and Latin botanicus; English botany, botanic, botanical and botanist all descend from that adjective.","cn":"希腊 botane「草本」衍生 botanikos 与拉丁 botanicus；英语的 botany、botanic、botanical 与 botanist 都出自那个形容词。"},"items":[{"word":"botane","structure":"botane (Greek noun, 'grass, herb, fodder')","meaning":"herb, pasture","meaningCN":"草本；牧草","example":"The root names what grows as herb.","exampleCN":"这个词根命名长成草的东西。"},{"word":"-ikos","structure":"-ikos (Greek adjective suffix)","meaning":"of or belonging to","meaningCN":"属于……的","example":"Botanikos means of herbs.","exampleCN":"botanikos 意为草本的。"},{"word":"-y","structure":"-y (English noun suffix from Latin -ia)","meaning":"the study or practice of","meaningCN":"……之学或实践","example":"Botany names the study of plants.","exampleCN":"botany 命名研究植物的学问。"},{"word":"botanic","structure":"botanikos + Latin -us","meaning":"relating to plants","meaningCN":"植物的","example":"The botanic garden holds living collections.","exampleCN":"植物园收藏活体植物。"},{"word":"botanical","structure":"botanic + -al","meaning":"relating to botany","meaningCN":"植物学的","example":"Botanical names follow international rules.","exampleCN":"植物学名遵循国际规则。"},{"word":"botanist","structure":"botany + -ist","meaning":"a student of plants","meaningCN":"植物学家","example":"The botanist keyed out the unknown sedge.","exampleCN":"植物学家检索出了那种未知的莎草。"},{"word":"botanize","structure":"botany + -ize","meaning":"to collect plants in the field","meaningCN":"野外采集植物","example":"They botanized the ridge before the road went in.","exampleCN":"在修路之前，他们在山脊采集植物。"},{"word":"ethnobotany","structure":"ethno- + botany","meaning":"the study of people's use of plants","meaningCN":"民族植物学","example":"Ethnobotany records which plants a village uses for medicine.","exampleCN":"民族植物学记录一个村庄用哪些植物做药。"},{"word":"botanically","structure":"botanical + -ly","meaning":"in botanical terms","meaningCN":"从植物学角度","example":"Botanically, a tomato is a fruit.","exampleCN":"从植物学上看，番茄是果实。"}],"latinEntries":[{"word":"botane","structure":"botane (Greek, f., 'grass, herb')","meaning":"grass, herb, fodder","meaningCN":"草；草本；饲草"},{"word":"botanicus","structure":"botanicus, botanica, botanicum (adjective, Latin from Greek)","meaning":"of herbs, botanical","meaningCN":"草本的；植物的"},{"word":"botanice","structure":"botanice (f., Medieval Latin, from Greek botanike)","meaning":"the study of herbs","meaningCN":"草本之学；植物学"}]}}]);
